/* generado por build: clases de Expedición SEN6 + respuestas de la radio de la base (sin IA) */
window.LECCIONES={"base": [{"id": "loom-0630a3652ddd4fabacecc6f04f2ee8b0", "titulo": "Por qué Youtube Faceless?", "min": 9, "loom": "0630a3652ddd4fabacecc6f04f2ee8b0", "resumen": "Explica por qué YouTube faceless es un gran negocio frente a otras plataformas: más permanencia y menos cambios de algoritmo, un activo digital que acumula valor y se puede vender o heredar, videos que pagan durante años y una barrera de entrada mucho más baja gracias a la IA.", "ideas": ["La visibilidad no se mide solo por el alcance sino por el tiempo que te miran: YouTube tiene mucha más permanencia que Instagram o TikTok, menos cambios de algoritmo, la tasa de clic en enlaces más alta y más ingresos.", "Un canal es como bienes raíces digitales: un activo que da flujo de caja mensual, gana valor con el tiempo, es escalable (1, 2, 3 o 10 canales) y se puede vender (por ejemplo, en Flippa) o heredar; no alquilás atención, la acumulás.", "Se monetiza con el Programa de Socios de YouTube y además construyendo alrededor de la audiencia productos digitales, membresías, cursos y merchandising.", "Un video puede pagar durante años y volver a generar ingresos si su tema vuelve a ser tendencia (el profe tiene videos que le siguen dando 400-500 dólares sin hacer nada); es ingreso pasivo por video, pero el negocio no es del todo pasivo."], "pdf": "pdf/base-1.pdf"}, {"id": "loom-a8b6e53a6f2a4dd88700f24f1711b93a", "titulo": "Regla del 6o", "min": 6, "loom": "a8b6e53a6f2a4dd88700f24f1711b93a", "resumen": "Presenta la regla del 6O: dividir el año en seis períodos de dos meses, que son seis oportunidades de lanzar y estudiar un canal, con el objetivo de acertar al menos en dos canales potentes que rindan en el Q3 y el Q4. Sirve para manejar expectativas y planificar la estrategia anual.", "ideas": ["El año da seis oportunidades de dos meses cada una para hacer un canal y estudiarlo (entre 30 y 60 videos por ciclo); lo que importa es el tiempo, la consistencia y las expectativas.", "No se trata de ser el primero sino el más potente: es mejor monetizar al tercer mes un canal que da 3.000 dólares que en 15 días uno que da 100.", "La meta es acertar en al menos 2 canales muy buenos; si pasás el tercer intento sin monetizar, hay que revisar si le estás dedicando horas o pedir ayuda en el plan ETHER.", "Los ingresos varían por trimestre: Q1 y Q2 suelen ser bajos (baja el RPM), el Q3 es intermedio y el Q4 (octubre a diciembre) es el que más paga; monetizar tarde en el año suele ser más difícil pero arranca con ingresos altos."], "pdf": "pdf/base-2.pdf"}, {"id": "loom-443f18d40fdf4d5da7f7392d34c09349", "titulo": "Requisitos de monetización", "min": 5, "loom": "443f18d40fdf4d5da7f7392d34c09349", "resumen": "Explica qué es la monetización (entrar al Programa de Socios de YouTube), los requisitos para canales largos y de shorts, la revisión de políticas, el cobro mediante AdSense y los otros beneficios del canal. Sirve para saber qué metas cumplir para empezar a ganar dinero.", "ideas": ["Requisitos para formato largo: 1.000 suscriptores y 4.000 horas de visualización pública (no cuentan los videos ocultos ni privados) en los últimos 12 meses.", "En shorts se necesitan 10 millones de vistas públicas en los últimos 90 días, no en el año.", "Al llegar a los requisitos, YouTube revisa con IA y con humanos que el canal cumpla las políticas de monetización y las normas de la comunidad, que pueden cambiar: hay que leerlas seguido.", "Para cobrar hay que crear y validar una cuenta de AdSense; YouTube paga entre el 21 y el 26 de cada mes las vistas del mes anterior (ingresos por anuncios, más si el espectador hace clic)."], "pdf": "pdf/base-3.pdf"}, {"id": "loom-c33d31426ab348dcbffaba15dd5fb6ed", "titulo": "Nicho vs. Temática", "min": 12, "loom": "c33d31426ab348dcbffaba15dd5fb6ed", "resumen": "Explica la diferencia entre temática y nicho (nicho, subnicho y micronicho) y la fórmula de SEN6: subnicho o micronicho con volumen + una estética particular.", "ideas": ["La temática es solo el tema; el nicho es una audiencia con interés común y comportamientos específicos: no se crea, se encuentra.", "Nicho = audiencia masiva (deportes, tecnología); subnicho = interés más específico (fútbol, tenis); micronicho = audiencia muy concreta (tenis para mujeres).", "Trabajar en subnichos o en micronichos con volumen; si el subnicho no es popular (waterpolo), su micronicho no sirve (waterpolo para niños).", "Fórmula SEN6: subnicho o micronicho + estética particular; la estética cambia la audiencia y por lo tanto el nicho (ej. psicología oscura explicada con stickman, arte con monos vs. documental)."], "pdf": "pdf/base-4.pdf"}], "mapa": [{"id": "loom-563ca314c97848ccbf4bed20053e3468", "titulo": "El Método del SEN6", "min": 15, "loom": "563ca314c97848ccbf4bed20053e3468", "resumen": "Explica en pizarra el método SEN6: buscar en cualquier mercado (idioma) un canal de referencia exitoso, extraer con IA sus estructuras ganadoras ('masters'), cambiar el ángulo para la misma audiencia, optimizar con métricas y luego monetizar y escalar. Sirve como mapa general del método antes de la investigación.", "ideas": ["Los mercados son idiomas y dentro de cada uno hay grupos con intereses comunes; se busca un canal de referencia bien estructurado, en un grupo grande y con vistas, en cualquier idioma.", "No se copia, se extraen estructuras: con IA se sacan los 'masters' (guion master, patrones de miniaturas, títulos, hooks, momentos de los CTA e incluso el modelo de negocio) del canal de referencia.", "Recomienda empezar en español: hay menos competencia que en inglés aunque pague menos, y es el idioma en el que podés entender tus guiones y a tu audiencia.", "Cambiar el ángulo (estilo, tono o elemento que haga único el canal) para hablarle al mismo grupo; ejemplo: un canal que analiza pinturas y otro que hace lo mismo con esculturas, con 6 videos, 7.000 suscriptores y 2.200 dólares."], "pdf": "pdf/mapa-1.pdf"}, {"id": "loom-a776d7477179429cbbc715cf1bff9437", "titulo": "Requisitos del nicho ideal", "min": 4, "loom": "a776d7477179429cbbc715cf1bff9437", "resumen": "Lista de requisitos que debe cumplir un canal de referencia para validar un nicho ideal, y cómo se aplican luego (con más flexibilidad) a la competencia en tu idioma.", "ideas": ["El canal de referencia debe cumplir todos los requisitos sin flexibilidad; la competencia en tu mercado puede ser más flexible.", "Requisitos: 6 meses de antigüedad o menos, entre 1.000 y 50.000 suscriptores y más de 1 millón de vistas mensuales.", "RPM conveniente: arriba de 3 en inglés y alrededor de 2 en español; varía en el tiempo y los nichos más competidos suelen pagar más.", "Tiene que ser factible de igualar o mejorar en producción (voces, miniatura, animaciones, guiones)."], "pdf": "pdf/mapa-2.pdf"}, {"id": "loom-a832de2288f44a6c915a3012cb27ba7f", "titulo": "Cuenta Educada", "min": 7, "loom": "a832de2288f44a6c915a3012cb27ba7f", "resumen": "Método de la cuenta educada: crear una cuenta de Gmail solo para YouTube y entrenar al algoritmo suscribiéndote a canales faceless para que te recomiende canales nuevos en auge sin pagar herramientas.", "ideas": ["Se entrena al algoritmo para que muestre solo canales faceless; tarda unos días y es el método favorito del profe porque no requiere herramientas pagas.", "Crear un Gmail con un nombre que recuerde que es la cuenta educada (ej. cuentaeducada.maximo) y usarlo solo para encontrar nichos.", "Si el inicio aparece negro, entrar a Shorts y volver a Principal; suscribirse solo a canales donde no aparece ninguna persona y refrescar para que aparezcan más.", "Entrar todos los días; además de suscribirte, dar like y comentar acelera el proceso."], "pdf": "pdf/mapa-3.pdf"}, {"id": "loom-583c655265fa4fed93cf6919ed0e4ae5", "titulo": "Ejemplo NexLev", "min": 26, "loom": "583c655265fa4fed93cf6919ed0e4ae5", "resumen": "Tutorial de NexLev para encontrar nichos y canales de referencia faceless con outliers recientes, canales similares y filtros avanzados.", "ideas": ["NexLev cuesta unos 42 euros por mes; recomendado cuando ya tenés canales monetizados.", "El mejor punto de partida son los 'outliers recientes' (últimas 24 h) del buscador de nichos, que se renuevan a diario.", "Hacé doble chequeo del estado de monetización: en canales con pocos videos NexLev suele fallar.", "Filtros recomendados en Long Form Channels: avanzado, monetizado, faceless, sin contenido para niños, sin shorts, menos de 50.000 suscriptores y alrededor de 1-2 millones de vistas."], "pdf": "pdf/mapa-4.pdf"}], "equipo": [{"id": "loom-20302217f8cb40c3a371e41a4a7ab394", "titulo": "Abrir un canal", "min": 7, "loom": "20302217f8cb40c3a371e41a4a7ab394", "resumen": "Tutorial para crear una cuenta de Gmail y abrir un canal de YouTube, dejando el nombre y el identificador para la clase siguiente, donde se eligen con IA.", "ideas": ["Creá la cuenta de Gmail 'para uso personal'; las cuentas más antiguas generan más confianza porque YouTube ya tiene tu historial.", "No crees el canal hasta ver la clase siguiente: el nombre y el identificador se eligen con IA.", "El identificador se escribe sin la arroba (por ejemplo, HormigaReyESP).", "No subas foto al crear el canal; logo, banner y descripción van en la clase siguiente."], "pdf": "pdf/equipo-1.pdf"}, {"id": "loom-2f5e37f7f9af4c8c810414cac4a2a577", "titulo": "Calentamiento de cuenta", "min": 7, "loom": "2f5e37f7f9af4c8c810414cac4a2a577", "resumen": "Explica cómo calentar la cuenta antes de subir videos: actuar como humano durante 8-15 días en tu nicho para que YouTube confíe en el canal, y producir mientras tanto.", "ideas": ["Durante 8 a 15 días (recomienda 15) mirá al menos 5 videos por día del nicho completos, con volumen y viendo el pre-roll, dale like, suscribite y dejá comentarios elaborados y naturales.", "Hacé búsquedas del tema y mirá shorts del nicho; no subas videos antes del día 15.", "Comprar cuentas viejas (ej. agedfiles.com) es posible pero no lo recomienda: heredás el mal historial de la cuenta.", "Aprovechá esos días para producir: tené al menos 5 videos hechos (2-3 si son muy elaborados) para la subida 3-2-1: 3 videos el primer día, luego 2 y después la frecuencia normal."], "pdf": "pdf/equipo-2.pdf"}], "carga": [{"id": "loom-6fe7cca0d5534ffebce3bce0bc71181f", "titulo": "Guión Master", "min": 26, "loom": "6fe7cca0d5534ffebce3bce0bc71181f", "resumen": "Cómo extraer la estructura y los patrones de los guiones más exitosos de un canal de referencia y convertirlos en un 'guion maestro' (archivo o proyecto en Claude) para generar guiones propios.", "ideas": ["No se copia el guion: se extrae la estructura de los 8 videos más populares del canal de referencia (pestaña videos > más populares); si las estructuras varían, se extraen patrones comunes (curiosidad al inicio, primera persona, tipo de CTA).", "Forma manual: copiar las transcripciones (botón de NexLev en YouTube o TurboScribe), pegarlas en una IA y pedir 'detecta la estructura exitosa; si son diferentes, dame las mejores prácticas y patrones'; guardar el resultado en Word como guion maestro.", "Forma recomendada: en Claude Code, 'Usa NexLev para estudiar las estructuras exitosas de los mejores 8 guiones del canal' + la URL del canal, y luego 'compila esta info en un archivo .md' (equivale a crear una skill).", "Crear un proyecto en Claude, subir ese archivo y poner como instrucción 'Haz guiones de X palabras siempre respetando la estructura de los documentos de archivo' (10 min ≈ 1.250-1.500 palabras); pedir que entregue sin marcas de tiempo ni títulos, solo párrafos."], "pdf": "pdf/carga-1.pdf"}, {"id": "loom-bd3ba7974d3940c7af5351f7f504c0a8", "titulo": "Retención", "min": 29, "loom": "bd3ba7974d3940c7af5351f7f504c0a8", "resumen": "Explica qué es realmente la retención según los cambios de YouTube 2025-2026, cómo leer la gráfica de retención de público en Studio y cómo diferenciarla del tiempo de sesión, la satisfacción del espectador y la AVD. Sirve para construir retención desde la idea, el guion y la edición.", "ideas": ["La retención se ve en Analytics > Participación > Retención de público; los primeros 30 segundos (zona gris) miden la promesa del video y en faceless deberían quedar arriba de 75-80%; menos indica una promesa floja o clickbait.", "Llegar al final con al menos 33% de la audiencia, porque ahí van las pantallas finales y tarjetas que mandan a otro video y alargan el tiempo de sesión.", "Hay cuatro curvas: plana (lo ideal), descenso gradual (pierden interés), subidas (capítulos, repeticiones o compartidos con marca de tiempo) y caídas (omiten o abandonan, contenido aburrido).", "Desde 2025 YouTube mide la satisfacción del espectador: si después de tu video la persona sigue en tu canal o en YouTube, el video se impulsa; por eso pensar series de videos enlazados, no videos sueltos."], "pdf": "pdf/carga-2.pdf"}, {"id": "loom-4379e9ff7d4c46639f0bdd445e57352b", "titulo": "Narración IA", "min": 27, "loom": "4379e9ff7d4c46639f0bdd445e57352b", "resumen": "Clase teórica y práctica de narración con IA: cómo funcionan los modelos TTS (fonemas, prosodia, espectrograma, vocoder, tokens) y cómo generar la voz del guion en Kukarella y ElevenLabs.", "ideas": ["El modelo no entiende ortografía sino fonemas y prosodia: la puntuación es la herramienta gratuita para que no suene robótico; escribí los términos en inglés, números y siglas como suenan.", "Generá por párrafos: ahorrás dinero, evitás alucinaciones (cambios de acento o de idioma) y regenerás solo la parte que falla.", "Fijá estabilidad, similitud y velocidad y no los toques entre párrafos ni entre guiones: la consistencia entre clips es igual a sonido profesional; en Kukarella no toques el pitch.", "Clonación: dale mucho audio (fine tuning), evitá el zero shot y no clones voces ajenas sin autorización."], "pdf": "pdf/carga-3.pdf"}, {"id": "loom-5f3acdd00a824748914f69ecdb40b6b3", "titulo": "Edición", "min": 40, "loom": "5f3acdd00a824748914f69ecdb40b6b3", "resumen": "Tutorial de producción del video más común en faceless (fotos o clips más locución): sacar la estructura del guion del canal de referencia, generar la voz con IA y editar en CapCut con movimientos, textos, transiciones, filtros y exportación. Sirve para dejar listo el primer material del canal.", "ideas": ["Extraer los guiones de los 5-6 videos más populares del canal de referencia, pasarlos a PDF y pedirle a ChatGPT la estructura; guardarla como PDF o prompt maestro y adjuntarla cada vez que se pide un guion nuevo.", "El video tiene que durar al menos 8 minutos para poder monetizarse; si la locución queda corta, pedir más párrafos al guion y regenerar la voz.", "Si se usan fragmentos de documentales: espejarlos, no pasar de 5 segundos por fragmento, cambiar el orden y agregar voz y valor para evitar problemas de copyright.", "Marcar 'contenido sintético alterado' cuando la IA simula personas reales; si no se simula a nadie, no es necesario."], "pdf": "pdf/carga-4.pdf"}], "senal": [{"id": "loom-7c314b03445f41c599162b37d400588d", "titulo": "Miniaturas", "min": 15, "loom": "7c314b03445f41c599162b37d400588d", "resumen": "Clase introductoria sobre miniaturas: qué son, sus medidas y su función junto al título, la anatomía de una miniatura que funciona, errores comunes y herramientas para hacerlas.", "ideas": ["El delivery (miniatura, título y descripción) es el 50% y el video, el otro 50%; la miniatura mide 1280x720 px (16:9).", "La miniatura se percibe en unos 0,3 segundos y empuja el CTR de las primeras horas, que es lo que define si YouTube muestra el video a más gente.", "Anatomía: un solo foco, alto contraste, de 1 a 3 palabras (máximo 5) o directamente sin texto si tu nicho funciona así, y un gancho de curiosidad que complemente al título sin repetirlo.", "Caras con emoción real; la mirada o el gesto del personaje hacia el texto dirige la atención. Atrae más una persona con los ojos visibles, después los colores fuertes (rojo, amarillo) y después el texto."], "pdf": "pdf/senal-1.pdf"}, {"id": "loom-90af2f9612954d9d9c3bbb02d7e00b89", "titulo": "Títulos", "min": 28, "loom": "90af2f9612954d9d9c3bbb02d7e00b89", "resumen": "Explica cómo escribir títulos para el YouTube semántico de 2026: lenguaje humano, palabras clave y long tail al principio, una sola palabra emocional y título y miniatura complementarios.", "ideas": ["YouTube es semántico: entiende la intención, así que escribí como un humano, sin repetir términos (edición/editar, tips/tutorial) ni saturar de keywords.", "Poné la keyword o long tail en los primeros 30 a 40 caracteres (ej. 'Nepal:' al inicio) y apuntá a 50-60 caracteres en total para que no se corte en el celular.", "Estructura sugerida: keyword + dos puntos + promesa o gancho; usá una sola palabra de poder, 'sin + objeción' (sin experiencia previa, sin software de pago) y el año (desde agosto-septiembre ya conviene el año siguiente).", "Usá yo, tú o vos y nunca 'ustedes'; usá números impares y evitá redondos o mitades (5, 25, 50, 500)."], "pdf": "pdf/senal-2.pdf"}], "ataque": [{"id": "loom-d42d4c2e72cc48aa88daa8309437015f", "titulo": "Estrategia de subida 3-2-1", "min": 14, "loom": "d42d4c2e72cc48aa88daa8309437015f", "resumen": "Presenta la estrategia de subida 3-2-1 y sus variantes según la dificultad del nicho (baja, media o alta), para darle al algoritmo la mayor cantidad de datos en el menor tiempo y no gastar de más en nichos caros sin validar.", "ideas": ["Nichos de baja dificultad (videos de unos 10 minutos que se editan en 1-2 horas, con fotos o stock más voz en off): 3-2-1, es decir, día 1 tres videos (mañana, mediodía y prime de 18-19 h), día 2 dos (mañana y prime), día 3 uno a las 18-19 h, y desde el día 4 la frecuencia promedio del nicho o del canal de referencia.", "Nichos de dificultad media (videos elaborados de 1-3 días de trabajo): subir tres videos en los tres primeros días a las 18-19 h y luego seguir la frecuencia del nicho; si aparece un outlier, subir lo más posible para aprovechar la demanda (un ejemplo pasó a ganar 12.000 dólares el primer mes).", "El horario de 18-19 h es el de la audiencia objetivo, no el tuyo: si estás en Argentina y el canal apunta a Estados Unidos, subir a las 18-19 h de allá.", "Nichos de alta dificultad (videos de 200 a 400 dólares, personajes consistentes, mucha IA): validar primero la idea con shorts, TikTok o Instagram y recién después producir largos; después se puede subir cada 15 días o incluso cada mes."], "pdf": "pdf/ataque-1.pdf"}, {"id": "loom-ebfb6697e1ae4f739e8a9418858f57b5", "titulo": "Mis primeros videos", "min": 22, "loom": "ebfb6697e1ae4f739e8a9418858f57b5", "resumen": "Recomendaciones de mentalidad y métricas para los primeros videos de un canal recién lanzado: cómo YouTube prueba un video con audiencias cada vez más grandes, qué métricas mirar primero y cómo diagnosticar problemas con la matriz CTR/retención. Sirve para leer los datos con paciencia y mejorar video a video.", "ideas": ["YouTube no castiga: entiende el tema (título, descripción, transcripción, capítulos y canal), muestra el video a un grupo chico, mide clic, retención, si siguen viendo y si interactúan, y según eso expande o frena.", "Al principio mirar las impresiones, que deben subir como un serrucho con pisos cada vez más altos; si después de 30-40 videos no pasás de 200 impresiones o es una línea plana, algo anda mal (revisar con el video de la cuenta).", "El CTR depende de las impresiones y al principio no es fiable; es normal que baje cuando el video llega a público nuevo; por debajo de 2-3% es alarmante y conviene cambiar miniatura o título. La retención sí se puede medir desde el inicio.", "Matriz de diagnóstico: buen video con mal empaque → cambiar título y miniatura; CTR y retención bajos → revisar el tema y las keywords; CTR alto y buena retención → iterar la fórmula; CTR alto y retención baja → arreglar el guion."], "pdf": "pdf/ataque-2.pdf"}]};
window.RESPUESTAS=[{"id": "g1-001", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Por qué YouTube y no TikTok o Instagram?", "variantes": ["¿por qué youtube?", "¿no es mejor tiktok?", "¿instagram o youtube?", "¿qué tiene youtube de especial?"], "respuesta": "Porque la visibilidad no se mide solo por cuánta gente te ve, sino por cuánto tiempo te mira. YouTube tiene mucha más permanencia que Instagram o TikTok, cambia menos el algoritmo, tiene la tasa de clic en enlaces más alta y paga más. Y si ya tenés redes, la idea es llevar a esa gente hacia YouTube, que es donde pasa más tiempo con vos. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false, "video": {"id": "_sa_jqSBsoM", "titulo": "Descubre por qué YouTube es el mejor negocio en 2026", "url": "https://www.youtube.com/watch?v=_sa_jqSBsoM"}}, {"id": "g1-002", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Qué significa que un canal es un activo?", "variantes": ["¿por qué dicen que un canal es como una propiedad?", "¿qué es eso de bienes raíces digitales?", "¿un canal gana valor con el tiempo?", "¿se puede vender un canal?"], "respuesta": "Un canal funciona como bienes raíces digitales: te da un flujo de caja mensual, gana valor con el tiempo, lo podés escalar a 2, 3 o 10 canales y hasta venderlo, por ejemplo en Flippa, o heredarlo. No alquilás atención, la acumulás. Por eso la audiencia que vas juntando ya es un activo importantísimo, y un solo canal, o incluso un solo video, puede devolverte todo el esfuerzo. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false, "video": {"id": "fdpYd4U9zrA", "titulo": "Así se hacen NEGOCIOS en Youtube y tal vez no lo sabías...", "url": "https://www.youtube.com/watch?v=fdpYd4U9zrA"}}, {"id": "g1-003", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Esto es ingreso pasivo?", "variantes": ["¿es plata pasiva?", "¿después no tengo que hacer nada?", "¿youtube es pasivo?", "¿un video paga para siempre?"], "respuesta": "Un video puede pagar durante años y hasta volver a generar ingresos si su tema vuelve a ser tendencia: es ingreso pasivo por video. Pero el negocio no es del todo pasivo. Siempre hay que investigar, ver cómo va el nicho, si salieron canales nuevos y seguir subiendo. Lo que sí se puede es automatizar y armar un sistema, como el dueño de una agencia de contenidos. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false}, {"id": "g1-004", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Cómo se gana plata con un canal de YouTube?", "variantes": ["¿de dónde sale la plata?", "¿cómo paga youtube?", "¿solo se gana con anuncios?", "¿qué formas de ingreso hay?"], "respuesta": "La vía principal es el Programa de Socios de YouTube: cuando monetizás, cobrás por los anuncios de tus videos. Además, alrededor de la audiencia se pueden construir productos digitales, membresías, cursos y merchandising. Al investigar, fijate si los canales de tu nicho solo viven de YouTube o también venden algo o tienen membresías (aparece el botón Unirse). Esto lo ves en las clases «Por qué YouTube Faceless» y «Requisitos de monetización».", "silver": false, "video": {"id": "_sa_jqSBsoM", "titulo": "Descubre por qué YouTube es el mejor negocio en 2026", "url": "https://www.youtube.com/watch?v=_sa_jqSBsoM"}}, {"id": "g1-005", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Tengo que mostrar la cara?", "variantes": ["¿necesito salir en cámara?", "¿se puede sin mostrarme?", "¿qué es faceless?", "¿y si soy tímido?", "¿canal personal o faceless?"], "respuesta": "No. Faceless significa justamente que no mostrás la cara, y eso es una ventaja: tenés anonimato, libertad y podés delegar y escalar sin que tu identidad sea el cuello de botella. En SEN6 se arranca por faceless porque son canales mucho más escalables que los personales. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false, "video": {"id": "ULem7Sy6TYM", "titulo": "Youtube FACELESS vs MARCA PERSONAL | Con cuál debes empezar?", "url": "https://www.youtube.com/watch?v=ULem7Sy6TYM"}}, {"id": "g1-006", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Puedo hacer un canal hecho 100% con IA?", "variantes": ["¿la ia hace todo el video?", "¿youtube desmonetiza lo hecho con ia?", "¿qué parte tiene que ser humana?", "¿sirve un canal solo de ia?"], "respuesta": "La IA hace que producir sea más barato y rápido, pero el proceso tiene que mostrar presencia humana. Si todo sale igual, YouTube lo toma como contenido de bajo valor y no lo monetiza, o lo desmonetiza después. Guiones con tu perspectiva, edición variada y miniaturas con estilo pero no idénticas. La IA te ayuda; el tono, la voz y la mirada tienen que ser tuyos. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false, "video": {"id": "kxU3WahtJQ4", "titulo": "La mentira de los canales Faceless con IA (no saberlo te lleva a la DESMONETIZACIÓN)", "url": "https://www.youtube.com/watch?v=kxU3WahtJQ4"}}, {"id": "g1-007", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Conviene más YouTube o dropshipping?", "variantes": ["¿youtube o ecommerce?", "¿qué negocio arranco primero?", "¿youtube o tienda online?", "¿por qué youtube y no otro negocio?"], "respuesta": "Max recomienda YouTube primero: el costo para empezar es muy bajo, no tenés stock, no hay reembolsos, no configurás pasarelas de pago, no tenés clientes ni proveedores y lleva menos tiempo. Además puede ser tu base para otros proyectos. Y si un canal no funciona, hacés otro; en una tienda el problema sería mucho más grande. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false}, {"id": "g1-008", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Hace falta invertir plata para arrancar?", "variantes": ["¿es gratis empezar?", "¿cuánto tengo que invertir?", "¿se puede sin gastar nada?", "¿alcanza con herramientas gratis?"], "respuesta": "La barrera de entrada es bajísima comparada con un negocio tradicional, pero no es cero. Si tu formato depende de IA generativa, no se sostiene con créditos gratuitos: hay una inversión real. Por eso, antes de elegir, pensá si podés sostener ese costo varios meses sin retorno. Hay formatos más baratos, como los canales con fotos de la web. Esto lo ves en la clase «Por qué YouTube Faceless».", "silver": false, "video": {"id": "50A3R42ckBI", "titulo": "Si comenzara un canal de YOTUBE FACELESS con IA en 2026 haría esto", "url": "https://www.youtube.com/watch?v=50A3R42ckBI"}}, {"id": "g1-009", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Cuántas horas por día le tengo que dedicar?", "variantes": ["¿puedo hacerlo trabajando?", "¿cuánto tiempo necesito?", "¿tengo que dejar mi trabajo?", "¿alcanza con una hora por día?", "avanzo muy lento, ¿está mal?"], "respuesta": "Con 1 a 2 horas al día alcanza para tener un canal. No hace falta dejar tu trabajo: Max no lo dejó con su primer canal y no lo recomienda. Lo que sí ayuda es organizarte, tener horarios de subida claros y adelantarte unos videos para no vivir con la presión diaria. Y si vas lento, tranqui: YouTube no premia el tiempo, premia la consistencia y una buena investigación. Importa cuánto podés sostener tu ritmo. Esto lo ves en la clase «Regla del 6O».", "silver": false, "video": {"id": "Ds5g7i3Lo6M", "titulo": "Tips de un Creador Exitoso de Youtube Faceless I Pablo Revela sus Secretos", "url": "https://www.youtube.com/watch?v=Ds5g7i3Lo6M"}}, {"id": "g1-010", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Cuánto tarda en dar resultados?", "variantes": ["¿en cuánto tiempo voy a ganar?", "¿es rápido?", "¿cuándo empiezo a ver plata?", "¿esto es para hacerse rico rápido?", "¿conviene monetizar rápido aunque gane poco?"], "respuesta": "No es un negocio de velocidad, es de constancia. Nada bueno se hace en poco tiempo: es como conseguir una receta exacta, no sacar una pizza rápido. Cada uno tiene su camino y nadie te puede prometer plazos. Lo que importa es el tiempo, la consistencia y las expectativas: date ciclos completos para aprender y medir. No se trata de ser el primero sino el más potente: mejor monetizar al tercer mes un canal que rinde mucho que en 15 días uno que da muy poco. Esto lo ves en la clase «Regla del 6O».", "silver": false, "video": {"id": "e8_mgzxssuk", "titulo": "La REGLA 6o: El salvavidas para comenzar a hacer Canales Automatizados de YT", "url": "https://www.youtube.com/watch?v=e8_mgzxssuk"}}, {"id": "g1-011", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "Me trabo analizando todo y no arranco, ¿qué hago?", "variantes": ["tengo parálisis por análisis", "quiero que todo salga perfecto", "¿lanzo aunque no esté perfecto?", "me da miedo equivocarme"], "respuesta": "Si te pasa, es que estás emprendiendo: les pasa a todos. El consejo es arrancar y equivocarte barato, porque en una de esas equivocaciones ya no te vas a equivocar. Meter las manos en la masa acelera muchísimo el aprendizaje. La autenticidad y hacer, probar y volver a probar pesan más que la producción perfecta. Eso sí, la investigación del nicho merece paciencia.", "silver": false}, {"id": "g1-012", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "Me cuesta mantener la motivación, ¿cómo sigo?", "variantes": ["estoy desmotivado", "pierdo las ganas", "siento que no avanzo", "me frustro", "¿cómo no abandonar?"], "respuesta": "Enfocate en el proceso, no en el resultado. Calma, paciencia y consistencia: agarrate al sistema. Lau cuenta que sus primeros tres canales fracasaron y que todo cambió cuando dejó de compararse y entendió que cada fracaso mejoraba su proceso. Celebrá cada paso, aunque sea chico, porque el que camina también llega. Y disfrutá el camino: sin disfrutarlo, todo se vuelve cuesta arriba.", "silver": false}, {"id": "g1-013", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿El objetivo es monetizar?", "variantes": ["¿todo pasa por monetizar?", "solo pienso en monetizar", "¿qué es lo más importante?", "¿la meta es la plata?"], "respuesta": "La monetización no es el objetivo, es la consecuencia de tu proceso. El objetivo real es dominar una metodología estructurada, medible, optimizable y repetible. Cuando la dominás, lo que lograste una vez lo podés repetir. Obsesionarte con monetizar genera ansiedad y te impide leer bien cómo rinde tu canal. Además, el objetivo va más allá: aportar valor, construir audiencia y aprender.", "silver": false}, {"id": "g1-014", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "Me abruma la cantidad de información, ¿por dónde empiezo?", "variantes": ["no sé por dónde arrancar", "es mucho contenido", "me perdí", "estuve desconectado, ¿cómo retomo?"], "respuesta": "Arrancá por el principio y andá a tu ritmo, sin querer abarcar todo de golpe. Una cosa a la vez: ver una clase, aplicarla y recién después seguir. Si estuviste un tiempo desconectado, retomá desde donde quedaste y mirá solo lo que necesitás para avanzar. Sumar más información sin aplicar no te acerca; la acción sí.", "silver": false}, {"id": "g1-015", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "Tengo que frenar por salud o un tema personal, ¿es grave?", "variantes": ["me tengo que tomar un descanso", "voy a dejar de subir unos días", "¿pierdo todo si paro?", "me mudo y no voy a poder subir"], "respuesta": "Si el cuerpo pide descanso, hay que dárselo. A Max se le quemó la computadora y estuvo una semana sin subir: la cuenta se resintió un poco pero volvió. Esto es a largo plazo. Si ya lanzaste, tratá de dejar videos programados, porque frenar de golpe hace que YouTube te baje un tiempo. Si todavía no lanzaste, esperá a tener la situación resuelta.", "silver": false}, {"id": "g1-016", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "Mi primer video me llevó muchísimo, ¿es normal?", "variantes": ["tardé días en un video", "¿siempre va a tardar tanto?", "soy lento editando", "el primer video me costó un montón"], "respuesta": "Totalmente normal. El primer video es el que más cuesta. Cada vez vas a tardar menos y la calidad va a subir con la práctica. Tener un margen de videos adelantados te ayuda a sostener la constancia. Ya terminarlo es un paso enorme: la mayoría se queda en la carpeta de proyectos.", "silver": false}, {"id": "g1-018", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "Mi canal no funcionó, ¿vuelvo a intentar con otro?", "variantes": ["fracasé con mi primer canal", "no monetizó, ¿hago otro?", "¿arranco de nuevo?", "perdí el tiempo con mi canal"], "respuesta": "No fracasaste: ganaste experiencia. Ya pasaste por la investigación, la pantalla en blanco y la constancia. El primer canal es para aprender, y un solo canal puede compensar varios intentos anteriores. Por eso el año te da seis oportunidades: si uno no anda, se hace otro con todo lo aprendido. Esto lo ves en la clase «Regla del 6O».", "silver": false, "video": {"id": "e8_mgzxssuk", "titulo": "La REGLA 6o: El salvavidas para comenzar a hacer Canales Automatizados de YT", "url": "https://www.youtube.com/watch?v=e8_mgzxssuk"}}, {"id": "g1-019", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Qué es la regla del 6O?", "variantes": ["¿qué significa 6o?", "¿qué es la regla de los seis?", "explicame la regla del 6o", "¿qué son las seis oportunidades?"], "respuesta": "Es dividir el año en seis períodos de dos meses: seis oportunidades para lanzar un canal y estudiarlo, con entre 30 y 60 videos por ciclo. La meta es acertar en al menos dos canales potentes que rindan en el tercer y cuarto trimestre. Sirve para manejar expectativas y planificar el año: lo que importa es el tiempo, la consistencia y las expectativas. Esto lo ves en la clase «Regla del 6O».", "silver": false, "video": {"id": "e8_mgzxssuk", "titulo": "La REGLA 6o: El salvavidas para comenzar a hacer Canales Automatizados de YT", "url": "https://www.youtube.com/watch?v=e8_mgzxssuk"}}, {"id": "g1-020", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Cuántos videos tengo que subir antes de decidir si el canal sirve?", "variantes": ["¿cuándo abandono un canal?", "llevo pocos videos y no anda, ¿lo dejo?", "¿cuándo sé si funciona?", "¿con 20 videos ya puedo saber?"], "respuesta": "Antes del video 30 siempre es apresurado decidir. Con esa cantidad, el algoritmo ya debería tener señales suficientes y tu canal impresiones, vistas y movimiento: ese es el primer balance. Con 8 o 20 videos todavía no hay información para concluir. Seguí ejecutando, mirá qué videos rinden mejor y potenciá eso. Esto lo ves en la clase «Regla del 6O».", "silver": false, "video": {"id": "wPkGiD3STWw", "titulo": "NO Comiences en YT FACELESS SIN VER ESTO PRIMERO!", "url": "https://www.youtube.com/watch?v=wPkGiD3STWw"}}, {"id": "g1-021", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Conviene arrancar con varios canales a la vez?", "variantes": ["¿hago varios canales juntos?", "¿cuántos canales tengo que tener?", "quiero lanzar tres canales", "¿mejor muchos canales o uno?", "¿qué errores comete el que empieza?"], "respuesta": "No. Menos es más: llevá los canales de a uno. Lanzar varios a la vez en el mismo nicho puede parecer conducta de granja de contenido. La meta del año es llegar con 2 canales muy buenos y bien atendidos, y escalar después. Apenas monetizás uno, lanzás el siguiente. Max cuenta que al principio lo que más le pesó fue la falta de organización: trabajá con videos adelantados. Esto lo ves en la clase «Regla del 6O».", "silver": false}, {"id": "g1-022", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿En qué época del año se gana más?", "variantes": ["¿qué es el q4?", "¿por qué bajan los ingresos a principio de año?", "¿cuándo paga más youtube?", "¿qué son los trimestres?"], "respuesta": "Los ingresos cambian por trimestre. El Q1 y el Q2 suelen ser bajos porque baja el RPM; el Q1 es la época de vacas flacas para todos. El Q3 es intermedio y el Q4, de octubre a diciembre, es el que más paga. Es una generalidad: hay nichos con demanda todo el año. Esto lo ves en la clase «Regla del 6O».", "silver": false}, {"id": "g1-023", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Ya es tarde para empezar este año?", "variantes": ["¿espero a que empiece el año?", "¿cuándo conviene lanzar?", "¿lanzo ahora o espero?", "¿espero un evento grande para lanzar?"], "respuesta": "El mejor momento es ya. Monetizar tarde en el año suele ser más difícil, pero arranca con ingresos altos porque el Q4 es el que más paga. Y cada período de dos meses es una oportunidad nueva para lanzar y estudiar un canal. Esto lo ves en la clase «Regla del 6O».", "silver": false}, {"id": "g1-024", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿La regla del 6O sirve si subo un video por mes?", "variantes": ["subo muy poco, ¿aplica?", "¿qué frecuencia necesita la regla?", "solo puedo subir uno por mes", "¿cuántos videos por semana para la regla?"], "respuesta": "La regla del 6O está pensada para canales que publican 2 o 3 veces por semana: así llegás a unos 30 videos en un mes y medio o dos, y hacés el primer balance. Si subís un video por mes, en el segundo video no hay información suficiente para saber si el canal es exitoso, así que no aplica igual. Esto lo ves en la clase «Regla del 6O».", "silver": false}, {"id": "g1-025", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "¿Cómo hacen los canales que monetizan con muy pocos videos?", "variantes": ["vi un canal que monetizó con 7 videos", "¿se puede monetizar con un video?", "¿cómo monetizan tan rápido?", "¿hay un truco para monetizar rápido?"], "respuesta": "No depende de cuántos videos subís, sino de la producción y de cómo responde el público al principio. Para que un video explote se tiene que dar todo junto: una idea de alta demanda y poca oferta, una miniatura con alto CTR, retención altísima, interacción, que la gente siga mirando después y buena calidad dentro de la estética del nicho. Suele pasarle a gente con experiencia. No es lo habitual: no te midas con eso.", "silver": false}, {"id": "g1-026", "modulo": "M0", "clase": "Regla del 6O", "pregunta": "Monetizé, ¿y ahora qué hago?", "variantes": ["ya estoy monetizado", "me llegó el pin, ¿qué sigue?", "¿qué hago después de monetizar?", "llegué a los requisitos"], "respuesta": "Felicitaciones, pero no te enamores del canal: es un escalón. Toca optimizar, estabilizar y cuidar ese canal, y empezar a armar el siguiente. No tomes los ingresos de los primeros meses como termómetro: mirá la retención, la consistencia y qué funcionó. Monetizar es uno de los primeros pasos, no la meta. Esto lo ves en la clase «Regla del 6O».", "silver": false}, {"id": "g1-027", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Qué necesito para monetizar mi canal?", "variantes": ["¿cuáles son los requisitos?", "¿cuántos suscriptores necesito?", "¿cuántas horas hacen falta?", "¿cómo entro al programa de socios?", "¿cuentan los videos ocultos o privados?"], "respuesta": "Monetizar es entrar al Programa de Socios de YouTube. Hoy, para videos largos, necesitás 1.000 suscriptores y 4.000 horas de visualización pública en los últimos 12 meses (o 10 millones de vistas de Shorts en 90 días). Ojo: desde el 1 de febrero de 2027 los canales nuevos van a necesitar 8.000 horas, así que conviene entrar antes. Los que ya están adentro no se ven afectados. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "zUfp4Z6xoZ4", "titulo": "Cómo monetizar en Youtube Automatizado con las NUEVAS REGLAS", "url": "https://www.youtube.com/watch?v=zUfp4Z6xoZ4"}}, {"id": "g1-028", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Conviene hacer un canal solo de shorts?", "variantes": ["¿shorts o videos largos?", "¿puedo monetizar solo con shorts?", "¿hago shorts para crecer?", "¿formato corto o largo?", "¿cuáles son los requisitos de shorts?"], "respuesta": "En shorts el requisito es de 10 millones de vistas públicas en los últimos 90 días. Se puede, pero Max no lo recomienda. Los shorts son negocios más efímeros: cuando dejás de tener virales, se cae, y tenés que hacer entre 5 y 10 videos por día. Su experiencia y la de sus mentores coinciden en que es mejor el formato largo. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "SAW-PZamvf0", "titulo": "Los Shorts destruyen tu monetización: esto es lo que no te dicen en Youtube", "url": "https://www.youtube.com/watch?v=SAW-PZamvf0"}}, {"id": "g1-029", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Qué pasa cuando llego a los requisitos?", "variantes": ["llegué a las 4000 horas, ¿y ahora?", "¿me aprueban automático?", "¿quién revisa mi canal?", "¿qué revisa youtube?"], "respuesta": "Cuando llegás, YouTube revisa con IA y con personas que tu canal cumpla las políticas de monetización y las normas de la comunidad. Esas políticas pueden cambiar, así que hay que leerlas seguido. Conocerlas es parte del negocio, igual que creer en el proceso y manejar las emociones si te piden correcciones. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g1-031", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Cómo y cuándo me paga YouTube?", "variantes": ["¿cómo cobro?", "¿qué día pagan?", "¿qué es adsense?", "¿cuándo llega la plata?", "¿puedo cobrar con paypal?"], "respuesta": "Para cobrar tenés que crear y validar una cuenta de AdSense, la plataforma de Google que te paga. YouTube paga entre el 21 y el 26 de cada mes lo generado el mes anterior, por los anuncios de tus videos, y algo más cuando el espectador hace clic. Qué medios de cobro podés usar depende de tu país: hay una lista oficial por país. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-036", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Puedo abrir el canal como si fuera de Estados Unidos para ganar más?", "variantes": ["¿uso una ip de usa?", "¿pongo otro país para cobrar más?", "¿abro el canal con vpn en usa?", "¿finjo que vivo en otro país?"], "respuesta": "No te lo recomendamos. Aunque cambie tu público inicial, falsear los datos frente a AdSense te puede traer problemas administrativos y hasta la desmonetización. Si querés audiencia que pague más, hacé el canal en inglés: atraés ese público sin necesidad de estar allá. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-037", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "Si vivo en Latinoamérica, ¿gano menos que alguien de Estados Unidos?", "variantes": ["¿mi país afecta lo que gano?", "¿cobro menos por vivir en latam?", "¿compito con los yanquis?", "¿de qué depende cuánto pagan?"], "respuesta": "Lo que define cuánto ganás no es dónde vivís, sino dónde está tu audiencia, porque eso marca el valor de los anuncios. Tu ubicación importa para lo fiscal. Y competís por idioma, no por país: si hacés videos en inglés, competís con todos los que hacen videos en inglés, vivan donde vivan. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "wPkGiD3STWw", "titulo": "NO Comiences en YT FACELESS SIN VER ESTO PRIMERO!", "url": "https://www.youtube.com/watch?v=wPkGiD3STWw"}}, {"id": "g1-039", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Hay beneficios antes de llegar a los 1.000 suscriptores?", "variantes": ["¿qué pasa con 500 suscriptores?", "¿qué son las membresías?", "¿cuándo dan la placa?", "¿qué es super thanks?"], "respuesta": "Sí, hay una meta intermedia: con 500 suscriptores y 3.000 horas se habilitan Super Chat, Super Stickers, Super Thanks y las membresías del canal. Las placas de YouTube llegan desde los 100.000 suscriptores. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-041", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Puedo pagar publicidad o promocionar el canal para llegar antes a los requisitos?", "variantes": ["¿compro vistas?", "¿pago anuncios en youtube?", "me ofrecen promocionar mi canal", "¿comparto mis videos en grupos?", "¿sirve pasar el link en redes?"], "respuesta": "No. Pagar anuncios o servicios de terceros destruye las señales del algoritmo, sobre todo la retención; muchas ofertas de tráfico son bots y eso está prohibido. Llevar tráfico externo al principio también ensucia tu audiencia inicial y YouTube puede confundirlo con vistas pagas. Max recién comparte en redes después de más de 60 videos. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-042", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "YouTube ahora cuenta las vistas desde el primer segundo, ¿qué cambia?", "variantes": ["cambio en el conteo de vistas", "¿qué son las vistas con interacción?", "¿gano más con más vistas en el contador?", "¿cambiaron los requisitos?"], "respuesta": "Desde agosto una vista cuenta desde el primer fotograma, incluida la reproducción automática. Lo que antes era vista ahora se llama vista con interacción. Tus ingresos se siguen calculando con las vistas y horas con interacción, así que un contador más grande no te hace ganar más. Los requisitos no cambiaron, y el CTR y la retención se calculan igual. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-043", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "Las vistas de mi video bajaron de golpe en YouTube Studio, ¿qué pasó?", "variantes": ["me sacaron vistas", "el contador de vistas bajó", "¿por qué desaparecen vistas?", "tenía más vistas y ahora menos", "las horas de monetización no coinciden con el panel"], "respuesta": "No es un error ni hiciste algo mal. Studio cuenta las vistas en tiempo real y después las valida en lote: descuenta tráfico inválido como bots, autovisualizaciones y rebotes que no cumplen con una vista humana. Además, las horas de monetización tardan unos 3 a 5 días en aparecer por una verificación antifraude, y ese panel solo cuenta horas públicas válidas: esas son las oficiales. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-044", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "Las 4.000 horas me parecen imposibles, ¿cómo llego?", "variantes": ["nunca voy a llegar a las horas", "¿y si suben los requisitos?", "sumo horas muy de a poco", "¿cuántos videos necesito para las horas?"], "respuesta": "En YouTube el crecimiento casi nunca es lineal, es exponencial. No se trata de subir cien videos que sumen de a poquito: la clave es lograr un video que se destaque, que acierte en el tema, tenga buen empaque y retenga a la gente. Un solo video así puede cubrir el requisito de horas. El foco está en encontrar la demanda. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "wVo2-1folnA", "titulo": "Te quedan 4 meses para MONETIZAR en YouTube con las reglas viejas (plan de 120 días)", "url": "https://www.youtube.com/watch?v=wVo2-1folnA"}}, {"id": "g1-045", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Qué es el RPM y cómo se calcula?", "variantes": ["¿qué significa rpm?", "¿cuánto pagan cada mil vistas?", "fórmula del rpm", "¿qué es el cpm?"], "respuesta": "RPM significa ingresos por cada mil vistas: ingresos totales dividido vistas totales, por 1.000. Depende mucho del país de tu audiencia y de la época del año. Las herramientas externas solo dan un rango aproximado del nicho, así que tomalo como algo orientativo: en la metodología es la variable de menor peso. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "_sa_jqSBsoM", "titulo": "Descubre por qué YouTube es el mejor negocio en 2026", "url": "https://www.youtube.com/watch?v=_sa_jqSBsoM"}}, {"id": "g1-046", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Cuánto voy a ganar con mi canal?", "variantes": ["¿cuánta plata se hace?", "¿cuánto gana un canal faceless?", "¿cuánto paga youtube por video?", "¿de esto se puede vivir?"], "respuesta": "Nadie te puede decir una cifra: depende del nicho, del país de tu audiencia, de la época del año y, sobre todo, de tu proceso. No hay garantías. Lo que sí está claro es que es un negocio que da resultados con constancia y paciencia, y que la mentalidad pesa muchísimo. Enfocate en dominar la metodología. Esto lo ves en las clases «Requisitos de monetización» y «Regla del 6O».", "silver": false, "video": {"id": "_sa_jqSBsoM", "titulo": "Descubre por qué YouTube es el mejor negocio en 2026", "url": "https://www.youtube.com/watch?v=_sa_jqSBsoM"}}, {"id": "g1-047", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Es verdad que las vistas bajan cuando monetizás?", "variantes": ["¿youtube baja las vistas al monetizar?", "monetizé y tengo menos vistas", "¿es un mito lo de las vistas?", "me bajó el rpm después de monetizar"], "respuesta": "Es un mito que YouTube te testee para ver si tu audiencia es real. Lo que suele pasar es que el RPM se estabiliza: con volúmenes chicos cualquier cambio mueve mucho los números, y si cambia el país de tu audiencia, cambia el valor de los anuncios. Si bajan las vistas, suele ser por otros cambios, como alargar mucho los videos de golpe. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g1-048", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Qué diferencia hay entre nicho y temática?", "variantes": ["¿qué es un nicho?", "¿nicho y tema son lo mismo?", "¿qué es la temática?", "no entiendo qué es un nicho"], "respuesta": "La temática es solo el tema. El nicho es una audiencia con un interés en común y comportamientos específicos. Un nicho no se crea, se encuentra. Por eso no alcanza con elegir un tema que te guste: tiene que haber gente que lo busque y lo mire. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false, "video": {"id": "yZ7I4q4EXP0", "titulo": "NO Empieces un CANAL DE YOUTUBE FACELESS Sin Saber Esto", "url": "https://www.youtube.com/watch?v=yZ7I4q4EXP0"}}, {"id": "g1-049", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Qué es un subnicho y un micronicho?", "variantes": ["¿diferencia entre nicho, subnicho y micronicho?", "¿qué es un micronicho?", "¿qué tan específico tiene que ser?", "ejemplo de subnicho", "¿un micronicho muy chico sirve?"], "respuesta": "Nicho es una audiencia masiva, como deportes o tecnología. Subnicho es un interés más específico, como fútbol o tenis. Micronicho es una audiencia muy concreta, como tenis para mujeres. En SEN6 se trabaja en subnichos o micronichos con volumen: si el subnicho no es popular, como el waterpolo, su micronicho tampoco sirve. En la comunidad, cuando decimos nicho, hablamos de eso. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false, "video": {"id": "yZ7I4q4EXP0", "titulo": "NO Empieces un CANAL DE YOUTUBE FACELESS Sin Saber Esto", "url": "https://www.youtube.com/watch?v=yZ7I4q4EXP0"}}, {"id": "g1-050", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Cuál es la fórmula de SEN6 para elegir nicho?", "variantes": ["¿qué es nicho más estética?", "¿la estética cambia el nicho?", "¿qué es tema más formato?", "¿cómo armo mi nicho?"], "respuesta": "Subnicho o micronicho con volumen más una estética particular. La estética cambia la audiencia y, por lo tanto, el nicho: no es lo mismo psicología oscura explicada con stickman que con otro estilo, ni arte con monos que en formato documental. Hasta el tono del guion puede cambiar la audiencia y el RPM. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false}, {"id": "g1-052", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Qué es el niche bending?", "variantes": ["¿qué es niche bending?", "¿puedo mezclar un formato con otro tema?", "¿llevar un formato viral a otro nicho?", "¿qué es el océano azul?"], "respuesta": "Es llevar un formato que ya funciona a un nicho con demanda donde nadie lo usa. Ejemplo de Max: los canales que explican fitness con monos y bananas tomaron el formato de los monos que explicaban economía. No sos pionero en el tema, le das un ángulo único a un nicho con demanda probada. Lo que funciona se deja y se adapta con un giro. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false, "video": {"id": "LbuKQhm7DfY", "titulo": "La Fórmula Para Hacer VIDEOS VIRALES EN YOUTUBE Antes De Que Sea Tarde (YouTube 2027)", "url": "https://www.youtube.com/watch?v=LbuKQhm7DfY"}}, {"id": "g1-053", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Puedo hacer un canal de un tema que nadie hace?", "variantes": ["quiero ser pionero", "no hay canales de mi tema", "¿sirve un nicho sin competencia?", "nadie hace lo que quiero hacer"], "respuesta": "Se puede, pero un canal pionero puede salir muy bien o muy mal, porque no hay demanda comprobada. Si es lo que te motiva a no abandonar, buscá el ángulo en nichos hermanos o trae formatos virales de otras plataformas. Para el primer canal conviene apegarse al paso a paso. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false, "video": {"id": "PV_F1EqF1aA", "titulo": "5 NICHOS DE YOUTUBE Que Pagan En Dólares y En Español están VACÍOS", "url": "https://www.youtube.com/watch?v=PV_F1EqF1aA"}}, {"id": "g1-056", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "Canales del mismo tema que el mío crecen más rápido, ¿qué hago mal?", "variantes": ["otros canales iguales al mío crecen", "mi competencia me pasa", "¿por qué a otros les va mejor?", "un canal nuevo me superó"], "respuesta": "Primero, antes del video 30 es apresurado sacar conclusiones. Segundo, el nicho es temática más formato: un detalle de estética o de tono cambia la audiencia y hasta el RPM. Mirá qué hace bien la competencia, dejá el ego de lado y adaptá sus buenas prácticas. Quizás no tengas que abandonar, sino ir girando el ángulo. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false}, {"id": "g1-057", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "Mi canal se estancó, ¿cambio de nicho por completo?", "variantes": ["¿cambio de tema?", "¿giro el canal a otra cosa?", "mi canal no crece, ¿lo cambio?", "¿puedo cambiar el enfoque del canal?"], "respuesta": "Mejor reperfilar que cambiar de golpe. Si cambiás bruscamente, es como empezar de cero, o peor: el algoritmo pierde lo que sabía de tu canal y perdés suscriptores. Estudiá tu audiencia y cambiá el ángulo de a poco dentro del mismo nicho, por ejemplo mirando nichos hermanos o cambiando la estética. Los cambios se notan con una seguidilla de videos, no con uno. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false}, {"id": "g1-058", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Hago el canal en español, en inglés o en los dos?", "variantes": ["¿canal en dos idiomas?", "¿conviene inglés?", "¿un canal con varios idiomas?", "¿traduzco mis videos?"], "respuesta": "Al empezar, elegí un solo idioma. Hacer dos canales o mezclar idiomas te duplica el trabajo antes de saber si el contenido funciona, y mezclar idiomas en un canal es un desastre. El inglés atrae audiencia que paga más sin que tengas que vivir allá. Replicar el canal en otro idioma es parte de escalar, cuando ya tenés uno monetizado. Esto lo ves en la clase «Nicho vs. Temática».", "silver": false, "video": {"id": "PV_F1EqF1aA", "titulo": "5 NICHOS DE YOUTUBE Que Pagan En Dólares y En Español están VACÍOS", "url": "https://www.youtube.com/watch?v=PV_F1EqF1aA"}}, {"id": "g1-059", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Conviene un nicho evergreen o de tendencia?", "variantes": ["¿qué es evergreen?", "¿temas de moda o atemporales?", "¿canal de tendencias sirve?", "¿nicho de moda o de siempre?"], "respuesta": "Max recomienda nichos evergreen, los que se siguen buscando con el tiempo. Los temas de moda pueden tener un boom, pero con el tiempo dejan de estarlo. Un video evergreen puede seguir pagando durante años. Esto lo ves en las clases «Nicho vs. Temática» y «Por qué YouTube Faceless».", "silver": false, "video": {"id": "yZ7I4q4EXP0", "titulo": "NO Empieces un CANAL DE YOUTUBE FACELESS Sin Saber Esto", "url": "https://www.youtube.com/watch?v=yZ7I4q4EXP0"}}, {"id": "g1-063", "modulo": "M1", "clase": "Requisitos de monetización", "pregunta": "¿Cómo armo productos, membresías o ventas fuera de YouTube?", "variantes": ["¿cómo vendo cursos con mi canal?", "monetización externa", "¿afiliados o merch?", "¿cómo gano además de adsense?"], "respuesta": "Lo básico: alrededor de tu audiencia se pueden construir productos digitales, membresías, cursos y merchandising, y funciona cuando están alineados la comunidad, la comunicación y el negocio. El cómo, paso a paso, no está en Lite. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "3uM7nQt6cvM", "titulo": "3 razones por las que tu canal faceless JAMÁS te dará dinero", "url": "https://www.youtube.com/watch?v=3uM7nQt6cvM"}}, {"id": "g1-064", "modulo": "M1", "clase": "Nicho vs. Temática", "pregunta": "¿Conviene hacer contenido para niños?", "variantes": ["¿canal infantil?", "¿youtube kids sirve?", "¿marco creado para niños?", "¿videos para chicos monetizan?"], "respuesta": "Lo básico: depende de tu tolerancia al riesgo, porque YouTube es muy estricto con ese contenido, y de tu paciencia, porque el RPM es bajo y necesitás mucho volumen. Y si tu contenido no es infantil, no lo marques como creado para niños. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g1-066", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Puedo usar música en mis videos sin problemas de copyright?", "variantes": ["¿música de capcut sirve?", "me llegó un reclamo por música", "¿la música de suno es mía?", "¿qué música puedo usar?"], "respuesta": "Lo básico: un reclamo de Content ID no es un strike, pero los ingresos de ese video van al dueño de la música. La música de bibliotecas como la de CapCut no está licenciada para YouTube. Música, efectos y derechos no están en Lite. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g1-068", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Puedo automatizar el canal con IA para que se haga solo?", "variantes": ["¿hay bots que hagan los videos?", "¿automatizo todo el canal?", "¿una ia que arme el video entero?", "tengo poco tiempo, ¿automatizo?"], "respuesta": "Lo básico: se puede automatizar casi todo, pero el guion y la voz tienen que tener aporte humano. Elegí herramientas que te dejen descargar el proyecto, porque si tenés que apelar y no podés mostrar un proceso humano, es difícil monetizar. Las automatizaciones no están en Lite. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "hxTpugOFcyw", "titulo": "El fin de los canales automatizados? Cómo sobrevivir a la nueva política de YOUTUBE", "url": "https://www.youtube.com/watch?v=hxTpugOFcyw"}}, {"id": "g1-069", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Cuánto cuesta producir videos con IA y puedo hacerlo con mi nivel?", "variantes": ["¿qué presupuesto necesito para ia?", "¿puedo competir con canales que producen mucho?", "¿qué suscripción de ia pago?", "¿me da el nivel técnico?"], "respuesta": "Lo básico: antes de entrar a un nicho pensá dos cosas, si podés producir al nivel de tus referencias y si podés sostener el costo varios meses sin retorno. No hay canal barato en sí: depende de tus medios de producción y de tu tiempo. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g1-070", "modulo": "M0", "clase": "Por qué YouTube Faceless", "pregunta": "¿Puedo tener una sesión 1 a 1 o hablar con alguien de la comunidad?", "variantes": ["¿hay grupo de whatsapp?", "¿puedo hablar con Lau?", "¿hay comunidad?", "¿dónde hago preguntas en vivo?", "quiero una reunión personalizada"], "respuesta": "En Lite te acompaño yo con estas respuestas, que salen de lo que Max y Lau ya contestaron a muchos alumnos. La comunidad, las sesiones de preguntas en vivo y las sesiones 1 a 1 con Lau son parte de los planes con comunidad, y no hay un grupo oficial de WhatsApp. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-001", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿En qué consiste el método SEN6, explicado simple?", "variantes": ["¿Cuál es el método de SEN6?", "¿Cómo funciona el método paso a paso?", "¿Qué es lo primero que hay que hacer?", "Resumime el método"], "respuesta": "Es un mapa en cinco pasos. Primero buscás, en cualquier idioma, un canal de referencia exitoso dentro de un grupo grande con vistas. Segundo, con IA le extraés las estructuras ganadoras, los famosos «masters»: guion, miniaturas, títulos, hooks y momentos de los CTA. Tercero, le cambiás el ángulo para hablarle a esa misma audiencia. Cuarto, optimizás con métricas. Y quinto, monetizás y escalás. Todo arranca por la investigación, que es la parte más importante. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-002", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Usar un canal de referencia no es copiar? ¿YouTube no castiga eso?", "variantes": ["¿Esto es copiar canales?", "¿Me van a penalizar por copiar?", "¿Puedo replicar un canal que funciona?", "¿Es legal tomar ideas de otro canal?", "¿Usar un canal de referencia es copiar?", "¿esto es copiar canales?", "¿youtube castiga a los que copian?", "¿puedo clonar un canal que funciona?", "¿qué se puede copiar y qué no?"], "respuesta": "No copiamos, y es justamente lo que evitamos. Del canal de referencia tomamos la estructura ganadora, no sus elementos, y validamos que haya audiencia. Después cambiamos todo el contenido y, sobre todo, el ángulo, que es lo que te convierte en un canal único. Además, si copiás tal cual a un canal ya establecido, te pasa por arriba: tiene historial y el algoritmo ya lo tiene como la opción fuerte. No replicamos canales, replicamos nichos. Esto lo ves en la clase «El Método del SEN6».", "silver": false, "video": {"id": "LbuKQhm7DfY", "titulo": "La Fórmula Para Hacer VIDEOS VIRALES EN YOUTUBE Antes De Que Sea Tarde (YouTube 2027)", "url": "https://www.youtube.com/watch?v=LbuKQhm7DfY"}}, {"id": "g2-003", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Qué es el ángulo de un canal?", "variantes": ["¿Qué significa cambiar el ángulo?", "¿Cómo le doy un ángulo distinto a mi canal?", "Si el nicho es temática más estética, ¿qué es el ángulo?", "¿Qué hace único a un canal?", "¿qué significa cambiar el ángulo?", "¿cómo le doy un giro a mi canal?", "¿qué es el anclaje cultural?", "¿en qué se diferencia de la competencia?"], "respuesta": "El ángulo es el punto de vista desde el que contás las cosas, y siempre se piensa respecto a la competencia. Lau lo explica así: un canal de historia de alimentos cuenta la historia del chocolate; uno con otro ángulo cuenta la historia de marcas de alimentos; y si le sumás anclaje cultural, hablás de las marcas más queridas de un país. Mismo tema, otra mirada. También puede ser el mismo formato aplicado a otra época o civilización. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-004", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Qué es exactamente un nicho?", "variantes": ["¿Cómo defino un nicho?", "¿Nicho es solo el tema del canal?", "¿Qué diferencia hay entre temática y formato?", "¿Qué quiere decir temática más estética?"], "respuesta": "Para nosotros un nicho es temática + estética, es decir, de qué hablás y con qué formato lo mostrás. Por eso, cuando buscás canales parecidos a tu referencia, te quedás solo con los que se parecen en las dos cosas. Ese pequeño detalle de la estética o el tono cambia todo: puede cambiar la audiencia y hasta lo que paga el canal. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false, "video": {"id": "yZ7I4q4EXP0", "titulo": "NO Empieces un CANAL DE YOUTUBE FACELESS Sin Saber Esto", "url": "https://www.youtube.com/watch?v=yZ7I4q4EXP0"}}, {"id": "g2-005", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Tengo que buscar un nicho o un canal? No entiendo la diferencia", "variantes": ["¿Busco nichos o canales?", "¿Qué es un subnicho?", "¿Cómo sé cuál es el nicho de un canal?", "¿Nicho y canal es lo mismo?"], "respuesta": "Las dos cosas a la vez. Aunque hablamos de nicho, lo que buscás son canales de referencia de ese nicho. La cuenta educada te muestra un canal y eso te indica el nicho, que lo determinás vos porque YouTube no clasifica nichos. Por ejemplo: un canal que analiza esculturas está en el nicho Arte, subnicho Escultura. A esa altura, por practicidad, ya le llamamos nicho al subnicho. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-006", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿En qué idioma me conviene arrancar mi canal?", "variantes": ["¿Español o inglés?", "¿Conviene hacer el canal en inglés porque paga más?", "¿En qué idioma hago mi primer canal?", "¿Qué mercado elijo para empezar?"], "respuesta": "Para el primer canal recomendamos español o un idioma que hables. Tiene menos competencia que el inglés, aunque pague menos, y es el idioma en el que podés entender tus guiones y a tu audiencia. Pensá que los mercados son idiomas: vivas donde vivas, competís contra todos los que hacen videos en ese idioma. Esto lo ves en la clase «El Método del SEN6».", "silver": false, "video": {"id": "PV_F1EqF1aA", "titulo": "5 NICHOS DE YOUTUBE Que Pagan En Dólares y En Español están VACÍOS", "url": "https://www.youtube.com/watch?v=PV_F1EqF1aA"}}, {"id": "g2-007", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Qué diferencia hay entre canal de referencia y canal de competencia?", "variantes": ["¿Cuál es mi referencia y cuál mi competencia?", "Encontré varios canales parecidos, ¿cuál tomo de referencia?", "¿Qué es un canal de competencia?", "¿Cómo elijo el canal de referencia?"], "respuesta": "La referencia es el canal del que extraés las estructuras; puede estar en cualquier idioma y tiene que cumplir todos los requisitos. La competencia son los canales de tu mismo nicho en el idioma en que vas a publicar. Si encontrás varios, tu referencia es el de mejor desempeño dentro de los requisitos: con canales de 500.000, 1 millón y 3 millones de vistas mensuales, la referencia es el de 3 millones. Mirá también cuál está mejor hecho y tiene más comentarios. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-008", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Qué son los «masters» y qué le saco al canal de referencia?", "variantes": ["¿Qué extraigo del canal de referencia?", "¿Qué es el guion master?", "¿Cómo saco la estructura de un canal?", "¿Para qué sirve analizar los guiones de la referencia?"], "respuesta": "Los masters son las estructuras ganadoras del canal de referencia: guion master, patrones de miniaturas, títulos, hooks, momentos de los CTA y hasta el modelo de negocio. Para el guion, juntás el texto de al menos 5 guiones exitosos (ideal 8) y le pedís a la IA que te saque la estructura y los patrones: tantos minutos de hook, tantos de planteo, y así. Ese esqueleto es tu master. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-009", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Cómo saco el texto o guion de un video de YouTube?", "variantes": ["¿Cómo transcribo un video?", "¿Qué herramienta uso para sacar los guiones?", "¿Sirve la transcripción de YouTube?", "¿Cómo copio el guion de un video de la referencia?"], "respuesta": "La forma más simple y gratis es el botón de transcripción de YouTube, debajo del video. Te recomendamos desactivar las marcas de tiempo desde los tres puntos del cuadro de transcripción (en algunos videos se puede y en otros no) y después copiás y pegás el texto donde quieras. También sirve la extensión de Chrome YouTube Summary, que es gratuita. Si alguna deja de andar un tiempo, usá la otra. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-010", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Puedo usar un canal en español como referencia?", "variantes": ["¿La referencia tiene que estar sí o sí en inglés?", "No encuentro nada en inglés, ¿sirve un canal en español?", "¿Puede ser la referencia del mismo idioma que mi canal?", "¿En qué idioma busco la referencia?"], "respuesta": "Sí. El canal de referencia puede estar en cualquier idioma, lo importante es que cumpla todos los requisitos. Si encontrás uno en español y ves que el nicho tiene oportunidad, adelante. Y si después monetizás, en lugar de irte a otro idioma podés blindarte: hacer otro canal en ese mismo nicho con un ángulo diferente. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-011", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Elijo un nicho que me guste o el que más paga aunque no me interese?", "variantes": ["¿Tiene que gustarme el tema?", "¿Conviene un nicho con más RPM aunque no me guste?", "¿Elijo por pasión o por plata?", "¿Tengo que tener un nicho en mente antes de buscar?", "¿Elijo un nicho que me guste o el que más paga?", "¿puedo elegir un tema que no me interesa?", "¿pasión o plata?", "¿tiene que gustarme el nicho?", "¿elijo por rpm?"], "respuesta": "Hay dos caminos. Uno: te centrás en lo rentable aunque no te guste el tema; la investigación tarda menos, pero sabé que vas a hacer muchos videos hasta poder delegar. Dos: buscás un nicho que te guste; es más fácil sostenerlo en el tiempo y más placentero, pero la investigación tarda más. Max elige el segundo y a veces tarda hasta un mes en encontrar uno rentable, que le guste y que pueda editar rápido. Esto lo ves en la clase «El Método del SEN6».", "silver": false, "video": {"id": "EK2I4TiE0UM", "titulo": "Así hice 8 canales de YouTube sin mostrar mi cara", "url": "https://www.youtube.com/watch?v=EK2I4TiE0UM"}}, {"id": "g2-012", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Por qué importa tanto conocer a la audiencia del nicho?", "variantes": ["¿La audiencia cambia cómo hago los videos?", "¿Para qué sirve saber quién mira el canal?", "¿Cómo optimizo según el público?", "¿Qué es optimizar con métricas?"], "respuesta": "Porque la audiencia define la optimización. Si el público es de España, te conviene elegir temas que le resuenen allá; si es gente de 25 a 35 años, una edición más dinámica; si miran por TV de noche, videos más largos. No es una receta fija: mirás quién te ve y ajustás temas, ritmo y duración a esa gente. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-013", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Escalar significa automatizar todo con IA?", "variantes": ["¿Cómo se escala un canal?", "¿Qué es escalar en SEN6?", "¿Tengo que automatizar con IA para crecer?", "¿Cuándo armo un segundo canal?"], "respuesta": "No. Escalar es delegar, no automatizar con IA. La idea es que, cuando un canal ya genera ingresos, uses parte de eso para contratar un editor y armar un segundo canal o pasar a otro mercado. Y cuando vayas a otro idioma, volvés a revisar que haya competencia con los requisitos de siempre en ese mercado. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-014", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Cuánto tiempo me va a llevar la investigación de nichos?", "variantes": ["¿Cuánto tarda encontrar un nicho?", "¿En cuántos días tengo que tener el nicho?", "¿Cuántas horas por día le dedico a investigar?", "¿Está bien tomarme mi tiempo?"], "respuesta": "Semanas, no días. Max recomienda unos 15 minutos por día durante un par de semanas hasta tener tus 5 opciones, y aun así hay que ver cómo evolucionan esos canales. Una investigación bien hecha no dura menos de dos semanas. No es un negocio de velocidad, es de paciencia: el nicho es la base de todo y apurarse es lo que más caro sale. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-015", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Arranco a hacer videos o veo clases de IA antes de tener el nicho?", "variantes": ["¿Puedo empezar a producir antes de terminar la investigación?", "¿Veo las clases de producción primero?", "¿Qué hago mientras la cuenta educada aprende?", "¿Conviene avanzar con videos sin nicho?"], "respuesta": "Primero el nicho. Producir sin tener la investigación hecha no suma, porque todo (miniaturas, guiones, estética) depende del nicho que elijas. Lo que sí podés hacer es aprovechar el tiempo: mientras alimentás la cuenta educada todos los días, que te lleva pocos minutos, podés ir mirando clases de producción. Pero no subas videos hasta tener el nicho validado. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-016", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "Encuentro un nicho, después otro, y salto de idea en idea sin terminar ninguno, ¿cómo me ordeno?", "variantes": ["Me disperso con muchos nichos", "¿Cómo organizo mi flujo de trabajo?", "Siempre encuentro un nicho mejor y cambio", "No logro decidirme por un nicho"], "respuesta": "Trabajá por etapas cortas, lo que se llama sprints. El primer sprint es solo investigar y decidir un canal. Recién en el segundo ves cómo se produce y hacés pruebas. Así no abrís puertas nuevas a cada rato. Si en el camino encontrás muchos más canales de los que necesitás, anotalos para el futuro y seguí con tu lista. Y en el primer canal, mejor algo conservador; el salto de riesgo viene después. Esto lo ves en la clase «El Método del SEN6».", "silver": false}, {"id": "g2-017", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Qué requisitos tiene que cumplir un canal de referencia?", "variantes": ["¿Cuáles son los requisitos del nicho ideal?", "¿Cómo sé si un canal sirve de referencia?", "¿Qué números tiene que tener el canal?", "Pasame la lista de requisitos"], "respuesta": "El canal de referencia tiene que cumplir todo: 6 meses de antigüedad o menos, entre 1.000 y 50.000 suscriptores, más de 1 millón de vistas mensuales, un RPM conveniente (arriba de 3 en inglés, alrededor de 2 en español), y sí o sí un outlier de más de 100.000 vistas en el último mes, mejor si viene acompañado de varios de 50 a 70 mil. Además, tiene que ser algo que puedas igualar o mejorar en producción. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-018", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Qué es un outlier y por qué es tan importante?", "variantes": ["¿Qué significa outlier?", "¿Para qué sirve el video de más de 100 mil vistas?", "¿Cuántos outliers tiene que tener la referencia?", "¿Qué indica un outlier?"], "respuesta": "Un outlier es un video que rinde muy por encima del resto del canal. Para nosotros es obligatorio que la referencia tenga al menos uno con más de 100.000 vistas en el último mes, y mejor si lo acompañan varios de 50 a 70 mil. ¿Por qué? Porque indica demanda: hay gente queriendo ver ese contenido ahora. Si tuvo outliers antes pero en el último mes no, no cumple. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-019", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Cómo calculo la antigüedad de un canal si la cuenta es muy vieja?", "variantes": ["El canal se creó hace años pero subió hace poco, ¿cuenta?", "¿La antigüedad es desde que se abrió el canal?", "¿Compran cuentas viejas?", "¿Desde cuándo cuento los 6 meses?"], "respuesta": "La antigüedad que nos importa es desde que subió su primer video, no la fecha de creación de la cuenta. Una cuenta puede ser muy vieja porque el creador ya la tenía o porque la compró; eso no nos interesa. Fijate cuándo empezó a publicar y con eso calculás si tiene 6 meses o menos. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-020", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "Encontré un canal que cumple todo pero tiene un año o más, ¿sirve como referencia?", "variantes": ["¿Sirve un canal de varios años con muchas vistas?", "¿Puede tener más de 6 meses la referencia?", "El canal tiene 1 año, ¿lo descarto?", "¿Por qué tiene que ser un canal nuevo?"], "respuesta": "La recomendación es que no tenga más de 6 meses. Con los cambios de 2026 la idea es encontrar un canal pequeño y reciente de referencia. Un canal de varios años con muchas vistas es una mala referencia: YouTube empuja más a los canales que llevan años y no te muestra si hay lugar para alguien nuevo hoy. Si encontrás uno de un año junto con varios canales chicos que la rompen, hay demanda, pero la pregunta pasa a ser cuál es tu ángulo. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-021", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Sirve un canal de referencia que ya pasó el límite de suscriptores?", "variantes": ["El canal tiene más de 100 mil suscriptores, ¿lo uso?", "¿Puedo tomar un canal grande como referencia?", "¿Por qué el máximo de suscriptores?", "Supera los 50 mil subs pero tiene buenas métricas"], "respuesta": "El requisito es entre 1.000 y 50.000 suscriptores, y para la referencia no hay flexibilidad. Un canal grande te tiene que hacer dudar: si lo encontraste vos, lo encontraron muchos otros. Lau lo dice claro: un canal de más de 100.000 ya está ultra posicionado y tiene tracción propia del algoritmo; se le puede competir, pero es muy difícil, y además tiene su propia audiencia. Buscá uno más chico que cumpla todo. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-022", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "A mi canal le faltan pocas vistas para el millón mensual, ¿lo descarto?", "variantes": ["Tiene 900 mil vistas al mes, ¿sirve?", "¿Puedo ser flexible con el millón de vistas?", "No llega al millón por poco", "¿Qué tan estricto es el requisito de vistas?"], "respuesta": "Depende de cuánto le falte. Lau lo explica así: si el canal tiene 900.000 o 950.000 vistas mensuales, está bien; si tiene 650.000, no. Igual, no te conformes rápido: canales de 1 o 2 millones se encuentran, y son los que buscamos. Lo importante es que cumpla los criterios de demanda: suscriptores, vistas y vistas de los últimos 30 días. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-023", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Qué es el RPM y cómo lo calculo?", "variantes": ["¿Qué significa RPM?", "¿Cómo saco el RPM de un canal?", "¿Cuál es la fórmula del RPM?", "¿Cómo calculo cuánto paga un nicho?"], "respuesta": "RPM significa «Revenue Per Mille»: lo que gana un canal cada mil vistas. La fórmula es ingresos totales dividido vistas totales, por 1.000. Con un canal ajeno, tomás los ingresos estimados del mes que te da la herramienta, los dividís por las visualizaciones del mes y multiplicás por 1.000. Como referencia, buscamos arriba de 3 en inglés y alrededor de 2 en español. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false, "video": {"id": "_sa_jqSBsoM", "titulo": "Descubre por qué YouTube es el mejor negocio en 2026", "url": "https://www.youtube.com/watch?v=_sa_jqSBsoM"}}, {"id": "g2-024", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Puedo confiar en el RPM o en las ganancias que me muestran VidIQ o NexLev?", "variantes": ["¿Es obligatorio que el RPM sea mayor a 2?", "VidIQ me muestra ganancias rarísimas, ¿son reales?", "¿Qué tan exacto es el RPM de las herramientas?", "¿Le doy importancia al RPM?", "¿Puedo confiar en las ganancias que muestran vidIQ o NexLev de otros canales?", "¿vidiq dice la verdad?", "¿cómo sé cuánto gana un canal?", "las ganancias estimadas son raras", "¿qué herramienta estima mejor?"], "respuesta": "Tomalo como orientativo. Las herramientas no te dan el RPM real de un canal: hacen un promedio de los canales del nicho que tienen, y hoy son más inexactas que nunca porque YouTube cambió cómo cuenta las vistas. De todos los criterios, es el que menos peso tiene. Usamos el piso de 2 para descartar nichos que, llevados al español, pagarían centavos. Lo más confiable es mirar las vistas mensuales del canal. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-025", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "Mi canal de referencia viene bajando vistas o tiene números en rojo, ¿lo cambio?", "variantes": ["La referencia cada vez monetiza menos", "¿Es grave que tenga números rojos?", "Mi referencia bajó, ¿busco otra?", "¿Qué hago si el canal de referencia está en baja?"], "respuesta": "No te asustes: los canales suben y bajan, nunca están siempre en positivo. Fijate si sigue cumpliendo los números: un outlier el último mes y más de 1 millón de vistas mensuales. Si cumple, tiene demanda; eliminá el «me parece». La señal de alerta es otra: que todos los canales parecidos bajen a la vez, de forma pronunciada. Además, a comienzo de año es normal que todos ganen menos. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-026", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "Encontré un canal con buenas vistas que dejó de publicar hace meses, ¿tomo su tema?", "variantes": ["¿Sirve un canal abandonado?", "El canal no sube videos hace tiempo pero le iba bien", "¿Puedo aprovechar un canal que dejó de publicar?", "¿Un canal inactivo sirve de referencia?"], "respuesta": "No. No cumple los criterios de validación, y lo crucial es justamente el abandono. La pregunta que te tenés que hacer es por qué dejó de publicar si tenía buenas vistas y comentarios; eso despierta sospechas. Puede que haya tenido problemas con la monetización. Buscá un canal activo que cumpla todo, incluido el outlier del último mes. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-027", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Sirve de referencia un canal de videos cortos o que sube muchos Shorts?", "variantes": ["El canal tiene videos de menos de 8 minutos", "¿Me sirve un canal de Shorts?", "¿Importa la duración de los videos?", "¿Conviene un canal que mezcla Shorts y videos largos?"], "respuesta": "Nos enfocamos en videos largos. Si los videos duran menos de 8 minutos, la desventaja es que vas a necesitar muchísimas vistas para tener buenos ingresos, porque cuanto más largo el video, mejor RPM. Por eso en NexLev filtramos sin Shorts. Si un canal mezcla formatos, fijate bien su estrategia. En el primer canal, lo mejor es apegarse al paso a paso. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-028", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "Un nicho cumple todo pero la planilla me lo marca en rojo, ¿qué hago?", "variantes": ["La plantilla me marca todo en rojo", "¿Le hago caso al color de la planilla?", "¿Por qué me sale rojo si cumple?", "La planilla dice que no sirve"], "respuesta": "Si ves que cumple los requisitos, ignorá esa celda. A veces nos equivocamos en algún dato y el color sale mal. Lo importante es que cumpla los criterios de demanda y audiencia: suscriptores, vistas, vistas de los últimos 30 días, outlier. Y tranquilo: es normal encontrar un nicho bueno entre veinte. Dejalo en tu lista y seguí. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-029", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Qué datos anoto de cada canal y dónde los organizo?", "variantes": ["¿Cómo ordeno mi investigación?", "¿Uso Excel para anotar los canales?", "¿Qué tengo que registrar de cada canal?", "¿Hay una plantilla para los nichos?"], "respuesta": "Usá lo que te sea cómodo: Max anota con lápiz y papel, y también podés usar una planilla. Lo principal es registrar los requisitos de cada canal: antigüedad (menos de 6 meses), suscriptores, vistas mensuales, el outlier del último mes con más de 100.000 vistas, RPM aproximado y si está monetizado. Así ves toda tu investigación de un vistazo y podés comparar. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-030", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Cuántos nichos o canales tengo que tener al terminar la investigación?", "variantes": ["¿Busco 3 a 5 nichos o 3 a 5 canales?", "¿Cuántas opciones necesito?", "¿Con un nicho alcanza?", "Terminé el módulo, ¿cuántos nichos debería tener?"], "respuesta": "La meta es tener entre 3 y 5 nichos con canales de referencia que cumplan los requisitos; Max apunta a 5. Conviene diversificar: por ejemplo uno de autos, otro de cocina, otro de salud, otro de finanzas. Después elegís uno entre los mejores. Si encontrás más, anotalos para el futuro. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-031", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "Ya tengo mis 5 canales, ¿cómo decido con cuál me quedo?", "variantes": ["¿Cómo elijo entre varios nichos?", "Tengo varias opciones, ¿cuál elijo?", "¿Qué miro antes de decidir el nicho?", "¿Elijo el primero que cumple?"], "respuesta": "No decidas enseguida. Primero tomate una semana mirando cómo funciona cada canal: ¿las vistas vienen de un video o de muchos? ¿Es un canal estable? ¿Está hecho para monetizar en YouTube o para llevar gente a una página y vender algo? Anotalos y fijate a cuál le va mejor. Recién con eso, y viendo qué se adapta a tu tiempo, elegís. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-032", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "Encontré varios canales chicos y nuevos con el mismo formato, ¿es buena señal?", "variantes": ["Hay seis canales recientes haciendo lo mismo", "¿Muchos canales nuevos iguales es bueno o malo?", "¿Me meto si hay varios canales chicos idénticos?", "¿Es una oportunidad o una trampa?"], "respuesta": "Puede ser una gran señal o una trampa. Varios canales idénticos de pocos meses suele ser un nicho que salió en algún video de «copiá este formato». La pregunta no es cuántos son, sino cómo les va: mirá vistas, no suscriptores. Si los videos recientes sacan 100.000 o más, hay demanda; si sacan 300, no hay nicho. Y si hay demanda en todos, la clave es qué ángulo te diferencia, porque solo sobreviven los distintos. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-033", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Cómo sé si un canal está monetizado de verdad?", "variantes": ["¿Qué extensión uso para ver la monetización?", "NexLev dice que no está monetizado, ¿le creo?", "¿Cómo se llama la extensión de monetización?", "Una herramienta dice monetizado y otra no"], "respuesta": "Hacé doble chequeo. Podés usar la extensión gratuita Monetization Checker de la tienda de Chrome junto con NexLev, que en canales con pocos videos suele fallar. Igual, son herramientas aproximadas: sirven para orientarte, no para decidir. Si te da desmonetizado pero sigue subiendo, hacele seguimiento unos días, porque a veces una herramienta da un dato errado. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-034", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Qué es la cuenta educada y para qué sirve?", "variantes": ["¿Para qué sirve la cuenta educada?", "¿Qué significa educar la cuenta?", "¿Por qué necesito otra cuenta de YouTube?", "¿Cómo encuentro nichos gratis?"], "respuesta": "Es una cuenta de Gmail que usás solo para YouTube y solo para investigar. La entrenás suscribiéndote a canales faceless, sin personas en pantalla, para que el algoritmo te recomiende canales nuevos en auge, que en general cumplen los requisitos que buscamos. Es el método favorito de Max porque no necesitás pagar herramientas. Y ojo: en esa cuenta está prohibido ver lo que mirás por gusto. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-035", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Cómo creo la cuenta educada paso a paso?", "variantes": ["¿Cómo armo la cuenta educada?", "Pasos para educar la cuenta", "¿Qué hago después de crear el Gmail?", "¿Cómo empiezo con la cuenta educada?"], "respuesta": "Creá un Gmail con un nombre que te recuerde que es la cuenta educada y verificalo con teléfono y correo alternativo. Iniciá sesión en YouTube con esa cuenta: va a estar vacía. Entrá a Shorts y volvé a Principal; ahí te aparecen videos. Suscribite solo a los canales donde no aparece ninguna persona, refrescá para que salgan más y repetí todos los días, sumando likes y comentarios. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-036", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Puedo usar mi cuenta personal de siempre como cuenta educada?", "variantes": ["¿Necesito un correo nuevo para la cuenta educada?", "¿Sirve un mail viejo que ya tengo?", "¿Investigo desde mi YouTube personal?", "¿Tiene que ser un Gmail nuevo?"], "respuesta": "Tu cuenta personal no, porque tiene todo tu historial y el algoritmo te va a mostrar lo de siempre. Podés crear un Gmail nuevo o usar un mail viejo que ya tengas, siempre que no tenga visualizaciones previas en YouTube, para que no esté viciado con tu historial. Como correo de recuperación sí podés poner tu mail de toda la vida. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-037", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Puedo usar la cuenta educada para subir los videos de mi canal?", "variantes": ["¿La cuenta educada y la del canal son la misma?", "¿Cuántas cuentas necesito?", "¿Subo mis videos desde la cuenta educada?", "Ya eduqué una cuenta, ¿la uso para mi canal?"], "respuesta": "No, siempre separadas. La cuenta educada es solo para investigar, y no conviene desarmarla: es muy valiosa. Para tu canal creás otra cuenta, y si un día hacés otro canal, otra más. En total vas a manejar tres: tu personal, la cuenta educada (suscrita a faceless de todo tipo) y la cuenta de tu canal (suscrita a faceless de tu nicho). Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-038", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "Entro a YouTube con la cuenta nueva y el inicio está vacío o negro, ¿qué hago?", "variantes": ["No me aparece ningún video", "La pantalla de inicio está en negro", "La cuenta nueva no me muestra nada", "¿Por qué YouTube no me recomienda nada?"], "respuesta": "Es normal: la cuenta no tiene historial y por eso no te muestra nada. Entrá a la pestaña Shorts, a la izquierda, y después volvé a Principal, justo arriba. Ahí te van a aparecer videos. Suscribite a los canales sin personas en pantalla y refrescá para que aparezcan más. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-039", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "La cuenta educada me muestra siempre los mismos canales o un solo tema, ¿qué hago?", "variantes": ["Me aparecen siempre los mismos videos", "Solo me muestra canales de un tema", "La cuenta educada no me da variedad", "¿Por qué no me salen canales nuevos?"], "respuesta": "Paciencia: el algoritmo tarda unos días en aprender. Mientras tanto, refrescá la página, suscribite a variedad de canales faceless (no solo los que te interesan) y buscá con la lupa temas distintos para suscribirte a canales nuevos. Si un tema aparece de más, en los tres puntitos al lado del título elegí «No me interesa». Así vas domando la cuenta. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-040", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿A cuántos canales me suscribo por día en la cuenta educada?", "variantes": ["¿Cuántas suscripciones por día?", "¿Me suscribo a todos los que aparecen?", "¿Hay un límite de suscripciones?", "¿Puedo suscribirme a muchos de golpe?"], "respuesta": "Alrededor de 20 por día, no más, y comentá algo en esos canales para que YouTube no te tome como spam. Suscribite a todos los faceless que te muestre, sin importar el nicho: lo que querés es que YouTube tenga clarísimo que esa cuenta consume solo ese formato. Dar like y comentar acelera el proceso. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-041", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Cuánto tarda la cuenta educada en empezar a funcionar?", "variantes": ["¿En cuántos días me muestra buenos canales?", "¿Cuánto tiempo le dedico por día?", "Hace dos días que la eduqué y no veo resultados", "¿Cuándo empieza a recomendarme faceless?"], "respuesta": "Unos días. Al principio te va a dar poca variedad, pero en cuestión de días te empieza a mostrar buenos canales. Entrá todos los días, con unos 15 minutos alcanza, y no dejes de suscribirte, dar like y comentar, que eso lo acelera. Que no te gane la ansiedad: paciencia, investigación, constancia y optimización. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-042", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Puedo buscar cosas con la lupa en la cuenta educada o arruino el algoritmo?", "variantes": ["¿Hacer búsquedas en la cuenta educada la daña?", "¿Puedo buscar un nicho específico?", "¿Está bien usar el buscador en la cuenta educada?", "¿Cómo busco un tema que me interesa?"], "respuesta": "Sí, podés y está bien usar la lupa para buscar un nicho que te interese. Después suscribite solo a los canales faceless. Tené en cuenta que si comentás, mirás o seguís esos canales, YouTube entiende que el tema te interesa y te va a mostrar más. Si empieza a aparecer de más, desde los tres puntitos al lado del título marcá «No me interesa». Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-043", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "Creé la cuenta educada pero me sigue mostrando lo de mi cuenta personal, ¿por qué?", "variantes": ["Me aparecen los videos de siempre", "La cuenta nueva muestra mi historial viejo", "¿Por qué veo mis recomendaciones personales?", "Estoy en el correo nuevo pero veo lo de antes"], "respuesta": "Seguramente estás en el perfil equivocado. Muchas veces, aunque entres con el correo nuevo, YouTube abre con el último perfil que usaste. Fijate arriba a la derecha que estés en la cuenta educada. Si de verdad estás en una cuenta completamente nueva, no debería mostrarte nada, porque nunca vio un video. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-044", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "YouTube me traduce automáticamente los títulos, ¿cómo lo evito?", "variantes": ["Me aparecen los títulos traducidos", "¿Cómo veo los títulos en su idioma original?", "YouTube me cambia el idioma de los videos", "Busco competencia y todo sale traducido"], "respuesta": "Pasa porque tu cuenta está configurada en un idioma y te autotraduce. Arriba a la derecha, en tu foto de perfil, configurá el idioma y el país que quieras, por ejemplo español latinoamericano y tu país. Así YouTube respeta el idioma original de títulos y descripciones. Si tu ubicación real no coincide con lo configurado, ajustá idioma y ubicación para que coincidan. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-045", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿En qué idioma tienen que ser los canales a los que me suscribo con la cuenta educada?", "variantes": ["¿Me suscribo a canales en inglés o en español?", "¿Importa el nicho de los canales que sigo?", "¿Solo canales de mi tema?", "¿Qué canales sigo en la cuenta educada?"], "respuesta": "Da igual el idioma, el formato o el nicho. Lo único obligatorio es que sean faceless, es decir, canales donde no aparece ninguna persona. Suscribite a todos los que te muestre, de cualquier tema; la idea es que YouTube entienda que esa cuenta consume solo ese formato y te traiga canales nuevos en auge. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-046", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Conviene tener dos cuentas educadas, una en español y otra en inglés?", "variantes": ["¿Hago una cuenta educada por idioma?", "¿Puedo tener varias cuentas educadas?", "Quiero cambiar mi cuenta educada a otro idioma", "¿Necesito otra cuenta para buscar en inglés?"], "respuesta": "No lo recomendamos, salvo que ya tengas cuentas creadas de antes: crear muchas cuentas nuevas de golpe empieza a parecer actividad de bot. Si querés pasar tu cuenta educada a otro idioma, no hace falta otra: en cada video, desde los tres puntitos, marcá «No me interesa» en los del idioma que no querés y suscribite solo a canales del otro. Así la transformás. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-047", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Educo la cuenta en modo incógnito?", "variantes": ["¿Uso una pestaña de incógnito?", "¿Tengo que estar logueado?", "¿Puedo educar sin iniciar sesión?", "¿Funciona la cuenta educada en incógnito?"], "respuesta": "No. Para educar la cuenta tenés que estar logueado con ella, no en modo incógnito, porque el algoritmo aprende de las suscripciones, likes y comentarios de esa cuenta. La pestaña de incógnito te sirve para otra cosa: buscar palabras clave de un nicho sin que influya tu historial. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-048", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Cómo sé de qué país o idioma es un canal?", "variantes": ["¿Cómo sé si un canal es en inglés o en español?", "VidIQ no me dice el país del canal", "¿Cómo veo el idioma original de un video?", "¿El canal está traducido o es original?"], "respuesta": "Mirá la descripción y la pista de audio original de algún video. En la tuerquita de abajo a la derecha del video entrás a «Audio»: si dice inglés original, es un canal en inglés. Si dice español, ojo, porque puede ser un video en español o uno que YouTube eligió traducir. Esto lo ves en la clase «Cuenta Educada».", "silver": false}, {"id": "g2-049", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Necesito pagar ChatGPT u otra IA para investigar nichos?", "variantes": ["¿Tengo que pagar alguna IA para investigar?", "¿Alcanza con herramientas gratis?", "¿Qué tengo que pagar para empezar la investigación?", "¿Necesito suscripciones para buscar nicho?"], "respuesta": "No. Para investigar te alcanza con la cuenta educada y la versión gratuita de VidIQ, sin pagar nada. Como dice Max, para él la mejor herramienta es la cuenta educada. Las suscripciones de producción las evaluás después, cuando ya tengas el nicho y sepas qué necesita tu canal. Esto lo ves en la clase «Cuenta Educada».", "silver": false, "video": {"id": "-P_oD0PYlts", "titulo": "NO le Pidas NICHOS RENTABLES de YOUTUBE a la IA (hasta ver esto)", "url": "https://www.youtube.com/watch?v=-P_oD0PYlts"}}, {"id": "g2-050", "modulo": "M3", "clase": "Cuenta Educada", "pregunta": "¿Qué extensiones y programas necesito para investigar?", "variantes": ["¿Qué tengo que instalar?", "¿Qué extensiones de Chrome se usan?", "¿Qué navegador uso para investigar?", "¿Qué apps necesito en la compu?"], "respuesta": "Intentá ser minimalista. Para investigar usamos Google Chrome, porque las extensiones funcionan bien ahí, y estas extensiones: VidIQ y NexLev para métricas, Monetization Checker para ver si el canal está monetizado y YouTube Summary para sacar transcripciones. No hace falta pagar NexLev al principio. Los plugins se instalan en el navegador, no en el canal, así que podés sacarlos cuando quieras. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-051", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Tengo que pagar NexLev para encontrar nicho?", "variantes": ["¿Es obligatorio NexLev?", "¿Vale la pena pagar NexLev?", "¿Me conviene el plan caro de NexLev?", "¿NexLev es necesario para empezar?"], "respuesta": "No es necesario. La mejor herramienta para encontrar nichos es la cuenta educada, y es gratis. NexLev cuesta unos 42 euros por mes y lo recomendamos cuando ya tenés canales monetizados. Según Lau, lo que más vale de NexLev es «canales similares», que ahorra mucho tiempo, y si la pagás conviene hacerlo solo durante la investigación y después cancelarla. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-052", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Por dónde empiezo a buscar nichos dentro de NexLev?", "variantes": ["¿Cómo uso NexLev?", "¿Qué sección de NexLev miro primero?", "¿Qué son los outliers recientes?", "Abrí NexLev y no sé qué hacer"], "respuesta": "Instalá la extensión, entrá al dashboard y abrí el buscador de nichos. El mejor punto de partida son los «outliers recientes», videos que explotaron en las últimas 24 horas, y se renuevan todos los días. Entrá a cada canal y validá suscriptores, antigüedad, videos populares y estado de monetización. Después validá a mano el que elijas: vistas, frecuencia y dificultad de edición. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-053", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Qué filtros pongo en NexLev para buscar canales?", "variantes": ["¿Cómo configuro los filtros de Long Form Channels?", "¿Qué filtros recomiendan?", "¿Cómo filtro canales faceless en NexLev?", "¿Qué pongo en la búsqueda avanzada?"], "respuesta": "En Long Form Channels usá la búsqueda avanzada con estos filtros: monetizado, faceless, sin contenido para niños, sin Shorts, menos de 50.000 suscriptores y alrededor de 1 a 2 millones de vistas. Así te quedan canales que se acercan a los requisitos. Después igual entrás a cada uno y lo validás a mano. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-054", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Para qué sirve la función «canales similares» de NexLev?", "variantes": ["¿Cómo encuentro más canales parecidos a mi referencia?", "¿Qué es Similar Channels?", "¿Cómo uso la búsqueda profunda?", "Canales similares me da cualquier cosa"], "respuesta": "Te muestra canales parecidos al que estás mirando y simplifica muchísimo la búsqueda. Usá la búsqueda profunda y quedate solo con los de la misma estética, porque un nicho es temática + estética. Ojo: funciona bien en inglés, pero en español da pocos resultados porque tiene pocos canales escaneados. Y la idea es encontrar un ángulo nuevo, no copiar. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-055", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Uso las keywords en tendencia o la sección de saturación de NexLev?", "variantes": ["¿Sirven las palabras clave en tendencia?", "¿Busco lo más buscado?", "¿Qué es la sección de saturación?", "¿El Niche Finder sirve?"], "respuesta": "Mejor evitalas. Te dan lo más buscado, que también es lo más competido. Lo que busca el método son los nichos emergentes, no los que ya están de moda y llenos de canales. Lau es todavía más directo: el buscador de nichos suele tirar resultados genéricos y repetidos. Arrancá por los outliers recientes y por canales similares. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-056", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Con qué email pago NexLev y sirve para todos mis canales?", "variantes": ["¿Contrato NexLev con el mail del canal o el personal?", "¿Una cuenta de NexLev sirve para varios canales?", "¿Necesito un NexLev por canal?", "¿En qué cuenta activo NexLev?"], "respuesta": "Usá cualquier email personal. El buscador de nichos se usa desde la página de NexLev, no desde YouTube, y la extensión funciona como un plugin del navegador, así que te aparece en cualquier canal que tengas logueado. Con la misma cuenta podés analizar desde afuera todos tus canales, igual que analizás referencias y competencia. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-057", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "VidIQ no me muestra los datos o me marca 0 de ingresos, ¿qué hago?", "variantes": ["VidIQ no anda", "La extensión no me muestra los stats", "VidIQ me da ganancias en cero", "No me aparecen los suscriptores en las miniaturas"], "respuesta": "Es habitual y suele ser temporal: pasa cuando actualizan la app o la API de YouTube, y se resuelve en unas horas o días. Probá cerrar y abrir el navegador; si sigue, borrá las cookies o desinstalá y volvé a instalar la extensión. Y recordá que toda la información que necesitás para investigar la podés sacar a mano del propio canal. Es más tedioso, pero se puede. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-058", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "VidIQ dice que un canal sube 0 videos por semana, ¿qué significa?", "variantes": ["¿Por qué aparece 0 videos por semana?", "VidIQ muestra frecuencia cero", "¿El canal dejó de subir?", "¿Cómo veo cada cuánto publica un canal?"], "respuesta": "Puede ser que el canal haya dejado de subir o un error. VidIQ pone 0 cuando la cadencia es menor a un video por semana, algo común en canales que suben poco o de forma irregular. Lo mejor es comprobarlo a mano: mirá debajo de cada título cuándo se publicó y contá cuántos videos sube por mes. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-059", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Sirven otras herramientas para buscar nichos, como HacksLabs?", "variantes": ["¿Pruebo otras apps de nichos?", "¿HacksLabs es buena?", "¿Hay algo mejor que NexLev?", "¿Pago otra herramienta de nichos virales?"], "respuesta": "No la necesitás. Según Lau, es lo mismo que el resto de estas herramientas: un empaquetado, con datos estimados y IA por debajo a la que ya tenés acceso. Para investigar te alcanza con la cuenta educada, VidIQ gratis y, si querés, NexLev durante la investigación. Las herramientas son eso, herramientas: lo que vale es el método. Esto lo ves en la clase «Ejemplo NexLev».", "silver": false}, {"id": "g2-060", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "Con el cambio de YouTube que cuenta vistas desde el primer segundo, ¿cómo leo las estadísticas?", "variantes": ["¿Cambió cómo se cuentan las vistas?", "¿Qué son las vistas con interacción?", "¿Las vistas de los canales ahora están infladas?", "¿Afecta el cambio de vistas a la investigación?"], "respuesta": "Desde agosto, en todos los formatos, una vista cuenta desde el primer fotograma, incluso la reproducción automática al pasar el cursor por la miniatura. Lo que antes era «vista» ahora se llama «vista con interacción». Según YouTube, los ingresos se siguen calculando con vistas con interacción y los requisitos para monetizar no cambiaron. Por eso hoy las herramientas son más inexactas: tomá sus estimaciones con pinzas. Esto lo ves en la clase «Requisitos del nicho ideal».", "silver": false}, {"id": "g2-061", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Cuántos canales de competencia en español necesito para validar el nicho?", "variantes": ["¿Cuántos competidores tiene que haber?", "¿Cómo valido la competencia?", "¿Los competidores tienen que cumplir todos los requisitos?", "¿Cuántos canales en español son aceptables?", "¿Cuántos canales de competencia necesito para validar un nicho?", "¿cómo valido un nicho?", "¿qué requisitos tiene que cumplir la competencia?", "¿cómo sé si un nicho sirve?", "¿cuántos competidores tiene que haber?"], "respuesta": "Lo básico: la competencia en tu idioma puede ser más flexible que la referencia, y lo que más importa son sus vistas del mes, porque muestran que hay demanda en ese mercado. Si no hay gente mirando ese contenido en tu idioma, el nicho no está validado ahí. Cómo contar, medir y validar la competencia es un proceso aparte. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-062", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Cómo busco la competencia en español de un canal de referencia en inglés?", "variantes": ["Mi referencia está en inglés, ¿cómo encuentro canales en español?", "¿Cómo encuentro competidores en mi idioma?", "El nombre del canal no se traduce, ¿cómo busco?", "¿Dónde busco la competencia?"], "respuesta": "Lo básico: la competencia se busca en el mismo idioma en que vas a hacer tu canal. Una forma simple es traducir al español los títulos de varios outliers de la referencia y buscarlos en YouTube para ver qué canales aparecen, quedándote solo con los que se parecen en temática y estética. Dale varios días a esa búsqueda. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-063", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Cómo sé si un nicho está saturado?", "variantes": ["¿Cuándo hay demasiados canales en un nicho?", "¿Cómo detecto saturación?", "Aparecen canales nuevos todos los días, ¿se saturó?", "¿Hay demasiada competencia?", "¿hay demasiados canales de mi tema?", "mi canal de referencia viene bajando", "¿el nicho se saturó?", "la competencia tiene números en rojo"], "respuesta": "Lo básico: no te guíes por la cantidad de canales sino por cómo les va. Una señal de alerta es que casi todos los canales del nicho vengan a la baja al mismo tiempo. Si los nuevos tienen vistas, hay demanda. El análisis completo de saturación forma parte de la validación de competencia. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-064", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "Encontré un nicho que cumple todo pero no hay canales en español, ¿es mala señal?", "variantes": ["No hay competencia en español, ¿arranco igual?", "¿Qué es un canal pionero?", "El nicho solo existe en inglés", "¿Conviene ser el primero en español?"], "respuesta": "Lo básico: si no hay canales en español sería un canal pionero, y no tiene término medio: puede irte muy bien o muy mal, porque no sabés si hay demanda en ese idioma. Hay temas que funcionan en un idioma y en otro no. Para el primer canal conviene ir a lo probado. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "PV_F1EqF1aA", "titulo": "5 NICHOS DE YOUTUBE Que Pagan En Dólares y En Español están VACÍOS", "url": "https://www.youtube.com/watch?v=PV_F1EqF1aA"}}, {"id": "g2-065", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Cómo sé si voy a poder hacer los videos de ese nicho si no sé editar?", "variantes": ["No sé editar, ¿qué nicho elijo?", "¿Cómo sé si puedo igualar la producción?", "¿Cuánto cuesta producir los videos del nicho?", "¿El canal es muy difícil de hacer para mí?"], "respuesta": "Lo básico: uno de los requisitos es que el canal sea factible de igualar o mejorar en producción: voces, miniaturas, animaciones y guiones. Tené en cuenta tu tiempo y tu presupuesto al elegir, porque no todos los canales llevan IA. Evaluar a fondo si podés producirlo es la factibilidad técnica. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "vR6HZv7hHWM", "titulo": "7 ERRORES Letales que cometes en YOUTUBE FACELESS", "url": "https://www.youtube.com/watch?v=vR6HZv7hHWM"}}, {"id": "g2-066", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Cómo averiguo con qué programa o técnica edita el canal de referencia?", "variantes": ["¿Qué herramientas usa ese canal?", "¿Cómo sé qué IA usa la referencia?", "¿Cómo se llama ese estilo de animación?", "¿Cómo replico la estética de un canal?"], "respuesta": "Lo básico: podés sacar capturas del video y preguntarle a una IA cómo se llama esa técnica de animación; con ese nombre buscás tutoriales en YouTube. Pero primero terminá la investigación: entender cómo se produce un canal es parte de la factibilidad técnica. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-067", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Sirve un canal sin narración, solo con imágenes y música?", "variantes": ["¿Un canal de música con IA sirve?", "Encontré un canal sin guion que cumple los requisitos", "¿Puedo hacer videos sin voz?", "¿Canales solo de música monetizan?", "¿canal sin voz?", "¿solo música con ia?", "¿videos sin guion monetizan?", "¿canal de frases e imágenes?", "¿Sirve un canal sin narración, solo con imágenes, música y frases?", "canal sin voz se puede monetizar", "videos solo con música e imágenes", "canal sin guion monetiza?", "puedo hacer videos sin narrar"], "respuesta": "Lo básico: no los recomendamos. Aunque cumplan los requisitos, en general son desmonetizados o rechazados, porque YouTube los toma como contenido de bajo esfuerzo. Que aparezca monetizado no asegura que esté ganando. Seguí buscando un nicho con narración. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "QDI67WVg1OY", "titulo": "Esto es lo que está pasando en YouTube ahora I DESMONETIZADOS", "url": "https://www.youtube.com/watch?v=QDI67WVg1OY"}}, {"id": "g2-068", "modulo": "M2", "clase": "Requisitos del nicho ideal", "pregunta": "¿Conviene hacer un canal infantil?", "variantes": ["¿Sirve un canal para niños?", "¿El contenido para chicos es buen nicho?", "¿Puedo hacer YouTube Kids con IA?", "¿Es escalable un canal infantil?"], "respuesta": "Lo básico: depende de tu tolerancia al riesgo, porque YouTube es muy estricto con ese contenido, y de tu paciencia, porque el RPM es bajo y necesitás masividad. Por eso, al buscar en NexLev, filtramos sin contenido para niños. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-069", "modulo": "M2", "clase": "El Método del SEN6", "pregunta": "¿Me pueden revisar o validar el nicho que encontré?", "variantes": ["¿Alguien revisa mi investigación?", "¿Me validan el canal de referencia?", "¿Puedo mandar mi nicho para que lo vean?", "¿Me dan feedback de mi nicho?"], "respuesta": "Lo básico: en Lite el camino es seguir al pie de la letra la validación de las clases: los requisitos del nicho ideal y el doble chequeo de cada canal. La revisión personalizada de tu investigación no está incluida acá. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g2-070", "modulo": "M3", "clase": "Ejemplo NexLev", "pregunta": "¿Cómo conecto NexLev con Claude o ChatGPT?", "variantes": ["¿Se puede usar NexLev gratis con Claude?", "¿Cómo uso NexLev por MCP?", "¿Qué permisos le doy a Claude con NexLev?", "Dejó de funcionar NexLev en Claude", "¿Cómo conecto NexLev con Claude?", "nexlev en claude", "cómo instalo nexlev", "claude no usa nexlev", "conectar nexlev gratis"], "respuesta": "Lo básico: NexLev se puede conectar a una IA para consultarle datos de canales y nichos, con un límite diario de consultas. No es necesario para la investigación de Lite: con la cuenta educada y las extensiones alcanza. El paso a paso de conectar herramientas con IA no está en Lite. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "EnKuUTUqtE8", "titulo": "Aprende Cómo CRECER EN YOUTUBE FACELESS I Claude + Nexlev", "url": "https://www.youtube.com/watch?v=EnKuUTUqtE8"}}, {"id": "g3-001", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Qué cuenta de Gmail uso para abrir mi canal?", "variantes": ["¿con qué mail creo el canal?", "¿me hago un gmail nuevo o uso el mío?", "¿qué correo pongo para youtube?", "¿necesito un gmail especial para el canal?"], "respuesta": "Para tu primer canal creá una cuenta de Gmail nueva, eligiendo la opción «para uso personal». Las cuentas más antiguas generan más confianza porque YouTube ya tiene tu historial, pero la recomendación es guardarlas como un tesoro para más adelante, cuando tengas experiencia y encuentres una oportunidad de oro. Ahora arrancá con una nueva y calentala bien antes de subir. Esto lo ves en la clase «Abrir un canal».", "silver": false}, {"id": "g3-002", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Puedo abrir el canal en mi cuenta personal de toda la vida?", "variantes": ["¿uso mi youtube personal para el canal?", "¿sirve mi cuenta vieja con historial?", "¿abro el canal en mi gmail de siempre?", "mi cuenta tiene años, ¿la aprovecho?"], "respuesta": "Técnicamente podés, y una cuenta vieja con historial limpio da un piso de confianza. Pero ojo: no te asigna más impresiones por ser antigua; la distribución se gana video a video. Por eso Max y Lau recomiendan no quemar ese activo en tu primer canal: guardala para cuando domines el método y tengas un nicho que valga la pena. Para arrancar, cuenta nueva y bien calentada.", "silver": false}, {"id": "g3-003", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Puedo tener varios canales con un mismo Gmail?", "variantes": ["¿un mail para todos mis canales?", "¿cuántos canales por cuenta de google?", "¿hago un correo por canal?", "¿puedo crear otro canal con el mismo correo?", "¿Puedo tener varios canales en el mismo Gmail?", "todos mis canales en una cuenta de google", "un correo para cada canal hace falta", "varios canales un solo mail", "riesgo de tener todo en un gmail"], "respuesta": "Se puede técnicamente, pero la regla es una cuenta de correo por canal. Si un canal recibe una penalización grave o te hackean, todos los que cuelgan de ese mismo correo pueden caer juntos. Separarlos es proteger tu trabajo. Si ya creaste alguno en la misma cuenta no pasa nada, pero de acá en adelante, un Gmail para cada canal.", "silver": false}, {"id": "g3-004", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿La cuenta educada y la cuenta del canal son la misma?", "variantes": ["¿subo videos en la cuenta educada?", "¿uso la cuenta de investigar para el canal?", "¿cuenta educada y canal van juntos?", "¿cuántos mails necesito?"], "respuesta": "No, van separadas. La cuenta educada es solo para investigar nichos y no se toca. Cuando encontrás tu nicho, creás otro correo nuevo y ahí abrís el canal con el que vas a trabajar, que es el que después calentás. Si algún día hacés otro canal, otro correo. Siempre separados.", "silver": false}, {"id": "g3-005", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Cuáles son los pasos para crear el canal?", "variantes": ["¿cómo abro un canal de youtube?", "¿dónde toco para crear el canal?", "paso a paso para abrir el canal", "¿cómo hago el canal desde cero?"], "respuesta": "Es simple: creá tu Gmail para uso personal, entrá a YouTube con esa cuenta (o agregala desde «cambiar de cuenta»), tocá «crear un canal», poné el nombre y el identificador que elegiste con IA y crealo sin foto. El logo, el banner y la descripción se suman después. Esto lo ves en la clase «Abrir un canal».", "silver": false}, {"id": "g3-006", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Pongo foto, logo y descripción cuando creo el canal?", "variantes": ["¿subo el logo al crear el canal?", "¿qué foto pongo en el canal?", "¿cuándo pongo el banner?", "¿lleno la descripción al abrirlo?"], "respuesta": "No subas foto al crear el canal. El logo, el banner y la descripción van en la clase siguiente, donde los armás con IA con la herramienta que está debajo del video. Primero creás el canal limpio, con nombre e identificador, y después lo vestís. Esto lo ves en la clase «Abrir un canal».", "silver": false}, {"id": "g3-007", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Cómo elijo el nombre y el identificador del canal?", "variantes": ["¿qué nombre le pongo al canal?", "¿qué es el identificador?", "¿el @ va con arroba?", "¿cómo invento el nombre del canal?"], "respuesta": "No crees el canal hasta ver la clase siguiente, porque el nombre y el identificador se eligen con IA. El identificador es tu @ único y se escribe sin la arroba, por ejemplo HormigaReyESP. Lau recomienda que sea simple y fácil de recordar, sin números raros ni combinaciones forzadas, porque así es como te van a buscar. Esto lo ves en la clase «Abrir un canal».", "silver": false}, {"id": "g3-008", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "YouTube no me acepta el nombre del canal y me hace esperar 24 horas, ¿qué pasó?", "variantes": ["me rechaza el identificador", "no me deja crear el canal, espere 24 hs", "dice que el @ ya existe", "me bloqueó por intentar muchas veces"], "respuesta": "Varios canales pueden llamarse igual, pero el identificador con @ es único: si ya lo tiene otro, te lo va a rechazar siempre. Y si insistís muchas veces seguidas, el sistema cree que sos un bot y te frena 24 horas. Respetá esa espera sin intentar nada y después probá con una variante distinta del identificador.", "silver": false}, {"id": "g3-009", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "Mi número de teléfono ya está usado en otras cuentas, ¿cómo creo el Gmail nuevo?", "variantes": ["no me deja crear gmail con mi número", "me pide verificar con QR", "mi celular ya tiene muchas cuentas", "¿qué número pongo para el gmail?"], "respuesta": "Tenés dos opciones: usar el teléfono de alguien de confianza (ese número no te lo vuelven a pedir) o un servicio de número temporal como SMS Virtual, que usan muchos en la comunidad. Si te vas a dedicar a esto a largo plazo, Max recomienda tener un teléfono usado cualquiera e ir sumando números, así no cansás a la familia.", "silver": false}, {"id": "g3-010", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Es obligatorio verificar el canal con un número de teléfono?", "variantes": ["¿tengo que poner mi celular en youtube?", "¿para qué verifico el teléfono?", "¿cuántos canales verifico con un número?", "¿hace falta verificar el canal?"], "respuesta": "Sí, es obligatorio, y conviene dejarlo configurado bien antes de lanzar tus videos para que nada te corte el proceso. Con un mismo número podés verificar 2 canales al año. Si te dice que el número ya se usó, no insistas con ese: conseguí otro, porque insistir da señales de bot.", "silver": false}, {"id": "g3-011", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "Verifiqué el teléfono pero no se habilitan las funciones, ¿qué hago?", "variantes": ["verifiqué el celular y no pasa nada", "¿cuánto tarda la verificación?", "¿cómo sé si el canal ya está verificado?", "dice verificado pero no se activa"], "respuesta": "En general es instantánea, pero puede demorar unas horas. Para confirmarlo andá a YouTube Studio, Configuración, Canal, Elegibilidad de funciones: lo importante es que ahí aparezca en verde. A veces YouTube marca que ya está verificado y no es así; en ese caso borrá las cookies del navegador y verificá de nuevo.", "silver": false}, {"id": "g3-012", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "YouTube me dice que el número ya está usado o que lo intenté demasiadas veces, ¿qué hago?", "variantes": ["error al enviar el código de verificación", "me dice demasiados intentos", "no me llega el código de youtube", "el número ya fue utilizado"], "respuesta": "No insistas con el mismo número, porque YouTube te puede bloquear el proceso por horas o días pensando que sos un bot. Dejá pasar un día y volvé a intentar; si sigue fallando, cambiá de número (el de un familiar o una app de número temporal). Si ya lo intentaste muchas veces, dale descanso varios días antes de probar otra vez.", "silver": false}, {"id": "g3-013", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "No puedo subir una miniatura propia, solo me deja elegir un fotograma, ¿por qué?", "variantes": ["no se guarda mi miniatura", "solo me deja poner fotogramas del video", "¿por qué no puedo cambiar la miniatura?", "no me aparece subir miniatura"], "respuesta": "Casi siempre es porque todavía no completaste la configuración del canal: teléfono e identidad verificados. Sin eso YouTube solo te deja elegir fotogramas del video. Revisá que los pasos estén habilitados. Si ya está todo y aun así no se guarda, probá borrar las cookies (acordate tus contraseñas) o mandá comentarios a soporte.", "silver": false}, {"id": "g3-014", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Qué país pongo en la configuración del canal?", "variantes": ["¿pongo estados unidos para ganar más?", "¿qué país de residencia elijo?", "¿el país tiene que ser el de adsense?", "¿puedo cambiar el país después?", "vivo en un país y cobro en otro", "¿el país del canal importa?", "¿tiene que coincidir con adsense?"], "respuesta": "Poné tu país real, el de la persona que va a recibir el dinero. Si todavía no tenés AdSense no pasa nada, pero la idea es que coincida con tu futura cuenta, porque con ese ajuste YouTube define si podés entrar al Programa de Socios y qué leyes locales aplican a tu canal. Elegir un país que no es el tuyo para «ganar más» te puede traer problemas después.", "silver": false}, {"id": "g3-015", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Marco mis videos como contenido para niños?", "variantes": ["¿es contenido para niños o no?", "¿qué marco en audiencia?", "¿marcar para niños da más vistas?", "¿qué pongo en apto para menores?"], "respuesta": "Si tu contenido no está hecho para chicos, marcá siempre que no es para niños, a nivel canal y en cada video. No es una preferencia para abarcar más público: es un requisito técnico, y si lo marcás como infantil YouTube te bloquea funciones clave y apaga anuncios. Leé las reglas de YouTube sobre contenido infantil para estar seguro.", "silver": false}, {"id": "g3-016", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "Ya tengo canales viejos que no uso, ¿los borro y creo uno nuevo?", "variantes": ["¿borro mis canales viejos?", "tengo canales vacíos, ¿qué hago?", "¿uso un canal que abrí hace tiempo?", "¿creo más canales o reutilizo?"], "respuesta": "No los borres: reutilizalos. Esas cuentas antiguas te sirven para mostrarle a YouTube que sos humano. Tampoco crees canales que no vas a usar, porque muchos canales juntos pueden parecer un bot. Tomá uno, cambiale nombre, banner y logo, y acordate de calentar la cuenta antes de subir. Esto lo ves en la clase «Abrir un canal».", "silver": false}, {"id": "g3-017", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "El canal que voy a reutilizar tiene videos o shorts personales viejos, ¿los borro?", "variantes": ["tengo videos viejos en el canal", "¿pongo en privado los shorts viejos?", "¿borro el contenido anterior?", "¿oculto los videos personales?"], "respuesta": "No los borres. Podés dejarlos o pasarlos a no listado o privado, como prefieras. Que haya contenido personal es una buena señal de que sos humano. Si el canal viejo tiene muchos suscriptores y videos de otra temática, analizalo con más cuidado, porque esa audiencia no va a responder a tu nuevo nicho.", "silver": false}, {"id": "g3-018", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "¿Qué es calentar la cuenta?", "variantes": ["¿qué significa calentar el canal?", "¿para qué sirve el calentamiento?", "calentar cuenta, ¿qué es?", "¿por qué hay que calentar la cuenta?"], "respuesta": "Calentar la cuenta es, antes de subir tu primer video, usarla como un humano para que YouTube confíe en vos y no te confunda con un bot. Mirás videos de tu nicho completos y con volumen, das like, te suscribís, comentás y respondés comentarios. Es uno de los pasos fundamentales, Max dice que hoy es vital. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-019", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "¿Cuántos días tengo que calentar la cuenta?", "variantes": ["¿cuánto dura el calentamiento?", "¿cuántos días antes de subir?", "¿alcanza con una semana?", "¿cuándo puedo subir el primer video?"], "respuesta": "Entre 8 y 15 días, y lo óptimo son 15. No subas videos antes de terminar ese período. No es tiempo perdido: mientras calentás, producís los videos que vas a necesitar para el lanzamiento. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-020", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "¿Qué tengo que hacer cada día durante el calentamiento?", "variantes": ["¿cuántos videos miro por día?", "¿cómo se calienta la cuenta paso a paso?", "¿qué hago en los 15 días?", "rutina de calentamiento"], "respuesta": "Todos los días mirá al menos 5 videos de tu nicho completos, con volumen y viendo también el anuncio del principio. Dales like, suscribite y dejá comentarios elaborados y naturales; también respondé algún comentario de otro usuario. Sumá búsquedas del tema y mirá shorts del nicho. Repetí durante 15 días. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-021", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "¿Puedo dejar los videos corriendo con el volumen en cero mientras hago otra cosa?", "variantes": ["¿dejo videos en silencio?", "¿sirve poner videos y no mirarlos?", "¿puedo acelerar el calentamiento?", "¿vale reproducir en segundo plano?"], "respuesta": "No. El calentamiento tiene que ser real: mirá los videos, no los dejes correr. Con volumen, completos, y comentando cosas relacionadas con lo que viste. La idea es justamente no parecer un bot, y dejar videos en silencio de fondo es lo que haría uno. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-022", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "Encontré mi nicho hoy, ¿igual tengo que esperar 15 días para publicar?", "variantes": ["¿puedo saltear el calentamiento?", "¿acorto los 15 días?", "quiero subir ya, ¿espero?", "¿calentar no me hace perder tiempo?"], "respuesta": "Sí, esperá, pero no de brazos cruzados. Empezar rápido significa calentar la cuenta a la vez que producís los videos, porque para el lanzamiento los tenés que tener hechos. Así, cuando terminan los días de calentamiento, ya estás listo para la subida 3-2-1. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-023", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "¿Cuántos videos tengo que tener listos antes de terminar el calentamiento?", "variantes": ["¿cuántos videos produzco antes de lanzar?", "¿qué hago mientras caliento?", "¿necesito videos guardados?", "¿cuántos videos para empezar?"], "respuesta": "Aprovechá los días de calentamiento para producir. La clase pide tener al menos 5 videos hechos (2 o 3 si son muy elaborados) para arrancar con la subida 3-2-1. Fijate que 3+2+1 son seis videos en los tres primeros días, así que cuantos más tengas listos, más tranquilo lanzás. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-024", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "Mi cuenta es vieja, ¿igual tengo que calentarla?", "variantes": ["¿una cuenta antigua necesita calentamiento?", "tengo un gmail de hace años, ¿caliento?", "¿las cuentas aged se calientan?", "¿si ya uso youtube tengo que calentar?"], "respuesta": "Sí. Aunque la cuenta sea antigua, hay que calentarla: usarla como humano unos 15 días mirando, comentando y dando likes en videos del nicho que vas a trabajar. Si es tu cuenta personal y la usás seguido en YouTube, ya tenés parte del camino hecho, pero igual conviene orientarla a tu nicho antes de subir.", "silver": false}, {"id": "g3-025", "modulo": "M4", "clase": "Calentamiento de cuenta", "pregunta": "¿Me conviene comprar una cuenta vieja de YouTube?", "variantes": ["¿compro una cuenta antigua?", "¿dónde compro cuentas aged?", "¿sirve comprar un canal viejo?", "¿comprar cuenta en vez de calentar?"], "respuesta": "Es posible, pero no lo recomendamos. Al comprar una cuenta podés heredar un mal historial: infracciones, mala reputación o incluso que te la reclamen cuando ya armaste el canal. Si alguien igual decide hacerlo, en la clase se menciona agedfiles.com como una de las pocas opciones serias. Lo más sano es usar una cuenta tuya y calentarla bien. Esto lo ves en la clase «Calentamiento de cuenta».", "silver": false}, {"id": "g3-026", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Qué es el video de prueba que se sube antes de los primeros videos?", "variantes": ["¿qué es el video meter?", "¿tengo que subir un video de testeo?", "¿qué video subo primero?", "video tester, ¿qué es?"], "respuesta": "Es un video cualquiera filmado con tu teléfono, de 2 a 4 minutos: un paseo, la plaza, los autos pasando. No hace falta que salgas en cámara, pero no puede estar hecho con IA. Sirve para ver si la cuenta recibe impresiones y para mostrarle a YouTube que sos humano. Hoy es opcional; se recomienda más a quien ya maneja varios canales.", "silver": false}, {"id": "g3-027", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Cuánto espero después del video de prueba y cuántas impresiones tendría que tener?", "variantes": ["¿cuántas impresiones es normal en el video de prueba?", "subí el video de prueba, ¿y ahora?", "¿cuánto tiempo espero para subir los demás?", "¿cómo sé si mi cuenta está sana?"], "respuesta": "Esperá 24 a 48 horas y mirá las impresiones, no las vistas. Según Max, una cuenta sana suele dar más de 100-200 impresiones en nicho en inglés y más de 50-100 en español. Si se mueve, buena señal. Si no llega, igual podés empezar a publicar; ese dato te sirve más adelante para saber si el problema es la cuenta y no tu contenido.", "silver": false}, {"id": "g3-028", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "Mi video de prueba casi no tuvo impresiones, ¿cambio de nicho?", "variantes": ["el video de prueba tiene 0 impresiones", "¿abro otra cuenta?", "¿busco otro nicho si no hay impresiones?", "mi cuenta no tiene impresiones"], "respuesta": "No cambies todo. Si la cuenta no responde, en todo caso cambiás la cuenta, no el nicho: te quedás con el mismo tema y probás otra cuenta. Antes de decidir, dale un día más, porque las impresiones varían. Y si querés, publicá igual y aguantá 10-15 videos mientras calentás otra cuenta de reserva.", "silver": false}, {"id": "g3-029", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Qué es el video reel humanizado y cuándo lo subo?", "variantes": ["¿qué es el video de presentación del canal?", "¿tengo que aparecer en un video?", "¿cuándo subo el trailer?", "video con persona real, ¿para qué?"], "respuesta": "Es un video donde aparece un humano (vos, un actor o un familiar) contando de qué va el canal. Se sube entre el video 10 y el 15, no afecta la temática y potencia el canal: le da seguridad a YouTube de que no sos un bot. Lau suma que para él es fundamental que haya sí o sí una persona real. Lo aconsejamos al 100%.", "silver": false}, {"id": "g3-030", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Cómo dejo fijo el video de presentación en mi canal?", "variantes": ["¿cómo pongo el trailer del canal?", "¿dónde fijo el video reel?", "¿lo subo público o no listado?", "avance del canal, ¿cómo se pone?"], "respuesta": "Grabá un video de 1 a 2 minutos explicando qué hacés en tu canal y subilo como no listado (en privado no te deja usarlo como sección). Después andá a Personalizar canal, Pestaña principal, activá el deslizador, tocá Agregar sección y elegí Avances del canal. Seleccioná tu video y guardá. Así queda fijo para todos los visitantes.", "silver": false}, {"id": "g3-031", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Qué es la estrategia de subida 3-2-1?", "variantes": ["¿qué significa 3-2-1?", "¿cómo es el 3 2 1?", "¿cuántos videos subo al principio?", "explicame la subida 3-2-1"], "respuesta": "Es la forma de lanzar el canal: el día 1 subís tres videos, el día 2 dos y el día 3 uno. Desde el día 4 seguís con la frecuencia promedio de tu nicho o de tu canal de referencia. La idea es darle al algoritmo la mayor cantidad de datos en el menor tiempo para que entienda de qué va tu canal. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-032", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿A qué hora subo cada video del 3-2-1?", "variantes": ["¿en qué horarios publico?", "¿a qué hora va cada video?", "horarios del primer día", "¿cuál es el horario prime?"], "respuesta": "Día 1: un video a la mañana, otro al mediodía y otro en el prime, a las 18-19 h. Día 2: uno a la mañana y otro en el prime. Día 3: uno a las 18-19 h. Si podés, dejalos programados con varias horas de anticipación, al menos unas 5. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-033", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Las 18-19 h son de mi país o del país de mi audiencia?", "variantes": ["¿uso mi hora local?", "¿hora de argentina o de estados unidos?", "¿qué zona horaria uso para publicar?", "mi audiencia está en otro país, ¿a qué hora subo?"], "respuesta": "Del país de tu audiencia objetivo, no el tuyo. Si estás en Argentina y tu canal apunta a Estados Unidos, subís a las 18-19 h de allá. Al principio no te pongas a estudiar horas pico al detalle: todavía no tenés audiencia ni datos propios. Primero publicá. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-034", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Por qué hay que subir tantos videos juntos al principio?", "variantes": ["¿para qué sirve el 3-2-1?", "¿no es mejor subir de a uno?", "¿por qué no subo un video y espero?", "¿qué gana el algoritmo con eso?"], "respuesta": "Por dos razones. Si alguien llega a tu canal y encuentra un solo video, la sesión se corta ahí; con varios, puede seguir mirando. Y un canal nuevo no tiene datos: cada video le da a YouTube información de tu tema para saber a quién mostrárselo. Además, si las impresiones son pocas, sabés que es algo técnico y no falta de contenido. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-035", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Qué hago después del día 3?", "variantes": ["¿y después del 3-2-1?", "¿cuántos videos por semana subo después?", "¿sigo subiendo todos los días?", "frecuencia después del lanzamiento"], "respuesta": "Desde el día 4 seguís la frecuencia promedio de tu nicho o de tu canal de referencia, para igualarla o mejorarla. Lau sugiere, si podés, seguir sumando videos el resto de la primera semana y desde la segunda fijar la cadencia real que puedas sostener según tu presupuesto, esfuerzo y vida diaria. Siempre priorizá calidad. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-036", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "Mi canal de referencia sube un video por semana, ¿igual hago el 3-2-1?", "variantes": ["¿3-2-1 aunque la competencia suba poco?", "¿copio la frecuencia de mi referencia?", "mi nicho sube 1 por semana", "¿hago 3-2-1 por semana?"], "respuesta": "Sí, el arranque 3-2-1 se hace igual, porque sirve para darle al algoritmo inventario y datos desde el inicio. Después te adaptás a tu nicho: si allí se sube un video por semana, podés llevar ese ritmo. Max recomienda que la frecuencia sea pareja y, si podés, un poco por encima de tus competidores. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-037", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "Mis videos me llevan días de trabajo, ¿también hago el 3-2-1?", "variantes": ["tardo 2 o 3 días por video", "mis videos son muy elaborados", "nicho de dificultad media, ¿cómo subo?", "no llego a hacer 6 videos"], "respuesta": "Depende de la dificultad del nicho. El 3-2-1 completo es para nichos de baja dificultad, videos que se editan en 1-2 horas. Si tus videos llevan 1 a 3 días (dificultad media), subí un video por día los tres primeros días a las 18-19 h y después seguí la frecuencia del nicho o el ritmo real que puedas mantener. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-038", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "Mis videos son muy caros de producir, ¿cómo lanzo el canal?", "variantes": ["nicho de alta dificultad", "mis videos cuestan mucho", "¿cómo valido antes de gastar?", "videos con personajes y mucha IA, ¿cómo arranco?"], "respuesta": "En nichos de alta dificultad (videos caros, personajes consistentes, mucha IA) primero validá la idea con shorts, TikTok o Instagram, y recién después producís videos largos. Así no gastás de más en algo sin validar. Una vez en marcha, en esos nichos se puede subir cada 15 días o incluso una vez por mes. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-039", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "No voy a poder subir tan seguido como la competencia, ¿qué hago?", "variantes": ["no llego con la frecuencia", "¿qué pasa si subo menos?", "no puedo publicar todos los días", "¿cómo compenso si subo poco?"], "respuesta": "Ajustá tus publicaciones a tu ritmo natural, sin forzarte: lanzá tu 3-2-1 y después seguí con la cadencia real que puedas mantener. Max sugiere compensar haciendo videos con más minutos que la competencia: no igualás en frecuencia, pero le das más datos a YouTube. Lo importante es que la frecuencia sea pareja.", "silver": false, "video": {"id": "m1AJcNSuFKw", "titulo": "Deja de hacer esto si quieres crecer en Yotube (el tip 3 es el mejor)", "url": "https://www.youtube.com/watch?v=m1AJcNSuFKw"}}, {"id": "g3-040", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Cuánto tiempo puedo tardar entre elegir el nicho y subir el primer video?", "variantes": ["¿espero a tener todo perfecto?", "¿cuándo lanzo el canal?", "¿conviene esperar un buen momento?", "¿lanzo durante un evento grande?"], "respuesta": "Lo menos posible. Si ves una oportunidad, andá directo: es preferible errar un canal que llegar tarde, salvo que el nicho todavía no te convenza. Como dice Lau, el mejor momento para lanzar es ayer. Eso sí, sin saltear el calentamiento. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-041", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "Uno de mis primeros videos explotó, ¿qué hago?", "variantes": ["tengo un outlier en los primeros videos", "un video tuvo muchas vistas", "¿subo más videos si uno funciona?", "primer video viral, ¿y ahora?"], "respuesta": "Si aparece un outlier, aprovechá la demanda y subí lo más posible: el algoritmo te está diciendo que hay interés. Al terminar la semana definí la cadencia real que puedas sostener. Y tranqui si los siguientes videos no llegan a ese número: así funciona YouTube. Esto lo ves en la clase «Estrategia de subida 3-2-1».", "silver": false}, {"id": "g3-042", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Conviene subir Shorts junto con los videos largos al empezar?", "variantes": ["¿hago shorts para crecer?", "¿mezclo shorts y videos largos?", "¿subo shorts si tengo pocas vistas?", "¿monetizo solo con shorts?"], "respuesta": "Por ahora no recomendamos combinar Shorts con videos largos: quien mira Shorts está en modo consumo rápido, no en modo ver 10 minutos. Monetizar solo con shorts se puede, pero Max no lo recomienda: es más efímero y exige muchos videos por día. La excepción es validar una idea cara en shorts antes de producir largos.", "silver": false, "video": {"id": "J9Ap9qyUr5I", "titulo": "¿Los YouTube Shorts están MATANDO tu canal Faceless?", "url": "https://www.youtube.com/watch?v=J9Ap9qyUr5I"}}, {"id": "g3-043", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "Mis primeros videos tienen cero vistas, ¿es normal?", "variantes": ["no tengo vistas", "nadie mira mis videos", "subí videos y nada", "¿es normal tener 0 vistas al principio?", "Mis primeros videos tienen casi cero vistas, ¿es normal?", "lancé y nadie me ve", "hay días sin vistas", "mis videos no tienen visitas", "tengo cero suscriptores"], "respuesta": "Sí, es completamente normal. Un canal nuevo arranca en frío: YouTube todavía no sabe a quién mostrarte ni tiene con qué comparar tus videos. Cero suscriptores y pocas vistas al principio no es un mal resultado, es que todavía no hay resultado. Ahora mirá impresiones y retención, no vistas, y tené paciencia. Esto lo ves en la clase «Mis primeros videos».", "silver": false}, {"id": "g3-044", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Cómo decide YouTube a quién mostrarle mi video?", "variantes": ["¿cómo funciona el algoritmo con un canal nuevo?", "¿youtube me castiga?", "¿por qué a veces muestra y a veces no?", "¿cómo se reparte un video?"], "respuesta": "YouTube no castiga. Primero entiende el tema por el título, la descripción, la transcripción, los capítulos y el canal. Después muestra el video a un grupo chico y mide si hacen clic, cuánto lo ven, si siguen mirando y si interactúan. Según eso, lo expande a audiencias más grandes o lo frena. Esto lo ves en la clase «Mis primeros videos».", "silver": false, "video": {"id": "Rgp334qvaqw", "titulo": "Entender YouTube Faceless como Negocio: Conoce el Algoritmo", "url": "https://www.youtube.com/watch?v=Rgp334qvaqw"}}, {"id": "g3-045", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Qué métrica miro primero en mis videos nuevos?", "variantes": ["¿miro vistas o impresiones?", "¿qué es lo importante al principio?", "¿en qué me fijo en youtube studio?", "¿qué son las impresiones?"], "respuesta": "Al principio, las impresiones: cuántas veces YouTube mostró tu video. Tienen que subir como un serrucho, con pisos cada vez más altos. La retención también se puede medir desde el inicio. Las vistas y los suscriptores son métricas de vanidad en esta etapa. Esto lo ves en la clase «Mis primeros videos».", "silver": false, "video": {"id": "wb4-5xT-da0", "titulo": "Mi Video de YOUTUBE Hizo 6x en 24 horas: ¿Suerte o Estrategia? (7 Señales)", "url": "https://www.youtube.com/watch?v=wb4-5xT-da0"}}, {"id": "g3-046", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Cuántos videos tengo que subir antes de sacar conclusiones?", "variantes": ["¿cuándo sé si el canal funciona?", "¿cuándo abandono el canal?", "llevo pocos videos y no pasa nada", "¿cuántos videos le doy al canal?"], "respuesta": "En la formación no sacamos conclusiones firmes hasta el video 30. En ese tramo vigilá las impresiones: si después de 30-40 videos no pasás de 200 impresiones o es una línea plana, algo anda mal. Si ya a los 15-20 videos no hay impresiones, puede ser el calentamiento o la confianza de la cuenta. Esto lo ves en la clase «Mis primeros videos».", "silver": false, "video": {"id": "wPkGiD3STWw", "titulo": "NO Comiences en YT FACELESS SIN VER ESTO PRIMERO!", "url": "https://www.youtube.com/watch?v=wPkGiD3STWw"}}, {"id": "g3-047", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "Llevo varios videos sin impresiones, ¿qué hago?", "variantes": ["mis videos no tienen impresiones", "¿cambio de cuenta?", "canal congelado, ¿qué hago?", "¿borro todo y empiezo de nuevo?"], "respuesta": "Primero asegurate de haber hecho el 3-2-1 y un calentamiento real. Dale hasta unos 15 videos. Si ahí sigue sin reaccionar, probablemente sea la cuenta: abrí otra, calentala y migrá el canal con el mismo nicho. Mejor si usás una cuenta ya creada hace tiempo en vez de una recién hecha.", "silver": false}, {"id": "g3-048", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Qué es el CTR y cuánto tendría que tener?", "variantes": ["¿qué es el ctr?", "mi ctr es bajo", "¿cuál es un buen ctr?", "¿por qué baja mi ctr?"], "respuesta": "El CTR es el porcentaje de personas que hacen clic cuando ven tu video. Depende de las impresiones, así que al principio no es fiable, y es normal que baje cuando el video llega a público nuevo. Por debajo de 2-3% ya es alarmante y conviene cambiar la miniatura o el título. Esto lo ves en la clase «Mis primeros videos».", "silver": false, "video": {"id": "oAI1OdUMJM8", "titulo": "La Prueba A/B de YOUTUBE Está DESTROZANDO Tu Canal (haz esto!)", "url": "https://www.youtube.com/watch?v=oAI1OdUMJM8"}}, {"id": "g3-049", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Qué retención necesita un video para estar bien?", "variantes": ["¿qué es buena retención?", "la gente se va enseguida de mis videos", "¿cuánto tienen que mirar?", "mi retención es baja"], "respuesta": "Según Max, en los primeros 30 segundos no debería bajar de 50-60%, lo ideal es 80%, y al final tendría que llegar al menos un 30%. A diferencia del CTR, la retención se puede medir desde el inicio. Si es baja, el problema suele estar en el guion. Esto lo ves en la clase «Mis primeros videos».", "silver": false}, {"id": "g3-050", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Cómo sé qué tengo que mejorar en mis videos?", "variantes": ["¿qué cambio si no funciona?", "¿el problema es la miniatura o el guion?", "matriz ctr retención", "¿cómo diagnostico mis videos?"], "respuesta": "Usá la matriz de la clase. Buen video con mal empaque: cambiá título y miniatura. CTR y retención bajos: revisá el tema y las palabras clave. CTR alto y buena retención: iterá esa fórmula. CTR alto y retención baja: arreglá el guion. Cambiá una sola cosa por vez. Esto lo ves en la clase «Mis primeros videos».", "silver": false}, {"id": "g3-051", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Cada cuánto reviso YouTube Studio?", "variantes": ["¿miro las estadísticas todo el día?", "¿cuándo evalúo un video?", "me la paso mirando studio", "¿cuándo reviso los números?"], "respuesta": "No mires Studio a cada rato, porque solo te genera ansiedad. Evaluá un video entre el día 1 y el 7, después a los 28 días y a los 90. Cambiá una sola cosa por vez y dale 5 o 6 videos antes de sacar conclusiones. Mejorar un 1% por día, al estilo Kaizen. Esto lo ves en la clase «Mis primeros videos».", "silver": false, "video": {"id": "m1AJcNSuFKw", "titulo": "Deja de hacer esto si quieres crecer en Yotube (el tip 3 es el mejor)", "url": "https://www.youtube.com/watch?v=m1AJcNSuFKw"}}, {"id": "g3-052", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Cuándo cambio la miniatura o el título de un video?", "variantes": ["¿cambio la miniatura si no tiene clics?", "¿cuánto espero para cambiar la miniatura?", "¿toco títulos de videos viejos?", "¿miniatura o título, qué cambio?"], "respuesta": "Si el CTR está bajo, cambiala rápido, como mucho en unos 5 días, porque si no es un outlier el video se apaga pronto. Cambiar la miniatura mucho después no sirve si casi nadie lo está viendo. Ojo: el CTR depende de las dos cosas; si cambiás la miniatura y no hay diferencia, probablemente sea el título. Esto lo ves en la clase «Mis primeros videos».", "silver": false, "video": {"id": "oAI1OdUMJM8", "titulo": "La Prueba A/B de YOUTUBE Está DESTROZANDO Tu Canal (haz esto!)", "url": "https://www.youtube.com/watch?v=oAI1OdUMJM8"}}, {"id": "g3-053", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Cómo pongo los capítulos y los títulos de mis videos?", "variantes": ["¿hacen falta capítulos?", "¿cuántos capítulos pongo?", "¿cómo escribo el título?", "¿qué título le pongo al video?"], "respuesta": "Usá capítulos: al menos 8 partes, con títulos en forma de pregunta o de afirmación. Y escribí títulos con la intención de búsqueda, tal como lo buscaría alguien, por ejemplo «cómo hacer un nudo de corbata». Así YouTube entiende mejor el tema. La demanda la podés validar con vidIQ y NexLev. Esto lo ves en la clase «Mis primeros videos».", "silver": false}, {"id": "g3-054", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿De dónde tienen que venir las vistas de un canal nuevo?", "variantes": ["¿qué fuente de tráfico es buena?", "casi todo viene de búsqueda, ¿está mal?", "¿cómo veo de dónde vienen mis vistas?", "¿qué es tráfico de sugeridos?"], "respuesta": "Al principio es normal que mucho venga de búsqueda; eso debería ir bajando y la idea es que después la mayoría llegue por el feed de exploración y sugeridos. Lo ves en Studio, Analíticas, Contenido, cómo encuentran tus videos. Si cerca del video 15 todo sigue viniendo solo de búsqueda, YouTube no te está recomendando y hay que revisar.", "silver": false}, {"id": "g3-055", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "No tengo suscriptores todavía, ¿hago algo mal?", "variantes": ["¿cómo consigo los primeros suscriptores?", "0 suscriptores", "¿por qué nadie se suscribe?", "¿cuándo llegan los suscriptores?"], "respuesta": "No te preocupes por los suscriptores al principio. Llegan solos: al principio nada, y después un suscriptor llama al otro. A medida que la gente ve más videos en tu canal, se va suscribiendo más. Ahora concentrate en impresiones y retención.", "silver": false, "video": {"id": "QDDwMMO6mx8", "titulo": "El cambio más grande en YouTube en años (Ahora o Nunca amigo!)", "url": "https://www.youtube.com/watch?v=QDDwMMO6mx8"}}, {"id": "g3-056", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Pido que se suscriban en mis primeros videos o espero?", "variantes": ["¿pongo llamados a la acción desde el inicio?", "¿digo suscribite en el video?", "¿alcanza con el botón automático?", "¿cuándo empiezo con los cta?"], "respuesta": "Desde el video uno. Si YouTube decide empujar uno de tus primeros videos y no pedís la suscripción, desperdiciás esa oportunidad. El botón automático y las pantallas finales son pasivos y la gente deja de verlos. Pedilo con tu voz o en pantalla, pero conectado con lo que estás contando, no el clásico «dale like» suelto.", "silver": false}, {"id": "g3-057", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "Uso IA para la voz o las imágenes, ¿lo tengo que declarar?", "variantes": ["¿marco contenido sintético?", "¿dónde aviso que usé ia?", "¿pongo en la descripción que es ia?", "¿declarar ia me baja las vistas?"], "respuesta": "Sí. Siempre que uses IA, aunque sea solo la voz, marcá la casilla de «contenido alterado o sintético» al subir el video. Ponerlo en la descripción no cuenta para YouTube: lo que vale es esa casilla. Y tranqui, que según Max no afecta la distribución de tu canal.", "silver": false, "video": {"id": "uIF68kQmaMg", "titulo": "SynthID: YouTube Automatizado te está marcando (y no lo sabes)", "url": "https://www.youtube.com/watch?v=uIF68kQmaMg"}}, {"id": "g3-058", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Qué cuidados tengo al subir videos hechos con IA?", "variantes": ["¿algo especial al subir videos con ia?", "¿cómo evito que youtube piense que soy un bot?", "consejos para videos con ia", "¿puedo pegar el guion de la ia tal cual?"], "respuesta": "Al subir, marcá que no es para niños (salvo que lo sea) y que tiene contenido hecho con IA. Guardá todo el material en una carpeta, sirve si te rechazan la monetización. No edites con apps de IA: la edición muestra que sos humano. Retocá los guiones con tu opinión y evitá voces robóticas.", "silver": false, "video": {"id": "uIF68kQmaMg", "titulo": "SynthID: YouTube Automatizado te está marcando (y no lo sabes)", "url": "https://www.youtube.com/watch?v=uIF68kQmaMg"}}, {"id": "g3-059", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Comparto mis videos en redes o grupos para que tengan más vistas?", "variantes": ["¿paso el link en grupos de facebook?", "¿pido feedback en foros?", "¿promociono el canal en redes?", "¿pago publicidad para el canal?"], "respuesta": "Al principio no. Con los primeros videos YouTube está aprendiendo quién es tu audiencia, y el tráfico forzado de grupos le ensucia los datos. Max empieza a llevar tráfico externo recién pasados unos 60 videos. Y nada de pagar promociones o «tráfico»: eso puede destruir las señales del canal.", "silver": false, "video": {"id": "vR6HZv7hHWM", "titulo": "7 ERRORES Letales que cometes en YOUTUBE FACELESS", "url": "https://www.youtube.com/watch?v=vR6HZv7hHWM"}}, {"id": "g3-060", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "Tengo pocos videos y estoy por abandonar, ¿sigo?", "variantes": ["quiero dejar el canal", "no veo resultados y me desanimo", "¿vale la pena seguir?", "me siento estancado con el canal"], "respuesta": "Respirá. Con pocos videos todavía no hay nada que decidir porque no hay información. Publicar ya es lo que la mayoría no hace. El primer canal es para aprender, no para triunfar: es el tutorial. Mirá impresiones y retención, cambiá una cosa por vez y date la oportunidad de llegar al video 30 antes de juzgar.", "silver": false, "video": {"id": "vR6HZv7hHWM", "titulo": "7 ERRORES Letales que cometes en YOUTUBE FACELESS", "url": "https://www.youtube.com/watch?v=vR6HZv7hHWM"}}, {"id": "g3-061", "modulo": "M4", "clase": "Abrir un canal", "pregunta": "¿Necesito Multilogin o proxies para abrir mi canal?", "variantes": ["¿qué es multilogin?", "¿uso proxies?", "¿cómo lanzo varios canales a la vez?", "¿tengo que instalar multilogin?"], "respuesta": "Para tu primer canal no hace falta. Max lo considera de alto riesgo a futuro, porque va contra las normas de YouTube, y se usa solo como último recurso en casos puntuales. Lanzar varios canales a la vez parece conducta de granja de contenido: lo sano es un canal a la vez, cada uno con su cuenta. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g3-062", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "YouTube me limitó un video por música con copyright, ¿qué hago?", "variantes": ["me reclamaron derechos de autor", "problema de copyright con la música", "¿qué música puedo usar?", "¿borro el video con reclamo?"], "respuesta": "Si lo volviste a subir sin esa música, no borres el original: pasalo a no listado desde YouTube Studio, Contenido, el lápiz del video, Visibilidad. Así no aparece en búsquedas ni en tu canal. Qué música y efectos usar sin problemas lo vemos a fondo en Silver.", "silver": true}, {"id": "g3-063", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Conviene hacer transmisiones en vivo para crecer?", "variantes": ["¿hago vivos en el canal?", "¿los directos ayudan?", "¿transmito en vivo?", "¿sirven los lives para faceless?", "¿Conviene hacer transmisiones en vivo?", "¿hago directos?", "¿los vivos ayudan a crecer?", "¿transmito en vivo en mi canal?", "¿sirven los streams?"], "respuesta": "Depende del tipo de canal. Según cuenta Max, le fue mal con vivos en canales atemporales y muy bien en canales de tendencia, porque al estar en vivo el algoritmo te da prioridad. Ojo con transmitir material ajeno, que puede traer reclamos. Para tus primeros videos no hace falta. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g3-064", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Cómo sé si mi nicho tiene suficiente competencia y demanda?", "variantes": ["¿cuántos canales necesito para validar?", "¿cómo valido mi nicho?", "no hay competencia en español, ¿sirve?", "¿mi nicho está saturado?"], "respuesta": "Lo básico: que haya demanda actual, varios canales funcionando en tu idioma, y no copiar a tu referencia sino darle un giro propio. Si no hay nadie en español, es un canal pionero: puede ir muy bien o muy mal. La validación de competencia la vemos a fondo en Silver.", "silver": true, "video": {"id": "r1Z_IMul9ks", "titulo": "3 NICHOS FÁCILES de Youtube Faceless que explotan en 2026", "url": "https://www.youtube.com/watch?v=r1Z_IMul9ks"}}, {"id": "g3-065", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "No me llega el PIN de AdSense, ¿qué hago?", "variantes": ["¿cómo verifico adsense?", "el pin de adsense no llega", "¿cómo cobro de youtube?", "¿qué pasa con adsense?", "¿Qué es el PIN de AdSense y qué hago si no llega?", "no me llega el pin", "¿cómo valido adsense?", "¿el pin llega por correo?", "pedí el pin varias veces"], "respuesta": "El PIN llega por carta y puede tardar semanas; si no llega, se puede pedir reenvío y existe un solucionador de problemas de PIN de AdSense. Igual eso aparece recién cuando monetizás: ahora enfocate en tus primeros videos. Todo lo de AdSense lo vemos a fondo en Silver.", "silver": true}, {"id": "g3-066", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Puedo hacer un canal de música hecha con IA?", "variantes": ["canal de música con ia", "¿monetiza la música ia?", "¿se puede hacer un canal solo de música?", "nicho de música relajante con ia"], "respuesta": "Max lo desaconseja: hoy está casi imposible monetizar música hecha con IA, y si los videos no tienen guion y son solo música, él directamente lo desestimaría. Antes de elegir, fijate si existen canales exitosos parecidos que demuestren que hay una audiencia. Qué nichos conviene evitar lo vemos a fondo en Silver.", "silver": true, "video": {"id": "R38vZH6BCsA", "titulo": "NO crees estos canales en YOUTUBE FACELESS", "url": "https://www.youtube.com/watch?v=R38vZH6BCsA"}}, {"id": "g3-068", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "Tengo un outlier, ¿cómo hago más videos parecidos sin canibalizarlo?", "variantes": ["¿cómo itero un outlier?", "¿repito la fórmula del video que funcionó?", "¿subo videos parecidos al que pegó?", "canibalizar videos"], "respuesta": "Exprimir un formato que funcionó es correcto, porque muestra que hay demanda. Pero no es fórmula mágica: el éxito mezcla idea, guion, CTR e interacción. Si es tendencia, subí rápido. Cómo iterar sin canibalizarte lo vemos a fondo en Silver.", "silver": true}, {"id": "g3-069", "modulo": "M8", "clase": "Mis primeros videos", "pregunta": "¿Alguien me puede revisar el canal y decirme qué estoy haciendo mal?", "variantes": ["¿me analizan el canal?", "¿quién me da feedback?", "¿pueden ver mis videos?", "quiero una revisión personalizada"], "respuesta": "Para diagnosticar hacen falta datos: cuántos videos subiste, cómo vienen las impresiones, CTR, retención y si le diste un giro propio al nicho. Con eso podés usar la matriz de la clase «Mis primeros videos». La revisión personalizada con el equipo es parte de Silver.", "silver": true}, {"id": "g3-070", "modulo": "M8", "clase": "Estrategia de subida 3-2-1", "pregunta": "¿Hay un bot o asistente que me responda dudas del método al instante?", "variantes": ["¿hay un bot de sen6?", "¿quién responde mis dudas rápido?", "asistente con ia de sen6", "¿puedo preguntarle a una ia del curso?"], "respuesta": "En Island Lite estoy yo para responderte las dudas de estas clases: abrir el canal, calentar la cuenta, la subida 3-2-1 y tus primeros videos. Los agentes entrenados con toda la data del método, que resuelven al instante preguntas más amplias, están en el módulo de bots. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g4-001", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Qué es el guion maestro?", "variantes": ["qué es el guion master", "para qué sirve el guion maestro", "qué significa guion master", "cómo funciona lo del guion maestro"], "respuesta": "Es un archivo con la estructura y los patrones que se repiten en los guiones más exitosos de tu canal de referencia. No es un guion para copiar: es el esqueleto que le das a la IA para que escriba tus guiones nuevos respetando lo que ya demostró que funciona. Lo guardás como documento (o .md) y lo subís a un proyecto en Claude. Esto lo ves en la clase «Guión Master».", "silver": false, "video": {"id": "yIL5m3iBT2U", "titulo": "5 minutos con Claude AI: investigación de nicho y script para tu canal de Youtube Faceless", "url": "https://www.youtube.com/watch?v=yIL5m3iBT2U"}}, {"id": "g4-002", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Puedo copiar el guion de un video que funciona?", "variantes": ["puedo copiar el guion del canal de referencia", "usar canales de referencia es copiar", "youtube castiga si copio", "puedo traducir un guion exitoso"], "respuesta": "No. En SEN6 no copiamos: validamos que haya audiencia y tomamos la estructura ganadora, no los elementos. Después cambiás todo el contenido y, sobre todo, el ángulo, que es lo que te convierte en un canal único y no en uno igual a los demás. Clonar un canal no funciona, ni para YouTube ni para la audiencia. Esto lo ves en la clase «Guión Master».", "silver": false, "video": {"id": "yIL5m3iBT2U", "titulo": "5 minutos con Claude AI: investigación de nicho y script para tu canal de Youtube Faceless", "url": "https://www.youtube.com/watch?v=yIL5m3iBT2U"}}, {"id": "g4-003", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Cuántos guiones tengo que analizar para armar el guion maestro?", "variantes": ["cuántos videos analizo", "qué videos elijo del canal de referencia", "cuántos guiones necesito", "de dónde saco los guiones para analizar"], "respuesta": "Andá al canal de referencia, pestaña Videos, y ordenalos por Más populares. Tomá los 8 primeros; si el canal tiene menos, usá los que tenga, y como mínimo apuntá a 5. Son los videos que ya probaron que la audiencia los quiere, así que su estructura es la que te conviene estudiar. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-004", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Cómo saco la transcripción de un video de YouTube?", "variantes": ["cómo copio el texto de un video", "cómo extraigo el guion de un video ajeno", "herramienta para transcribir videos de youtube", "dónde está la transcripción en youtube"], "respuesta": "La forma más simple y gratis es el botón de transcripción del propio YouTube, debajo del video. Antes de copiar, desactivá las marcas de tiempo desde los tres puntos del cuadro de la transcripción (en algunos videos se puede y en otros no), y pegás el texto en un doc o un txt. También podés usar el botón de NexLev en YouTube o TurboScribe. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-005", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Qué le pido a la IA para que saque la estructura de los guiones?", "variantes": ["qué prompt uso para el guion maestro", "cómo le pido a chatgpt que analice los guiones", "qué escribo para sacar la estructura", "prompt para analizar guiones"], "respuesta": "Pegás las transcripciones y le pedís algo como: «Detecta la estructura exitosa de estos guiones; si son diferentes, dame las mejores prácticas y patrones». Te va a devolver el esqueleto, por ejemplo: del minuto 0 al 1 el gancho, del 1 al 3 el planteo del problema, y así. No es un prompt mágico fijo: son dos pasos, primero analizar la estructura y después generar guiones nuevos con ella. Esto lo ves en la clase «Guión Master».", "silver": false, "video": {"id": "yIL5m3iBT2U", "titulo": "5 minutos con Claude AI: investigación de nicho y script para tu canal de Youtube Faceless", "url": "https://www.youtube.com/watch?v=yIL5m3iBT2U"}}, {"id": "g4-006", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Qué hago si los guiones del canal de referencia tienen estructuras distintas?", "variantes": ["los videos no siguen la misma estructura", "cada guion es diferente qué hago", "no encuentro una estructura común", "las estructuras varían mucho"], "respuesta": "Pasa seguido. En ese caso no buscás una estructura única sino los patrones comunes: por ejemplo, si todos generan curiosidad al inicio, si narran en primera persona, qué tipo de llamado a la acción usan. Por eso al pedírselo a la IA le agregás: «si son diferentes, dame las mejores prácticas y patrones». Ese resultado también es tu guion maestro. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-007", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Cómo armo el guion maestro con Claude Code y NexLev?", "variantes": ["forma recomendada del guion maestro", "cómo uso nexlev para estudiar guiones", "qué le digo a claude code para el guion master", "guion maestro automático"], "respuesta": "Es la forma recomendada. En Claude Code escribís: «Usa NexLev para estudiar las estructuras exitosas de los mejores 8 guiones del canal» y pegás la URL del canal de referencia. Cuando termina, le pedís: «compila esta info en un archivo .md». Ese archivo es tu guion maestro, y armarlo así equivale a crear una skill. Si preferís, la forma manual con transcripciones también sirve. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-008", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Cómo armo el proyecto en Claude para que me escriba los guiones?", "variantes": ["qué instrucciones pongo en el proyecto de claude", "dónde subo el guion maestro", "el guion me sale con títulos y tiempos", "proyecto de claude para guiones"], "respuesta": "Creás un proyecto en Claude, subís el archivo del guion maestro y en las instrucciones ponés algo como: «Haz guiones de X palabras siempre respetando la estructura de los documentos de archivo». Pedile también que te los entregue sin marcas de tiempo ni títulos, solo en párrafos. Después le vas pidiendo guiones por tema. Esto lo ves en la clase «Guión Master».", "silver": false, "video": {"id": "MNNy0TB1v9g", "titulo": "Gané $1,000 por Video con Guiones Automáticos de YouTube (Así lo Hago)", "url": "https://www.youtube.com/watch?v=MNNy0TB1v9g"}}, {"id": "g4-009", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Cuántas palabras tiene que tener un guion de 10 minutos?", "variantes": ["cuántas palabras para un video de 10 minutos", "largo del guion", "cuántas palabras por minuto", "qué tan largo hago el guion"], "respuesta": "Como referencia, 10 minutos son más o menos entre 1.250 y 1.500 palabras. Depende mucho de la voz: por ejemplo, una narración en inglés americano con ElevenLabs corre alrededor de 150 a 160 palabras por minuto. Por eso conviene probar con tu voz y ajustar la cantidad de palabras en las instrucciones del proyecto. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-011", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Puedo hacer todo el guion con IA?", "variantes": ["la ia puede escribir todo el guion", "youtube desmonetiza los guiones hechos con ia", "qué parte del guion tiene que ser mía", "el canal es en un idioma que no domino"], "respuesta": "La IA sirve muchísimo para el análisis de estructura y patrones, pero todo el guion tiene que tener tu perspectiva y aportar valor. La parte de editorial personal escribila vos, sin vocabulario de IA, y guardá esos párrafos en un Word que subís al proyecto para que imite tu forma de escribir; solo si el canal es en un idioma que no dominás, dejá que la IA la escriba. YouTube necesita ver intervención humana; sin eso, lo toma como contenido de bajo valor. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-012", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Cómo evito que mi guion suene a IA?", "variantes": ["mi guion suena robótico", "cómo hago que no parezca escrito por chatgpt", "frases típicas de ia", "cómo le doy mi estilo al guion"], "respuesta": "El tono, la voz, los modismos y la marca tienen que ser tuyos; eso es lo que separa un canal de verdad de uno automatizado sin valor. Ojo con los clichés de redacción de IA, del tipo «esto me sorprende porque». Escribí vos la editorial personal y subí al proyecto un Word con párrafos tuyos para que la IA imite cómo escribís.", "silver": false, "video": {"id": "6-YFJhREYcA", "titulo": "¿Por qué tus vídeos de Youtube no funcionan? (No es el algoritmo)", "url": "https://www.youtube.com/watch?v=6-YFJhREYcA"}}, {"id": "g4-013", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Para qué guardo los guiones que hago?", "variantes": ["tengo que guardar los guiones", "sirve guardar el proyecto de claude", "para qué sirven los guiones viejos", "qué muestro si me rechazan la monetización"], "respuesta": "Guardar los guiones del proyecto te sirve como prueba si YouTube te rechaza la monetización y tenés que apelar: muestran que hay un proceso con intervención humana detrás de cada video. Por eso los guiones son fundamentales aunque te ayudes con IA. Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-014", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Uso Claude o ChatGPT para escribir los guiones?", "variantes": ["cuál ia es mejor para guiones", "chatgpt sirve para guiones", "qué es poner human en el prompt", "deepseek sirve para guiones"], "respuesta": "Para generar el guion, Máximo recomienda Claude por su calidad creativa. El análisis de estructura lo podés hacer con Claude o con GPT. Para corregir, DeepSeek es una buena alternativa gratuita. En Claude, arrancá el pedido con «human:» y adjuntá el guion maestro, por ejemplo: «human: crea un guion sobre [tema], con tono [misterioso, educativo…], siguiendo la estructura del archivo adjunto». Esto lo ves en la clase «Guión Master».", "silver": false}, {"id": "g4-015", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Puedo cambiar de tono o de ángulo entre un video y otro?", "variantes": ["puedo hacer un video serio y otro de humor", "mezclar estilos en el mismo canal", "probar distintos ángulos en el canal", "cambiar el tono de los guiones"], "respuesta": "Cambiar el tono o el ángulo drásticamente en un mismo canal te tira para atrás, sobre todo si recién arrancás. El ángulo diferenciador lo definís al principio, frente a tus referencias, y después lo mantenés. Si un día saltás de lo técnico al humor, tu audiencia no hace clic, se cae el CTR, la retención y YouTube frena la recomendación.", "silver": false, "video": {"id": "6-YFJhREYcA", "titulo": "¿Por qué tus vídeos de Youtube no funcionan? (No es el algoritmo)", "url": "https://www.youtube.com/watch?v=6-YFJhREYcA"}}, {"id": "g4-016", "modulo": "M5", "clase": "Guión Master", "pregunta": "Con la automatización todos mis videos me salen iguales, ¿qué hago?", "variantes": ["los guiones salen todos parecidos", "mis videos se repiten", "cómo evito que todo sea igual", "la ia me hace siempre el mismo guion"], "respuesta": "A medida que avanzás, cargale a Claude la data de tu canal para que vaya modificando las estructuras y no te salgan todos los videos iguales. YouTube ve con malos ojos el contenido repetitivo, así que variar guiones, edición y miniaturas es parte de mostrar que hay una persona detrás.", "silver": false}, {"id": "g4-017", "modulo": "M5", "clase": "Guión Master", "pregunta": "El corrector de guiones me marca muchas cosas, ¿corrijo todo?", "variantes": ["qué corrijo del corrector", "tengo que cambiar todo lo amarillo", "el corrector marca rojo y amarillo", "cómo uso el corrector de guiones"], "respuesta": "Para no perder tiempo: corregí todo lo rojo y, de lo amarillo, solo lo que esté muy al límite. Si son pequeñeces, Máximo no suele tocarlas. También podés pedirle que aplique todos los cambios directamente. La idea es que el corrector te ayude a pulir, no que te frene la producción.", "silver": false}, {"id": "g4-018", "modulo": "M5", "clase": "Guión Master", "pregunta": "¿Conviene cargarle a la IA libros o PDFs para que escriba mejores guiones?", "variantes": ["notebooklm para guiones", "subir pdfs de copywriting a la ia", "entrenar a la ia con libros", "base de documentos para guiones"], "respuesta": "Como herramienta de análisis y auditoría está muy bien. El techo aparece si le delegás la parte creativa: un modelo de lenguaje calcula la palabra más probable, así que tiende a guiones promedio. Usalo como motor analítico y dejá la creatividad, el tono y la perspectiva de tu lado.", "silver": false}, {"id": "g4-019", "modulo": "M5", "clase": "Retención", "pregunta": "¿Conviene pedirle a la IA un guion para la edición, además del de locución?", "variantes": ["guion audiovisual", "guion a dos columnas", "cómo planifico qué imágenes poner", "tardo mucho buscando clips"], "respuesta": "Sí, está muy recomendado. Lau propone un guion a dos columnas: de un lado el texto y del otro qué recurso va, así separás la búsqueda de material de la edición y trabajás por bloques. Te ahorra muchísimo tiempo. Y si producir te lleva demasiado, un video por semana bien hecho puede ser mejor que dos mediocres.", "silver": false}, {"id": "g4-020", "modulo": "M5", "clase": "Guión Master", "pregunta": "Tuve un video que explotó, ¿cómo hago otros parecidos sin canibalizarlo?", "variantes": ["cómo aprovecho un outlier", "repetir un video que funcionó", "hago otro video igual al que pegó", "cuándo subo el siguiente después de un outlier"], "respuesta": "Exprimir un formato exitoso es correcto porque indica demanda, aunque un outlier es una combinación de cosas. Mantené la estructura de la miniatura, la palabra clave y la estructura del título, y el guion; cambiá lo menos posible, pero cambiá la temática. Si no es tendencia, esperá a que las vistas por hora del outlier bajen durante un día antes de lanzar el siguiente. Si es tendencia, subí rápido.", "silver": false}, {"id": "g4-021", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué es la retención y dónde la veo?", "variantes": ["dónde veo la retención de mi video", "qué significa retención", "cómo veo cuánto miran mis videos", "dónde está la gráfica de retención"], "respuesta": "La retención te muestra cuánta gente sigue mirando tu video segundo a segundo. La ves en YouTube Studio, en Analytics > Participación > Retención de público. Se construye en tres capas: la idea y la promesa (título, miniatura y primeros 30 segundos), el guion y la edición. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-022", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué retención es buena en los primeros 30 segundos?", "variantes": ["cuánto tiene que quedar al inicio", "porcentaje bueno de retención", "qué retención mínima necesito", "mi video pierde gente al principio es normal"], "respuesta": "Los primeros 30 segundos (la zona gris de la gráfica) miden la promesa del video. En faceless conviene que queden arriba del 75-80%. Si está bastante por debajo, la promesa está floja o hubo clickbait: lo que prometiste en título y miniatura no aparece rápido. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-023", "modulo": "M5", "clase": "Retención", "pregunta": "¿Cuánta gente tiene que llegar al final del video?", "variantes": ["qué porcentaje tiene que llegar al final", "retención al final del video", "cuántos tienen que terminar el video", "para qué sirve que lleguen al final"], "respuesta": "Apuntá a que al menos un 33% de la audiencia llegue al final. Ahí van las pantallas finales y las tarjetas que mandan a otro video, y eso alarga el tiempo de sesión, que es lo que YouTube valora. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-024", "modulo": "M5", "clase": "Retención", "pregunta": "¿Cómo leo la curva de retención?", "variantes": ["qué significan las subidas en la gráfica", "por qué mi gráfica cae de golpe", "tipos de curva de retención", "cómo interpreto la gráfica de retención"], "respuesta": "Hay cuatro formas: plana, que es lo ideal; descenso gradual, cuando van perdiendo interés; subidas, que aparecen por capítulos, repeticiones o porque compartieron el video con marca de tiempo; y caídas, cuando omiten o abandonan porque esa parte aburre. Mirá dónde están las caídas para saber qué tramo del guion o de la edición corregir. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-025", "modulo": "M5", "clase": "Retención", "pregunta": "La gente se va en los primeros segundos de mi video, ¿qué hago?", "variantes": ["me abandonan al principio", "cómo mejoro el arranque del video", "qué pongo al inicio del video", "el gancho no funciona"], "respuesta": "Si la caída fuerte está en los primeros 30 segundos, el problema es el arranque. Sacá introducciones largas, saludos y el «en este video vamos a ver»: entrá directo al contenido que promete el título. Y chequeá que título, miniatura y contenido estén alineados, porque si el video no valida el clic, la gente se va. Esto lo ves en la clase «Retención».", "silver": false, "video": {"id": "m1AJcNSuFKw", "titulo": "Deja de hacer esto si quieres crecer en Yotube (el tip 3 es el mejor)", "url": "https://www.youtube.com/watch?v=m1AJcNSuFKw"}}, {"id": "g4-026", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué es la satisfacción del espectador y el tiempo de sesión?", "variantes": ["qué es el tiempo de sesión", "qué mide youtube además de la retención", "por qué importa que vean otro video", "qué es session time"], "respuesta": "Desde 2025 YouTube mide la satisfacción: si después de tu video la persona sigue en tu canal o en YouTube, el video se impulsa. No premia que produzcas más volumen, sino que te vean de forma secuencial. Por eso conviene pensar series de videos enlazados y no videos sueltos. Esto lo ves en la clase «Retención».", "silver": false, "video": {"id": "6-YFJhREYcA", "titulo": "¿Por qué tus vídeos de Youtube no funcionan? (No es el algoritmo)", "url": "https://www.youtube.com/watch?v=6-YFJhREYcA"}}, {"id": "g4-027", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué es la AVD?", "variantes": ["qué significa avd", "duración media de visualización", "cómo comparo videos de distinta duración", "qué es la duración promedio"], "respuesta": "La AVD es la duración media de visualización, en minutos. Te sirve para comparar videos de duraciones distintas, porque el porcentaje solo puede engañar. En «ver más» de la retención también podés comparar con tus otros videos y ver la actividad detallada: cuántos empiezan y cuándo dejan de mirar. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-028", "modulo": "M5", "clase": "Retención", "pregunta": "¿Cómo mejoro la retención desde la edición?", "variantes": ["cada cuánto cambio de imagen", "cuántas imágenes lleva un video", "imágenes acordes a cada frase o random", "cuántos clips necesito para 10 minutos"], "respuesta": "La edición es la tercera capa de la retención. La referencia es hacer cortes de 3 a 5 segundos; un video de 10 minutos puede llevar entre 80 y 200 imágenes o clips. Y siempre mirá a tu competencia: la idea es igualarla o superarla, porque un canal mejor hecho retiene mejor. Lo que mejor funciona es que lo que se ve refuerce lo que se dice: poné primero el audio y buscá imágenes para cada parte. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-029", "modulo": "M5", "clase": "Retención", "pregunta": "¿Desde qué video pido que se suscriban?", "variantes": ["cuándo pido la suscripción", "pido suscripción en los primeros videos", "me quemo si pido que se suscriban", "cuándo empiezo con los llamados a la acción"], "respuesta": "Desde el video uno. El miedo a quemarte es un mito: cualquiera de tus primeros videos puede ser amplificado, y si no hay un llamado a la acción desperdiciás suscriptores. Esos primeros suscriptores son tu audiencia semilla, la que YouTube usa para decidir si recomienda tus próximos videos. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-030", "modulo": "M5", "clase": "Retención", "pregunta": "¿Alcanza con el botón de suscripción automático de YouTube?", "variantes": ["la marca de agua alcanza", "las pantallas finales son suficientes", "hace falta pedir la suscripción con la voz", "cta de voz o botón automático"], "respuesta": "No. La marca de agua del canal y las pantallas finales son elementos pasivos: mientras mira, el espectador deja de percibirlos. Un llamado a la acción activo, con tu voz pidiendo la suscripción y una animación, funciona mucho mejor y además corta la monotonía. Que sea breve y después de entregar valor.", "silver": false}, {"id": "g4-031", "modulo": "M5", "clase": "Retención", "pregunta": "¿En qué momento del video pongo el llamado a la acción?", "variantes": ["dónde pongo el cta", "cómo pido que se suscriban sin que se vayan", "el clásico dale like sirve", "cómo hago un cta que no moleste"], "respuesta": "Justo después de entregar valor, no por marca de tiempo, y evitando los puntos donde la gente abandona. El típico «dale like y activá la campanita» hace que la gente se vaya; el llamado a la acción tiene que ir ligado a lo que estás contando para que sea orgánico. Por ejemplo, preguntarle al espectador su opinión sobre el tema del video. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-032", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué es un patrón de interrupción?", "variantes": ["qué son los patrones de interrupción", "cómo corto la monotonía del video", "cómo evito que se aburran a mitad del video", "para qué sirve un cambio de plano"], "respuesta": "Es un cambio que le resetea la atención al espectador: un cambio de encuadre, un corte de audio fuerte, un b-roll. Si mirás tus gráficas de retención, la gente se va en los tramos monótonos; el patrón de interrupción lo reconecta justo antes. Van desde el primer video, igual que los llamados a la acción.", "silver": false}, {"id": "g4-033", "modulo": "M5", "clase": "Retención", "pregunta": "¿Los anuncios en el medio del video afectan la retención?", "variantes": ["dónde pongo los midrolls", "los anuncios hacen que se vayan", "puedo mover los anuncios", "qué son los midrolls"], "respuesta": "Mientras no estés monetizado no los podés manejar. Cuando monetices, ubicalos en un momento donde vas a revelar o recompensar con información, porque ahí la persona se queda. Si lo ponés donde estás enganchando a la gente, puede ser la muerte de tu retención. Para encontrar esos momentos te podés ayudar con Claude y NexLev. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-034", "modulo": "M5", "clase": "Retención", "pregunta": "¿Conviene hacer series de videos conectados?", "variantes": ["cómo hago que vean otro video mío", "playlists y pantallas finales", "videos enlazados", "cómo armo una serie de videos"], "respuesta": "Sí, porque YouTube premia que la persona siga mirando después de tu video. El orden es: primero tus temas grandes salen de analizar los outliers de tu nicho; cada video tiene que funcionar solo; y recién después los conectás con pantallas finales y playlists. No arranques por la arquitectura antes de tener videos que funcionen. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-035", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué es un open loop y cómo lo uso en el guion?", "variantes": ["qué es un bucle abierto", "cómo dejo intriga en el guion", "técnicas para que no se vayan del video", "estructuras de guion avanzadas"], "respuesta": "Un open loop es una herramienta de guion dentro de un mismo video: abrís una curiosidad y la cerrás más adelante, para que el espectador sienta la necesidad de quedarse hasta la resolución. No confundirlo con la estrategia de canal ni con las series de videos. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "MNNy0TB1v9g", "titulo": "Gané $1,000 por Video con Guiones Automáticos de YouTube (Así lo Hago)", "url": "https://www.youtube.com/watch?v=MNNy0TB1v9g"}}, {"id": "g4-036", "modulo": "M5", "clase": "Retención", "pregunta": "Tengo pocos videos y mi retención es baja, ¿ya puedo sacar conclusiones?", "variantes": ["con 10 videos ya sé si funciona", "mis métricas son malas con pocos videos", "cuándo analizo mis números", "mi ctr y retención cambian mucho"], "respuesta": "Todavía no. Con pocas vistas, un solo usuario que entra y sale en 2 segundos te mueve el porcentaje un montón. En la formación aconsejamos no sacar conclusiones firmes hasta el video 30. Mientras, cuando pruebes algo, mové una sola variable a la vez y no lo midas con solo dos videos.", "silver": false}, {"id": "g4-037", "modulo": "M5", "clase": "Retención", "pregunta": "¿Cuánto tienen que durar mis videos?", "variantes": ["los videos de 5 minutos sirven", "qué duración conviene", "videos cortos o largos", "duración mínima del video"], "respuesta": "Máximo recomienda apuntar a un mínimo de 8 minutos: YouTube cada vez impulsa más los videos largos, y con 5 minutos quedás por debajo de lo que conviene para monetizar. Igual, mirá cuánto duran los videos de tu canal de referencia y armá el guion con el largo que pide tu nicho.", "silver": false, "video": {"id": "vl74Cg7QQLI", "titulo": "Cuánto Se Gana en YOUTUBE en 2026: El Nuevo Anuncio Que Paga Los Videos Cortos", "url": "https://www.youtube.com/watch?v=vl74Cg7QQLI"}}, {"id": "g4-038", "modulo": "M5", "clase": "Retención", "pregunta": "¿Cómo uso la IA para analizar mi retención?", "variantes": ["le paso la gráfica a claude", "cómo saco conclusiones de mis estadísticas", "sirve ask studio para analizar mi canal", "puedo usar las ideas de títulos de ask studio", "la ia puede leer mis métricas"], "respuesta": "Sacá capturas de la retención y de la actividad detallada en YouTube Studio y pasáselas a Claude para que te ayude a sacar conclusiones. También podés usar Ask Studio, el asistente de YouTube Studio, y probar las ideas de videos, títulos y miniaturas que te sugiere a partir de tu canal. Eso sí, usalas con pensamiento crítico: no confíes ciegamente en lo que te devuelven. Esto lo ves en la clase «Retención».", "silver": false}, {"id": "g4-039", "modulo": "M5", "clase": "Retención", "pregunta": "¿Qué cambia que YouTube cuente las vistas desde el inicio del video?", "variantes": ["ahora las vistas cuentan desde el segundo cero", "cambió cómo cuenta las visualizaciones", "por qué cayó mi retención inicial", "nuevo conteo de vistas de youtube"], "respuesta": "Con ese cambio, cualquier reproducción automática o clic de rebote suma una vista, así que la retención inicial puede mostrar una caída más fuerte y el contador pierde valor como análisis. Lau señala que pasan a ser críticos los primeros 15 segundos, el tiempo total de visualización y las interacciones. Máximo lo ve positivo: menos bots y más vistas para quien hace las cosas bien.", "silver": false}, {"id": "g4-040", "modulo": "M5", "clase": "Retención", "pregunta": "¿Subir Shorts ayuda a mi canal de videos largos?", "variantes": ["mezclo shorts con videos largos", "hago shorts para crecer", "los shorts suman suscriptores", "shorts y videos largos en el mismo canal"], "respuesta": "Por ahora no lo recomendamos. El espectador de Shorts está en modo de consumo rápido: si no lo atrapás en segundos, pasa al siguiente. Al mezclarlo con videos largos te destruye la retención y el tiempo de sesión, y eso es una mala señal para el algoritmo.", "silver": false, "video": {"id": "J9Ap9qyUr5I", "titulo": "¿Los YouTube Shorts están MATANDO tu canal Faceless?", "url": "https://www.youtube.com/watch?v=J9Ap9qyUr5I"}}, {"id": "g4-041", "modulo": "M5", "clase": "Retención", "pregunta": "¿Se puede saber si un video va a ser outlier?", "variantes": ["cómo hago un video viral", "puedo predecir si un video va a explotar", "qué tiene que tener un video para ser outlier", "cómo aumento las chances de un outlier", "¿Se puede predecir si un video va a ser un outlier?", "¿cómo hago un video viral?", "¿cómo sé si va a explotar?", "¿truco para outliers?", "¿cómo funciona el algoritmo a fondo?"], "respuesta": "No se puede asegurar: depende de la idea, el título, la miniatura y sobre todo la retención. Un outlier aparece cuando la idea tiene demanda, la miniatura tiene alto CTR, la retención es altísima, la gente interactúa y sigue mirando después. Una pista: si la gráfica de vistas arranca por encima de tu promedio y la retención también, va bien. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g4-042", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Con qué hago las miniaturas?", "variantes": ["qué herramienta uso para miniaturas", "app para hacer miniaturas", "cómo hago una miniatura con ia", "nano banana para miniaturas"], "respuesta": "Con Nano Banana es mucho más fácil: le adjuntás como referencia una miniatura que te guste y le vas pidiendo modificaciones. Lo recomendable es la imagen con IA, pero el texto y la exportación hacerlos a mano en Canva. Así, si tenés que apelar la monetización, podés mostrar intervención humana. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-043", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Puedo automatizar las miniaturas?", "variantes": ["hacer todas las miniaturas de un tirón", "sistema automático de miniaturas", "generar miniaturas en lote", "bot para miniaturas", "hay una app para hacer todas las miniaturas", "miniaturas automáticas sirve?", "hago las miniaturas con ia"], "respuesta": "Ojo con eso. Si te mandan a apelación tenés que mostrar cómo hacés las miniaturas, y es mejor demostrar que las hacés a mano. Automatizar queda para después de monetizar. Mientras tanto: imagen con IA y texto y exportación manual en Canva.", "silver": false}, {"id": "g4-044", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Puedo usar la misma miniatura en todos mis videos?", "variantes": ["repetir la misma miniatura", "todas las miniaturas iguales", "uso una plantilla fija de miniatura", "pasa algo si copio la miniatura", "¿Puedo usar la misma miniatura o plantilla en todos mis videos?", "repito la misma miniatura siempre", "miniaturas todas iguales está mal?", "uso una plantilla para todas las miniaturas", "copiar miniatura en cada video"], "respuesta": "Es uno de los errores graves: a veces YouTube deja de mostrarte y a veces desmonetiza. En faceless no hagas todas las miniaturas iguales (en marca personal sí conviene). Pueden tener un estilo, pero no ser todas muy parecidas, porque YouTube lo toma como contenido de bajo valor. Esto lo ves en la clase «Miniaturas».", "silver": false, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g4-045", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿En qué me baso para diseñar mis primeras miniaturas?", "variantes": ["cómo sé qué miniatura funciona en mi nicho", "de dónde saco ideas de miniaturas", "dónde aprendo a hacer miniaturas", "qué estilo de miniatura uso"], "respuesta": "Las miniaturas cambian según el nicho, por eso primero tenés que tener hecha la investigación. Arrancás tomando de base gráfica y conceptual los outliers de tus referentes y tu competencia, pero no te quedás a vivir ahí: cada audiencia responde distinto, así que vas iterando según tus métricas. Como base, que tenga un solo foco, alto contraste y pocas palabras. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-046", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Cómo pruebo qué estilo de miniatura funciona mejor?", "variantes": ["cambio el estilo de miniatura en cada video", "bloques de testeo de miniaturas", "cómo testeo miniaturas", "cuántos videos con un mismo estilo"], "respuesta": "Armá bloques de testeo: por ejemplo, 5 videos con un estilo, 5 con otro, y así. Cuando llegues al video 30 vas a tener volumen real para comparar varios enfoques. La clave es aislar la variable: si cambiás el estilo en cada video, el resultado puede ser puro azar.", "silver": false}, {"id": "g4-047", "modulo": "M7", "clase": "Miniaturas", "pregunta": "Mi miniatura tiene CTR bajo, ¿cuándo la cambio?", "variantes": ["cuánto espero para cambiar la miniatura", "falla el título o la miniatura", "mi video no tiene clics", "cada cuánto cambio la miniatura"], "respuesta": "El CTR de las primeras horas es el que define si YouTube muestra el video a más gente, así que lo ideal es cambiarla rápido, en un máximo de 5 días, como una prueba A/B, porque si no es un outlier el video muere rápido. Si las vistas por hora ya son muy bajas, no vale la pena cambiarla mucho después, porque casi nadie lo está viendo. Ojo: el CTR depende también del título. El cambio de miniatura hace efecto casi inmediato; si la cambiás y no varía nada, probablemente el que falla es el título.", "silver": false, "video": {"id": "oAI1OdUMJM8", "titulo": "La Prueba A/B de YOUTUBE Está DESTROZANDO Tu Canal (haz esto!)", "url": "https://www.youtube.com/watch?v=oAI1OdUMJM8"}}, {"id": "g4-048", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Hago pruebas A/B de miniaturas desde el primer video?", "variantes": ["las pruebas a/b sirven al principio", "no se subieron las miniaturas de la prueba a/b", "cuándo uso el test de miniaturas", "prueba a/b con pocos videos"], "respuesta": "Al principio son prácticamente irrelevantes. YouTube busca espectadores de distintas fuentes, cada una con comportamientos diferentes, y con pocas impresiones la prueba no te aporta demasiado. Fijate cuántos videos e impresiones tenés antes de preocuparte; mientras tanto, tu prioridad es seguir subiendo y probar estilos en bloques.", "silver": false, "video": {"id": "oAI1OdUMJM8", "titulo": "La Prueba A/B de YOUTUBE Está DESTROZANDO Tu Canal (haz esto!)", "url": "https://www.youtube.com/watch?v=oAI1OdUMJM8"}}, {"id": "g4-049", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Por qué no me deja poner una miniatura personalizada?", "variantes": ["no se guarda la miniatura", "me pone un fotograma del video", "no puedo subir miniatura", "cambié la miniatura y sigue la vieja"], "respuesta": "Revisá que tengas hechos los pasos de configuración del canal: número de teléfono e identidad verificados. Sin eso solo te deja usar fotogramas del video. Si ya está todo y sigue fallando, probá borrar las cookies (ojo, te borra accesos guardados) o mandá comentarios a soporte. Si la cambiaste y en el canal sigue la vieja, suele ser que YouTube tarda: mirala en incógnito o esperá unas horas.", "silver": false}, {"id": "g4-050", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Qué CTR es bueno?", "variantes": ["cuál es un buen ctr", "qué porcentaje de clics necesito", "mi ctr es bajo", "qué es el ctr"], "respuesta": "El CTR es el porcentaje de gente que hace clic cuando ve tu miniatura y tu título. Máximo considera bueno arriba de 6%. Igual, Lau aclara que los números de referencia son orientativos y dependen de cada caso, y con pocos videos el porcentaje se mueve mucho.", "silver": false, "video": {"id": "oAI1OdUMJM8", "titulo": "La Prueba A/B de YOUTUBE Está DESTROZANDO Tu Canal (haz esto!)", "url": "https://www.youtube.com/watch?v=oAI1OdUMJM8"}}, {"id": "g4-051", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Cómo combino el título con la miniatura?", "variantes": ["título y miniatura dicen lo mismo", "qué pongo en la miniatura y qué en el título", "la miniatura repite el título", "cómo evito el clickbait"], "respuesta": "Título y miniatura tienen que complementarse, no repetirse: la miniatura suma un gancho de curiosidad que el título no dice. Y lo que prometen tiene que cumplirse en los primeros 30 segundos del video: si el contenido no valida el clic, la gente se va y es señal de clickbait. Esto lo ves en las clases «Títulos» y «Miniaturas».", "silver": false, "video": {"id": "oAI1OdUMJM8", "titulo": "La Prueba A/B de YOUTUBE Está DESTROZANDO Tu Canal (haz esto!)", "url": "https://www.youtube.com/watch?v=oAI1OdUMJM8"}}, {"id": "g4-052", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Cómo escribo un buen título?", "variantes": ["estructura de un título", "cómo hago títulos que funcionen", "fórmula para títulos", "qué tiene que tener un título"], "respuesta": "Una estructura sugerida: palabra clave + dos puntos + promesa o gancho. Escribí como un humano, porque YouTube es semántico y entiende la intención. Usá una sola palabra de poder y pensá el título como la respuesta a una pregunta real que se haría tu audiencia. Esto lo ves en la clase «Títulos».", "silver": false}, {"id": "g4-053", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Dónde pongo la palabra clave y qué tan largo hago el título?", "variantes": ["largo ideal del título", "dónde va la keyword", "cuántos caracteres tiene que tener", "repito la palabra clave varias veces", "el título se corta en el celular"], "respuesta": "Poné la palabra clave o long tail en los primeros 30 a 40 caracteres, por ejemplo arrancando con «Nepal:», y apuntá a 50-60 caracteres en total para que no se corte en el celular. No la repitas ni satures de palabras clave: YouTube es semántico y entiende la intención, así que evitá términos duplicados como edición/editar o tips/tutorial. Esto lo ves en la clase «Títulos».", "silver": false}, {"id": "g4-054", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Qué palabras ayudan a que un título llame más la atención?", "variantes": ["palabras de poder", "pongo el año en el título", "qué números uso en el título", "le hablo a ustedes en el título", "qué es sin + objeción"], "respuesta": "Usá una sola palabra de poder, no varias. Sirve el recurso «sin + objeción»: sin experiencia previa, sin software de pago. Sumá el año: desde agosto o septiembre ya conviene poner el siguiente. Si usás números, que sean impares, y evitá los redondos o las mitades (5, 25, 50, 500). Y hablale a una persona: yo, tú o vos, nunca «ustedes». Esto lo ves en la clase «Títulos».", "silver": false}, {"id": "g4-055", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Cómo pruebo distintos títulos?", "variantes": ["cuántos títulos escribo antes de elegir", "cómo testeo títulos", "cambio la estructura de títulos en cada video", "cuánto tiempo pruebo un formato de título"], "respuesta": "Escribí de 3 a 5 variaciones antes de decidir. Y para testear, probá una sola variable a la vez: mantené una estructura de título durante 5 a 10 videos antes de sacar conclusiones. Si cambiás todo junto, no vas a saber qué funcionó. Esto lo ves en la clase «Títulos».", "silver": false}, {"id": "g4-056", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Qué es Ask YouTube y cómo afecta a mis títulos?", "variantes": ["no me aparece ask youtube", "búsqueda conversacional en youtube", "qué es ask youtube", "ask youtube en latinoamérica"], "respuesta": "Es la búsqueda conversacional de YouTube: la gente pregunta y YouTube responde con videos. Por eso conviene pensar el título como respuesta a una pregunta real. Según lo que compartió Lau, arrancó en beta en Estados Unidos y se va habilitando por etapas, así que si no te aparece, es normal. Esto lo ves en la clase «Títulos».", "silver": false}, {"id": "g4-057", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Qué tan importantes son las palabras clave?", "variantes": ["las keywords son lo más importante", "cómo hago seo en youtube", "importa la categoría del canal", "youtube entiende de qué trata mi video"], "respuesta": "Son importantes, pero no lo principal: lo principal es tu contenido. YouTube es semántico y entiende tu canal por tus guiones, títulos y descripción, mucho más que por la categoría (elegí la más cercana a tu nicho, pero casi no incide). Hoy el SEO que importa es el que responde a la consulta real del usuario, y el algoritmo analiza todo el paquete del video. Esto lo ves en la clase «Títulos».", "silver": false}, {"id": "g4-058", "modulo": "M7", "clase": "Títulos", "pregunta": "Las vistas que vienen de búsqueda bajan, ¿está mal?", "variantes": ["tráfico de búsqueda bajando", "de dónde vienen mis vistas", "qué es exploración y sugeridos", "mis vistas ya no vienen de búsqueda"], "respuesta": "Está bien. El tráfico por búsqueda viene por término y debería ir disminuyendo, salvo que hagas un video en tendencia. La idea es que después la mayoría llegue por exploración y videos sugeridos. Para ver de dónde vienen tus vistas, analizá tu canal en YouTube Studio: ese es el camino, analizar y mejorar.", "silver": false}, {"id": "g4-059", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Conviene pagar VidIQ para títulos y palabras clave?", "variantes": ["vale la pena vidiq", "vidiq para seo", "qué herramienta uso para keywords", "vidiq o nexlev"], "respuesta": "No es necesario. Máximo no paga VidIQ: todos sus canales se hicieron sin él y prefiere Claude conectado a NexLev. Lau rescata que su investigación sirve para buscar ideas y palabras clave long tail, pero sus títulos no le convencen. Si lo tenés, bien; si no, no pasa nada.", "silver": false}, {"id": "g4-060", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Le pongo subtítulos al video en la edición?", "variantes": ["subtítulos quemados en el video", "pongo subtítulos en capcut", "el txt de youtube tapa mis subtítulos", "subtítulos en pantalla sí o no"], "respuesta": "Hoy Lau no lo recomienda: los subtítulos en la edición son de lo más repetido en los canales faceless de baja calidad, y se superponen con los subtítulos nativos que YouTube muestra en el autoplay del inicio. Además, si quien mira activa los subtítulos de YouTube, te tapan los de CapCut. Lo que sí es obligatorio es subir los subtítulos nativos (CC) en todos tus videos.", "silver": false}, {"id": "g4-061", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Para qué subo el guion como subtítulos a YouTube y dónde lo hago?", "variantes": ["dónde adjunto el guion", "subir transcripción a youtube", "cómo subo los subtítulos cc", "sirve subir el txt del guion"], "respuesta": "Subirlo es obligatorio porque YouTube usa esa transcripción para entender y categorizar tu contenido. Primero marcá el idioma del video en la pantalla de subida, y después en la sección Subtítulos subís el texto. Podés pegar el guion en un .txt con el mismo nombre del video; sincroniza solo y después ajustás los bloques para que no queden líneas largas.", "silver": false}, {"id": "g4-062", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Cómo saco los capítulos y el archivo SRT exactos?", "variantes": ["los capítulos no coinciden con el video", "qué es un archivo srt", "subtítulos para videos largos", "cómo hago timestamps exactos"], "respuesta": "Pedile a Claude Code que instale Whisper (lo hace solo). Whisper pasa el audio a texto sabiendo cuándo empieza y termina cada parte, así los capítulos te salen exactos y te puede bajar el archivo SRT, que es texto con marcas de tiempo. Ese SRT es el que subís cuando YouTube te da la opción de subtítulos sincronizados. Sirve para videos de cualquier duración.", "silver": false}, {"id": "g4-063", "modulo": "M7", "clase": "Títulos", "pregunta": "¿Cómo escribo la descripción del video?", "variantes": ["qué pongo en la descripción", "descripción para seo", "cuánto escribo en la descripción", "la descripción sirve para algo"], "respuesta": "Lo básico: YouTube lee todo el paquete del video para entenderlo, y la descripción es parte junto con el título, la miniatura y la transcripción. Escribila como un humano, alineada con lo que busca tu audiencia y sin rellenar de palabras clave. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g4-064", "modulo": "M7", "clase": "Retención", "pregunta": "¿Cómo respondo los comentarios de mis videos?", "variantes": ["dónde veo los comentarios", "conviene responder comentarios", "cómo gestiono los comentarios", "qué le contesto a la gente"], "respuesta": "Los gestionás en YouTube Studio, en la sección Comunidad de la barra izquierda. Un buen hábito es responder con una pregunta para que la conversación siga, porque la interacción es una de las cosas que hay que dominar. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g4-066", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Qué es una miniatura y por qué importa tanto?", "variantes": ["para qué sirve la miniatura", "la miniatura es tan importante", "qué peso tiene la miniatura", "qué es el delivery"], "respuesta": "Es la imagen que la gente ve antes de hacer clic. Junto con el título y la descripción forma el delivery, que es el 50% del éxito; el video es el otro 50%. La miniatura se percibe en unos 0,3 segundos y empuja el CTR de las primeras horas, que es lo que define si YouTube le muestra tu video a más gente. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-067", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Qué medida tiene que tener la miniatura?", "variantes": ["tamaño de la miniatura", "resolución de la miniatura", "qué formato uso para la miniatura", "cuántos píxeles tiene la miniatura"], "respuesta": "La miniatura mide 1280x720 píxeles, en formato 16:9. Armala en ese tamaño desde el principio, y antes de publicar mirala también en chico, porque así es como la va a ver la mayoría de la gente en el celular y en el inicio de YouTube. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-068", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Cuánto texto pongo en la miniatura?", "variantes": ["cuántas palabras van en la miniatura", "pongo el título en la miniatura", "miniatura sin texto sirve", "qué escribo en la miniatura"], "respuesta": "Poco: de 1 a 3 palabras, 5 como máximo. Incluso podés hacerla sin texto si así funciona tu nicho. Ese texto no repite el título: lo complementa con un gancho de curiosidad. Fijate qué hacen los outliers de tus referentes para ver si en tu nicho se usa texto o no. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-069", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Qué es lo que más llama la atención en una miniatura?", "variantes": ["qué atrae más en una miniatura", "qué colores uso en la miniatura", "cómo hago que se note mi miniatura", "anatomía de una buena miniatura"], "respuesta": "Primero atrae una persona con los ojos visibles, después los colores fuertes como el rojo y el amarillo, y después el texto. La miniatura que funciona tiene un solo foco, alto contraste, poco texto y un gancho de curiosidad. Si metés muchas cosas, el ojo no sabe adónde ir en esos 0,3 segundos. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-070", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Conviene poner caras en la miniatura?", "variantes": ["pongo una persona en la miniatura", "caras con emoción", "hacia dónde mira el personaje", "sirve una cara en un canal faceless"], "respuesta": "Las caras con emoción real funcionan, y una persona con los ojos visibles es lo que más atrae. Además, la mirada o el gesto del personaje hacia el texto dirige la atención del espectador justo adonde querés. Que la emoción se note y que tenga que ver con lo que promete el video. Esto lo ves en la clase «Miniaturas».", "silver": false, "video": {"id": "rBbelWbbGZ0", "titulo": "Cómo Hacer Miniaturas de Youtube con Inteligencia Artificial I De Principiante a PRO", "url": "https://www.youtube.com/watch?v=rBbelWbbGZ0"}}, {"id": "g4-071", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Qué errores tengo que evitar en una miniatura?", "variantes": ["errores comunes en miniaturas", "por qué mi miniatura se ve mal", "fondo borroso en la miniatura", "cómo reviso mi miniatura antes de subir"], "respuesta": "Los más comunes: fondos débiles, borrosos o pixelados; demasiadas cosas compitiendo, sin un foco claro; mucho texto; y en faceless, hacer todas las miniaturas iguales. Antes de publicar, mirala en tamaño chico: si no se entiende ahí, no va a funcionar en el celular. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g4-072", "modulo": "M7", "clase": "Miniaturas", "pregunta": "¿Hago la miniatura antes o después del video?", "variantes": ["cuándo hago la miniatura", "dejo la miniatura para el final", "orden para hacer la miniatura", "la miniatura va al final"], "respuesta": "Antes. La recomendación es hacer la miniatura antes que el video, para no dejarla para el final. Y recordá que lo que promete la miniatura, junto con el título, tiene que cumplirse en los primeros 30 segundos del video, así que conviene tenerla clara mientras armás el guion. Esto lo ves en la clase «Miniaturas».", "silver": false}, {"id": "g5-001", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Qué herramienta uso para hacer la voz con IA?", "variantes": ["qué app para la voz en off", "con qué hago la locución", "mejor programa de texto a voz", "Kukarella o ElevenLabs", "qué IA de voz me recomiendan"], "respuesta": "Depende de tu presupuesto. Si tenés poco, arrancá con Kukarella; si podés invertir un poco más, ElevenLabs te da más control y calidad. Fish Audio también es una opción que Max usa y recomienda. No hay una herramienta mágica: la mejor es la que se acomoda a tu producción y a tu bolsillo. Elegí una, aprendé a configurarla bien y mantenela en todos tus videos. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-002", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Por qué la voz de IA me suena robótica?", "variantes": ["la voz suena como robot", "cómo hago que la voz suene natural", "la locución suena fea y plana", "la IA lee raro mi guion"], "respuesta": "El modelo no entiende ortografía: lee fonemas y prosodia. Por eso la puntuación es tu herramienta gratis para que suene natural: comas, puntos y pausas le marcan el ritmo. Escribí las palabras en inglés, los números y las siglas como se pronuncian. Y una vez que encontraste una configuración que te gusta, no la cambies. Ojo, que una voz robótica es de las cosas que más perjudican a un canal. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-003", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Cómo escribo números, siglas o palabras en inglés para que la voz los lea bien?", "variantes": ["la IA lee mal los números", "pronuncia mal las siglas", "cómo pongo una palabra en inglés en el guion", "lee mal los años"], "respuesta": "Escribilos como suenan. El modelo trabaja con fonemas, no con ortografía, así que si ponés «1945» o una sigla tal cual, puede leerlo cualquier cosa. Pasalo a palabras («mil novecientos cuarenta y cinco»), separá las siglas como se dicen y escribí los términos en inglés con su pronunciación. Después escuchá ese párrafo y, si falla, corregís solo esa parte. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-004", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Pego todo el guion de una o lo genero por partes?", "variantes": ["genero el audio entero o por párrafos", "la voz cambia de acento a la mitad", "se puso a hablar en otro idioma", "conviene generar todo junto", "pegar el texto completo"], "respuesta": "Generalo por párrafos. Así ahorrás plata, evitás alucinaciones (que la voz cambie de acento o de idioma a mitad de camino) y, si algo sale mal, regenerás solo esa parte en lugar de todo el guion. Después unís los audios en el editor. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-005", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Qué configuración de estabilidad, similitud y velocidad le pongo a la voz?", "variantes": ["qué valores uso en ElevenLabs", "cómo configuro la voz", "estabilidad y similitud cuánto", "toco los ajustes en cada párrafo"], "respuesta": "Lo clave es la consistencia: probá hasta encontrar la estabilidad, similitud y velocidad que te gustan y después fijalas. No las toques entre párrafos ni entre guiones. Que todos los clips suenen igual es lo que hace que suene profesional. Si sentís la voz plana, jugá con esos ajustes y la expresividad en la etapa de prueba, no en medio de un video. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-006", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Qué modelo de ElevenLabs uso, v2 o v3?", "variantes": ["Multilingual v2 o v3", "cuál es mejor modelo de ElevenLabs", "para qué sirve v3", "las etiquetas entre corchetes"], "respuesta": "Para la mayoría de los videos, Multilingual v2: da buena similitud, control fino y es más barato. El v3 sirve para meter etiquetas de expresión entre corchetes, pero usalas con sutileza; consume bastante más y, salvo que tu formato sea muy dramático, en YouTube no hace gran diferencia. En v2 mejorás el resultado con los ajustes de la voz y los controles de énfasis. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-007", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿En qué formato descargo el audio de la voz?", "variantes": ["qué calidad elijo al bajar el audio", "MP3 o WAV", "formato de salida ElevenLabs", "cómo bajo la locución"], "respuesta": "En ElevenLabs elegí salida MP3 a 44.1 kHz y 192 kbps, con speaker boost activado. Un buen truco: generá dos versiones, escuchalas y bajá la que mejor suene. Después importás ese MP3 directo en CapCut. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-008", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Cómo paso mi guion a voz en ElevenLabs paso a paso?", "variantes": ["cómo uso ElevenLabs", "dónde pego el guion en ElevenLabs", "primeros pasos con la voz IA", "cómo genero la locución"], "respuesta": "Entrá a Text to Speech, pegá el guion (mejor por párrafos) y revisalo. Elegí o agregá la voz desde Mis voces, filtrando por idioma, acento y estilo. Ajustá velocidad, estabilidad y similitud, elegí el modelo y el formato MP3 44.1 kHz. Generá, escuchá las versiones y descargá la que más te guste. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-009", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Puedo probar ElevenLabs gratis antes de pagar?", "variantes": ["ElevenLabs tiene plan gratis", "cuántos créditos gratis da ElevenLabs", "tengo que pagar para probar la voz", "cuenta free de ElevenLabs"], "respuesta": "Sí. Lau siempre recomienda abrir la cuenta freemium de ElevenLabs, que no tiene costo y te da 10.000 créditos renovables por mes para probar y testear. No hace falta comprometerte a una suscripción de entrada. Casi todas las herramientas tienen algo parecido, así que aprovechá para comparar antes de pagar. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-010", "modulo": "M6", "clase": "Narración IA", "pregunta": "Las voces en español de ElevenLabs me suenan planas, ¿qué hago?", "variantes": ["voz en español sin emoción", "la voz no tiene expresión", "ElevenLabs suena aburrido", "cómo le doy más vida a la voz"], "respuesta": "Depende de qué versión estés usando. En v2, jugá con el seteo de la voz (expresividad, velocidad, similitud) y con los controles de énfasis; también ayuda mucho cuidar la puntuación del guion. En v3 podés usar las etiquetas de emoción entre corchetes, con sutileza. Probá varias voces filtrando por idioma y acento: es bastante subjetivo, así que elegí la que mejor encaje con tu canal. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-011", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Cómo clono mi propia voz?", "variantes": ["quiero usar mi voz clonada", "qué app para clonar mi voz", "clonación de voz cuál conviene", "cuánto audio necesito para clonar"], "respuesta": "Dale mucho audio al modelo. Con muestras de pocos segundos (zero shot) la clonación queda mal; lo que funciona es el entrenamiento con bastante material, del orden de 30 minutos. ElevenLabs en su plan intermedio acepta esas muestras largas, y Fish Audio es otra opción probada por alumnos y más económica. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-012", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Puedo clonar la voz de un famoso o de otro youtuber?", "variantes": ["clonar voz de otra persona", "usar la voz de un narrador conocido", "copiar la voz de otro canal", "clonar voz ajena"], "respuesta": "No. No clones voces ajenas sin autorización. Si querés una voz propia del canal, clonás la tuya o elegís una de las voces de la biblioteca de la herramienta y la mantenés siempre igual. Eso además le da identidad a tu canal. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-013", "modulo": "M6", "clase": "Narración IA", "pregunta": "Cloné mi voz en Kukarella y no aparece, ¿dónde quedó?", "variantes": ["no encuentro mi voz clonada en Kukarella", "Kukarella se borró mi clon", "grabé la voz y desapareció", "dónde está la voz clonada"], "respuesta": "Tranqui, no se perdió. Max lo probó: después de grabar, la pantalla queda como si no hubiera pasado nada, sin ningún mensaje, pero en realidad se está procesando. Esperá más o menos una hora y entrá a la sección «Clone a voice»: ahí la vas a encontrar. Si no aparece, el soporte de Kukarella responde bien. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-014", "modulo": "M6", "clase": "Narración IA", "pregunta": "Kukarella me tira error 500, ¿qué hago?", "variantes": ["error 500 en Kukarella", "Kukarella no carga el guion", "Kukarella no funciona", "error al pasar el texto"], "respuesta": "Los errores 500 son del servidor, no tuyos. Probá abrir Kukarella en otro navegador; suele resolverse así. Si sigue, esperá un día o dos y volvé a intentar en tu navegador de siempre. Mientras tanto, guardá tu guion dividido en párrafos así retomás rápido. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-015", "modulo": "M6", "clase": "Narración IA", "pregunta": "Pedí un guion de 10 minutos pero la voz dura mucho menos, ¿qué pasó?", "variantes": ["la locución quedó corta", "el audio dura menos de lo que quería", "no llego a los minutos", "guion corto para 8 minutos", "Pedí un guion de 10 minutos y la locución dura mucho menos, ¿qué pasa?", "el guion me queda corto", "la voz dura menos de lo que pedí", "no llego a los minutos del video", "la ia no respeta la cantidad de palabras"], "respuesta": "Pasa seguido. Muchas veces el guion maestro pide pocas palabras por bloque y el modelo respeta eso antes que el largo total: revisá que la suma de los bloques dé el total que buscás. Además, la narración en ElevenLabs va rápido (en inglés ronda 150 a 160 palabras por minuto, según la voz). Si queda corta, pedí más párrafos al guion y regenerá solo lo nuevo. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-016", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Cuánto tiene que durar la locución de mi video?", "variantes": ["cuántos minutos tiene que tener el video", "duración mínima del video", "8 minutos por qué", "de cuánto hago el guion"], "respuesta": "Según la clase, el video tiene que durar al menos 8 minutos para poder monetizarse. Por eso, cuando le pedís el guion a ChatGPT, adaptá la estructura a 8 minutos o más. Si la locución te queda corta, pedí más párrafos y regenerá la voz de esa parte. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-017", "modulo": "M6", "clase": "Narración IA", "pregunta": "Estoy gastando muchos créditos probando la voz, ¿cómo ahorro?", "variantes": ["se me van los créditos", "gasto mucho en ElevenLabs", "cómo no gastar tanto en pruebas", "me quedé sin créditos"], "respuesta": "Al principio es normal gastar más por la prueba y error; después se optimiza. Tres trucos: generá por párrafos y regenerá solo lo que falla, usá voces en v2 (más baratas que v3) y no cambies la configuración en cada intento. Cuando algo te gusta, recién ahí subís la calidad. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-018", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Grabo la locución con el celular o con un programa?", "variantes": ["puedo grabar mi voz con el celu", "necesito micrófono", "con qué grabo mi voz", "usar mi propia voz en los videos"], "respuesta": "Las dos sirven. Con el celular sin micrófono, pasá el audio por un limpiador como Adobe Podcast. Celular más un micrófono simple es la mejor opción: la grabación sale mucho más limpia. Grabar en un programa como Audacity conviene si ya sabés algo de audio, porque ahí podés ecualizar y bajar ruido. Después ajustás volumen y efectos en CapCut. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-019", "modulo": "M6", "clase": "Narración IA", "pregunta": "Mi grabación de voz tiene ruido, ¿cómo la mejoro?", "variantes": ["limpiar audio con ruido", "sacar el ruido de fondo de mi voz", "mi voz suena mal grabada", "mejorar audio del celular"], "respuesta": "Adobe Podcast es la que Max usa seguido y recomienda: subís la grabación, incluso hecha con el teléfono, y la limpia muy bien. Si tenés CapCut Pro, también trae funciones con IA para limpiar audio. Y si sabés de audio, en Audacity podés ecualizar y reducir ruido a mano. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-020", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿YouTube desmonetiza los videos con voz de IA?", "variantes": ["puedo usar voz IA y monetizar", "la voz artificial es un problema", "YouTube castiga la voz IA", "tengo que usar mi voz sí o sí"], "respuesta": "Lo que perjudica es la voz robótica, no la IA en sí. Hay canales con voz IA y canales con voz humana que monetizan. Para alejarte de un rechazo: usá una voz natural y bien configurada, modificale algún parámetro (velocidad, expresividad), o clona tu propia voz o usá la tuya. Y sumale un guion retocado por vos y una edición propia. Esto lo ves en la clase «Narración IA».", "silver": false, "video": {"id": "QDI67WVg1OY", "titulo": "Esto es lo que está pasando en YouTube ahora I DESMONETIZADOS", "url": "https://www.youtube.com/watch?v=QDI67WVg1OY"}}, {"id": "g5-021", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Conviene pagar Neuroflix para tener ElevenLabs y otras IAs juntas?", "variantes": ["Neuroflix sirve", "plataforma con varias IAs barata", "Neuroflix para la voz", "recomiendan Neuroflix"], "respuesta": "Hoy no la recomiendan. Max borró el post donde la sugería porque varios alumnos reportaron que el servicio decayó, sobre todo en soporte. Para la voz, mejor ir directo a Kukarella o a ElevenLabs, que podés probar gratis con la cuenta freemium. Esto lo ves en la clase «Narración IA».", "silver": false}, {"id": "g5-022", "modulo": "M6", "clase": "Narración IA", "pregunta": "¿Tengo que pagar herramientas para hacer mi primer video?", "variantes": ["puedo empezar gratis", "qué suscripciones necesito para arrancar", "cuánto tengo que invertir en herramientas", "hay opciones gratis para editar y la voz"], "respuesta": "Podés arrancar gastando poco. Para la voz, Kukarella si tenés poco presupuesto o la cuenta freemium de ElevenLabs para probar. Para editar, CapCut, y si no querés pagar, DaVinci es gratis. Las imágenes podés buscarlas en Google o en bancos gratuitos. Eso sí, cuando el canal ya produce en serio, alguna herramienta paga vas a necesitar. Esto lo ves en la clase «Edición».", "silver": false, "video": {"id": "50A3R42ckBI", "titulo": "Si comenzara un canal de YOTUBE FACELESS con IA en 2026 haría esto", "url": "https://www.youtube.com/watch?v=50A3R42ckBI"}}, {"id": "g5-023", "modulo": "M6", "clase": "Edición", "pregunta": "¿Con qué programa edito los videos?", "variantes": ["qué editor uso", "CapCut o DaVinci", "programa para editar gratis", "dónde armo el video"], "respuesta": "En la clase se edita en CapCut, que es simple y tiene muchas soluciones prefabricadas. Si preferís algo gratis y sin restricciones, DaVinci Resolve es más robusto, aunque un poco más pesado. Lo importante es que edites vos y guardes tus proyectos en tu compu. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-024", "modulo": "M6", "clase": "Edición", "pregunta": "¿Me conviene CapCut Pro o alcanza con el gratis?", "variantes": ["vale la pena CapCut Pro", "diferencias CapCut gratis y pago", "comprar CapCut Pro a un revendedor", "CapCut free sirve"], "respuesta": "Con el gratis podés arrancar. Max recomienda CapCut Pro porque cada vez trae más IA que ayuda en la edición, como limpieza de audio, y no tiene el límite de exportación de 2 GB de la versión gratis. Si te ofrecen Pro por un revendedor, ojo: no lo pueden recomendar porque no saben cómo funciona. Y sea cual sea el editor, guardá siempre tus proyectos. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-025", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cuáles son los pasos para armar mi primer video?", "variantes": ["cómo hago un video faceless de cero", "por dónde empiezo a editar", "paso a paso del video", "cómo se arma un video con imágenes y voz"], "respuesta": "El flujo es: sacás la estructura del guion de tu canal de referencia, pedís el guion de tu tema, lo pasás a voz y lo descargás en MP3. En CapCut creás un proyecto, ponés el audio en la línea de tiempo y vas sumando imágenes en 16:9 a pantalla completa. Les das movimiento con fotogramas clave, agregás textos, transiciones y filtros, normalizás el audio y exportás. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-026", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo saco el guion para después hacer la voz?", "variantes": ["de dónde saco el guion", "cómo copio la estructura del canal de referencia", "prompt para el guion", "cómo hago el guion con ChatGPT"], "respuesta": "Tomá los guiones de los 5 o 6 videos más populares de tu canal de referencia, pasalos a PDF y pedile a ChatGPT que extraiga la estructura y la adapte a videos de 8 minutos. Guardala como prompt maestro y adjuntala cada vez que pidas un guion nuevo (usá canvas si es largo). Copiás la estructura, no el contenido, y retocalo con tu toque antes de pasarlo a voz. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-027", "modulo": "M6", "clase": "Edición", "pregunta": "¿De dónde saco las imágenes para el video?", "variantes": ["dónde busco fotos", "bancos de imágenes gratis", "páginas de stock gratis", "imágenes para mi canal"], "respuesta": "En la clase se buscan en Google Imágenes con filtro de tamaño grande, para que tengan buena resolución. También tenés bancos gratuitos como Pexels, Unsplash, Pixabay o Kaboompics, y el stock de Canva o Magnific si tenés cuenta. Siempre revisá la licencia por si piden dar crédito, y que la imagen sea nítida. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-028", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo usar cualquier foto de Google Imágenes?", "variantes": ["fotos de Google tienen copyright", "puedo bajar imágenes de internet", "qué fotos de Google evito", "imágenes con licencia"], "respuesta": "Podés usar fotos de Google, pero evitá las que dicen que tienen licencia. Buscá en tamaño grande para que se vean bien, y mezclalas con otras fuentes (bancos gratuitos, imágenes o videos de IA) para que tu video no se vea igual a otros. Y siempre agregá tu valor: voz, edición y orden propios. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-029", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo usar fragmentos de documentales o de otros videos?", "variantes": ["usar clips de un documental", "meter partes de otro video", "clips de películas en mi video", "cómo evito el copyright con clips"], "respuesta": "Con cuidado. Si usás fragmentos de documentales: espejalos, no pases de 5 segundos por fragmento, cambiá el orden y sumales tu voz y tu valor. YouTube pide que si usás contenido ajeno lo modifiques de forma significativa, así que nada de subir clips tal cual. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-030", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo usar los videos cortos de stock de Canva?", "variantes": ["videos de Canva tienen copyright", "usar clips de stock en mi video", "videos de bancos gratis sirven", "me desmonetizan por usar stock"], "respuesta": "Sí, pero con cuidado, porque seguramente otro creador ya los usó y te pueden rechazar por contenido reutilizado. Reencuadralos (otro zoom o recorte), espejalos y sumales algún texto. Mezclalos con fotos e imágenes de otras fuentes y agregá valor humano con tu voz y tu edición. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-031", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo pongo las imágenes para que ocupen toda la pantalla?", "variantes": ["la imagen queda con bordes negros", "formato 16:9 en CapCut", "ajustar foto a pantalla completa", "qué formato usa el video"], "respuesta": "Trabajá el proyecto en 16:9 y ajustá cada imagen para que ocupe toda la pantalla, sin bordes. Por eso conviene bajar imágenes de buena resolución: al agrandarlas no se pixelan. Si una imagen tiene una marca en el borde, agrandarla para que salga del cuadro también te sirve. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-032", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo le doy movimiento a una imagen fija?", "variantes": ["cómo hago zoom en una foto", "animar imágenes en CapCut", "fotogramas clave", "efecto de movimiento en las fotos"], "respuesta": "Con fotogramas clave (keyframes) de posición y escala. Marcás un punto al inicio y otro al final de la imagen, y cambiás el tamaño o la posición entre ellos: así hacés zoom in, zoom out, recorridos en diagonal o con varios puntos. Variá los movimientos entre imágenes para que no se vea todo igual. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-033", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo copio el mismo movimiento a muchas imágenes rápido?", "variantes": ["copiar el zoom a otras fotos", "aplicar el efecto a todas las imágenes", "copiar atributos CapCut", "repetir el paneo"], "respuesta": "Hacé el paneo en una imagen con keyframes de inicio y final. Después clic derecho sobre ese clip, «Copiar atributos», seleccionás las imágenes que querés y «Pegar atributos». También existe la animación automática, pero queda medio plantilla, así que mejor variá a mano. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-034", "modulo": "M6", "clase": "Edición", "pregunta": "¿Pongo una imagen por cada frase o imágenes cada cierto tiempo?", "variantes": ["cada cuánto cambio de imagen", "imágenes al azar con zoom sirve", "cómo elijo qué imagen va en cada parte", "sincronizar imágenes con la voz"], "respuesta": "Mirá cómo lo hace tu competencia: la idea es igualarla o superarla, porque un canal mejor hecho retiene más. Max pone primero el audio y va dándole play y pausa, buscando imágenes que refuercen lo que se dice. En nichos como meditación eso importa menos, pero en general conviene que lo que se ve acompañe lo que se escucha. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-035", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo hacer el video con una sola imagen con zoom lento?", "variantes": ["video con una foto en loop", "una imagen fija todo el video", "efecto ken burns todo el video", "pocas imágenes en el video"], "respuesta": "No te lo recomendamos. Lau analizó los canales desmonetizados y se repite el mismo patrón: imagen estática en loop con efecto Ken Burns, voz robótica, sin edición ni variedad. Usá varias imágenes, con movimientos distintos y que acompañen el guion. Esto lo ves en la clase «Edición».", "silver": false, "video": {"id": "QDI67WVg1OY", "titulo": "Esto es lo que está pasando en YouTube ahora I DESMONETIZADOS", "url": "https://www.youtube.com/watch?v=QDI67WVg1OY"}}, {"id": "g5-036", "modulo": "M6", "clase": "Edición", "pregunta": "¿Le pongo transiciones a todos los cortes?", "variantes": ["cuántas transiciones uso", "transiciones entre todas las imágenes", "qué transición queda bien", "filtros y transiciones"], "respuesta": "No hace falta. El corte directo ya es una transición. Sumá transiciones y filtros con criterio, no en cada clip. Lo que da dinamismo es mezclar planos de distinta duración y perspectiva: más largos para momentos dramáticos, más cortos para dar ritmo. Muchas veces una edición simple queda más limpia que una recargada. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-037", "modulo": "M6", "clase": "Edición", "pregunta": "Editar unos minutos me lleva horas, ¿cómo lo hago más rápido?", "variantes": ["tardo mucho en editar", "cómo acelero la edición", "me lleva días un video", "editar es muy lento"], "respuesta": "Editar mejora con la práctica, no hay atajo. Un cambio grande: no busques recursos mientras editás. Primero juntá todas las imágenes del guion, y después editá en un bloque aparte; saltar de tarea en tarea te liquida la concentración. No te compliques con tutoriales difíciles: en CapCut, lo simple suele quedar más limpio. Y mejor un video bueno por semana que dos mediocres. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-038", "modulo": "M6", "clase": "Edición", "pregunta": "¿Es normal tardar tanto en hacer el primer video?", "variantes": ["tardé un montón en el primer video", "soy muy lento al principio", "me frustra lo que tardo", "el primero me costó mucho"], "respuesta": "Sí, es totalmente normal. Es parte de ejercitar la cintura creativa: a medida que practicás, automatizás procesos y los tiempos se achican muchísimo. Recordá este primer video, porque pronto vas a mirar atrás y no vas a creer lo que tardabas. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-039", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cuánto debería tardar en producir un video?", "variantes": ["tiempo promedio por video", "cuántas horas lleva un video", "en cuánto tiempo hago un video de 10 minutos", "cuánto tarda la edición"], "respuesta": "No hay un tiempo fijo, depende del nicho. Como referencia, Max cuenta que un canal simple de 10 minutos puede llevarte una hora y media por video cuando arrancás con edición básica, y con el tiempo bajarlo a unos 45 minutos. Hacé una prueba de edición antes de lanzar el canal para medir cuánto tardás vos. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-040", "modulo": "M6", "clase": "Edición", "pregunta": "¿A qué volumen dejo la voz en CapCut?", "variantes": ["cuántos decibeles la voz", "nivel de audio de la narración", "el audio se satura", "la voz suena bajita"], "respuesta": "Lo más importante es que la voz se escuche durante todo el video por encima de cualquier efecto o música, y que nunca llegue a rojo ni suene saturada. Como referencia, Max deja la voz alrededor de -6 a -3 dB en los picos y, si hay música, alrededor de -18 dB. Y normalizá el audio antes de exportar. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-041", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo sé si el audio de mi video está bien antes de subirlo?", "variantes": ["chequear el volumen antes de publicar", "normalizar audio", "YouTube baja el volumen", "cómo pruebo el sonido"], "respuesta": "Normalizá el audio en CapCut y después escuchá el video con auriculares, en el celular y en una tele o compu, para asegurarte de que suene cómodo en todos. Como lo escuchás vos lo van a escuchar los demás. YouTube no sube un audio bajito, pero si está muy alto lo baja a un estándar de 14 LUFS. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-042", "modulo": "M6", "clase": "Edición", "pregunta": "¿Con qué configuración exporto el video?", "variantes": ["cómo exporto en CapCut", "qué resolución exporto", "4K o 1080", "formato para subir a YouTube"], "respuesta": "En la clase se exporta en 4K, MP4 y H.264, poniéndole nombre al archivo y cancelando la opción de compartir. Después guardalo en la carpeta de tu canal. Si el archivo te pesa demasiado, podés bajar la resolución o cambiar a H.265. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-043", "modulo": "M6", "clase": "Edición", "pregunta": "CapCut no me deja exportar videos de más de 2 GB, ¿qué hago?", "variantes": ["error de peso al exportar", "el video pesa mucho", "límite de 2 GB CapCut", "no puedo exportar el video largo"], "respuesta": "Es una restricción de la versión gratuita. Opciones: pasarte a DaVinci, que es gratis y sin ese límite; o bajar el peso al exportar, reduciendo resolución (de 4K a 2K, por ejemplo) o bitrate, o cambiando la compresión de H.264 a H.265. También podés exportar por partes en H.265 y unirlas, perdiendo un poquito de calidad. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-044", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo organizo los archivos de mis videos?", "variantes": ["dónde guardo los proyectos", "tengo que guardar los guiones", "puedo editar en un CapCut online compartido", "qué hago con los archivos después de subir"], "respuesta": "Armá una carpeta por canal con guiones, audios y videos, e idealmente un respaldo en disco externo. Es un activo reutilizable, por ejemplo para llevar el canal a otros idiomas. Además, si YouTube te rechaza la monetización, te piden mostrar los proyectos originales, así que conviene que estén en tu compu y no en un editor online ajeno. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-045", "modulo": "M6", "clase": "Edición", "pregunta": "¿Le pongo subtítulos en pantalla a mis videos?", "variantes": ["subtítulos quemados en el video", "pongo texto con lo que dice la voz", "subtítulos automáticos de CapCut", "conviene subtitular"], "respuesta": "Lau no lo recomienda: hoy es una práctica asociada a canales de contenido masivo de baja calidad y no te suma nada. Además, en la portada de YouTube los videos se reproducen solos con los subtítulos nativos y se superponen. Lo que sí tenés que hacer siempre es subir el archivo de subtítulos (CC) en YouTube, porque el algoritmo lo usa para entender tu contenido. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-046", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo subo los subtítulos (CC) a YouTube sin pagar nada?", "variantes": ["cómo hago el archivo SRT", "subtítulos gratis para YouTube", "herramienta para subtítulos con tiempos", "dónde subo los subtítulos"], "respuesta": "No necesitás pagar ni gastar créditos. Copiá tu guion a un bloc de notas, guardalo como .txt con el mismo nombre del video y subilo en la sección de subtítulos de YouTube: se sincroniza solo. Lo único manual es ajustar los bloques de texto para que no queden líneas larguísimas en pantalla. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-047", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo sincronizo las imágenes si la voz está en un idioma que no entiendo?", "variantes": ["edito un video en inglés y no lo entiendo", "canal en otro idioma cómo edito", "no sé dónde va cada imagen", "subtítulos bilingües CapCut"], "respuesta": "En CapCut podés activar subtítulos bilingües: poné el audio en la línea de tiempo, andá al menú Subtítulos, elegí el idioma de origen y activá «Subtítulos bilingües». Así ves qué se dice en cada momento y acomodás las imágenes. Antes de exportar, acordate de borrar esos subtítulos. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-048", "modulo": "M6", "clase": "Edición", "pregunta": "¿Tengo que avisar que usé IA cuando subo el video?", "variantes": ["dónde pongo que es contenido con IA", "contenido sintético alterado", "lo aclaro en la descripción", "casilla de IA en YouTube"], "respuesta": "Sí. Al subir el video, debajo de la descripción y la miniatura aparece la casilla de contenido alterado o sintético: esa es la única que cuenta ante YouTube. Ponerlo en la descripción o en el video no vale. Max y Lau recomiendan marcarla si usaste IA en el proceso. Esto lo ves en la clase «Edición».", "silver": false, "video": {"id": "uIF68kQmaMg", "titulo": "SynthID: YouTube Automatizado te está marcando (y no lo sabes)", "url": "https://www.youtube.com/watch?v=uIF68kQmaMg"}}, {"id": "g5-049", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo usar un editor con IA que arme el video solo?", "variantes": ["app que edita automáticamente", "Opus Clip para mis videos", "editor que hace cortes por prompt", "la IA puede editar por mí"], "respuesta": "Con cuidado. La edición es lo que le muestra a YouTube que hay un humano detrás. Si te mandan a revisión y no tenés proyectos propios, no podés demostrar que no automatizaste. Usá esas herramientas para partes puntuales, pero no para armar todo el video, y guardá siempre tus proyectos. Esto lo ves en la clase «Edición».", "silver": false, "video": {"id": "hxTpugOFcyw", "titulo": "El fin de los canales automatizados? Cómo sobrevivir a la nueva política de YOUTUBE", "url": "https://www.youtube.com/watch?v=hxTpugOFcyw"}}, {"id": "g5-050", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo saco la marca de agua de una imagen o clip?", "variantes": ["borrar marca de agua", "el clip tiene logo en la esquina", "quitar el logo de Gemini", "marca de agua Veo"], "respuesta": "La forma más rápida al editar: agrandá la imagen para que esa esquina quede fuera de cuadro. Ojo, esto vale para material tuyo, como lo que generaste vos con IA. Si la marca es de otro creador, no lo uses: te pueden reclamar. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-051", "modulo": "M6", "clase": "Edición", "pregunta": "Tengo imágenes de baja resolución, ¿cómo las mejoro?", "variantes": ["la foto se ve pixelada", "escalar imágenes gratis", "agrandar una imagen sin perder calidad", "imágenes chicas para 4K"], "respuesta": "Primero, tratá de buscar imágenes grandes desde el principio (en Google, filtro de tamaño grande). Si igual te queda alguna chica, Max usa bastante Upscayl, que es gratis y escala muy bien. Así no se pixelan cuando las ponés a pantalla completa en 16:9. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-052", "modulo": "M6", "clase": "Edición", "pregunta": "¿Qué necesito instalar en la compu para editar?", "variantes": ["qué computadora sirve para editar", "PC o notebook", "qué programas instalo", "apps para trabajar en SEN6"], "respuesta": "Sé minimalista y dejá espacio para que la edición funcione fluida. Casi todo lo que usamos va en la nube: las IAs y Skool funcionan en el navegador. Instalá Google Chrome y CapCut (recomiendan la versión instalada). Para la compu, priorizá potencia (una PC rinde más) o movilidad si viajás (notebook). Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-053", "modulo": "M6", "clase": "Edición", "pregunta": "No sé editar nada, ¿puedo igual hacer un canal?", "variantes": ["nunca edité un video", "no tengo conocimientos de edición", "qué canal hago si no sé editar", "es difícil editar"], "respuesta": "Sí. Arrancá con el video más común en faceless: imágenes más locución. Hacé un video de prueba siguiendo la clase y medí cuánto tardás por minuto; eso te dice si el tipo de canal es viable para tu nivel actual. Hay canales que solo usan fotos de la web y son mucho más rápidos de hacer. Esto lo ves en la clase «Edición».", "silver": false}, {"id": "g5-054", "modulo": "M6", "clase": "Edición", "pregunta": "¿Le pongo música de fondo al video?", "variantes": ["necesito música en el video", "música de fondo sí o no", "de dónde saco música", "música sin copyright"], "respuesta": "En canales con locución mucha gente mira acelerado, así que mejor no pongas música salvo que tu canal de referencia la tenga. Si la usás, que sea de la Biblioteca de audio de YouTube, que está dentro de YouTube Studio y es la opción más segura, y con el audio normalizado para que la voz quede siempre arriba. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-055", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo usar la música que trae CapCut?", "variantes": ["música de CapCut tiene copyright", "me llegó un reclamo por la música de CapCut", "canciones de CapCut en YouTube", "biblioteca de CapCut"], "respuesta": "No. La música de CapCut está licenciada para TikTok y uso personal, no para YouTube, y además otros creadores la usan mucho. Si ya te llegó un aviso, es un reclamo de Content ID, no un strike: los ingresos de ese video irían al dueño de la música. Lo podés resolver reemplazando o silenciando ese tramo desde YouTube Studio. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-056", "modulo": "M6", "clase": "Edición", "pregunta": "¿Dónde consigo efectos de sonido sin problemas?", "variantes": ["efectos de sonido gratis", "los SFX de CapCut tienen copyright", "puedo sacar sonidos de otro video de YouTube", "sonido ambiente para el video"], "respuesta": "No los descargues de otros videos de YouTube: te los pueden marcar como contenido duplicado. Para efectos, Lau recomienda Pixabay, FreeSound y SoundBible, que son gratuitas, pero leé siempre los requisitos de atribución. La YouTube Audio Library también tiene, más básicos. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-057", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo hacer la música con IA, como Suno?", "variantes": ["música con Suno para monetizar", "música generada por IA es mía", "crear banda sonora con IA", "Suno tiene copyright"], "respuesta": "Se puede, pero suma riesgo. La música hecha con IA no siempre se desmonetiza, pero agrega riesgo, y no podés registrarla a tu nombre. Max recomienda quedarte con la Biblioteca de audio de YouTube o una biblioteca paga como Epidemic Sound. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "R38vZH6BCsA", "titulo": "NO crees estos canales en YOUTUBE FACELESS", "url": "https://www.youtube.com/watch?v=R38vZH6BCsA"}}, {"id": "g5-058", "modulo": "M6", "clase": "Edición", "pregunta": "Mi video tiene música de fondo de un lugar, ¿cómo se la saco?", "variantes": ["quitar música de un video", "separar la voz de la música", "aislar la voz", "video con música de concierto"], "respuesta": "Si la dejás, Content ID te va a generar un aviso, y camino a la monetización no te conviene. Se puede aislar la voz con herramientas como Adobe Podcast Enhance o el Voice Isolator de ElevenLabs, aunque si hay mucho ruido mezclado no siempre queda bien. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-059", "modulo": "M6", "clase": "Edición", "pregunta": "Si mejoro con IA una foto con derechos de autor, ¿la puedo usar?", "variantes": ["foto con copyright pasada por IA", "agrandar una foto ajena con IA", "modificar una imagen protegida", "la IA cambia los derechos de una foto"], "respuesta": "No. Aunque la mejores o la pases a 16:9 con IA, sigue siendo una obra derivada y mantiene los derechos de la foto original. Pasarla por IA no elimina la propiedad del autor. Usá imágenes libres, de bancos gratuitos o generadas por vos desde cero. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-060", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo usar videos de IA que hicieron otros usuarios?", "variantes": ["usar clips del explorador de Kling", "videos IA de otros en mi canal", "bajar videos generados por otros", "imágenes de IA ajenas", "¿Puedo usar videos de IA que generaron otros usuarios?", "uso videos del explorador de kling", "puedo bajar videos ia de otros", "imágenes de ia de otra persona sirven", "copiar videos generados por ia"], "respuesta": "No te lo recomendamos: al ser creados por otro usuario te pueden reclamar. A Max le dejaron sin monetizar un video por eso. Lo que sí podés hacer es tomar la idea del prompt y generar tu propia versión. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-061", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo generar las imágenes con IA en vez de buscarlas?", "variantes": ["qué IA uso para imágenes", "generar cientos de imágenes por video", "imágenes con IA gratis", "Nano Banana o Flow"], "respuesta": "Sí. Una opción que recomienda Max es Google Flow, que podés probar con una cuenta de Gmail y usa Nano Banana para imágenes. En Lite trabajás con imágenes buscadas; la generación con IA, en lote y con personajes consistentes, es otro nivel. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "uIF68kQmaMg", "titulo": "SynthID: YouTube Automatizado te está marcando (y no lo sabes)", "url": "https://www.youtube.com/watch?v=uIF68kQmaMg"}}, {"id": "g5-062", "modulo": "M6", "clase": "Edición", "pregunta": "¿Con qué IA genero clips de video para mis videos?", "variantes": ["IA para hacer videos", "Kling o Seedance", "animar imágenes con IA", "generar video desde una imagen"], "respuesta": "Max usa Kling por su relación calidad-precio; Seedance es otra opción si tenés más presupuesto. También están en suites como Magnific o Higgsfield. La mejor es la que resuelve tu contenido según tu presupuesto, así que probá antes de pagar. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-063", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo hago un avatar o personaje que hable con mi locución?", "variantes": ["avatar con lipsync", "personaje que mueva la boca", "HeyGen para mi canal", "animar un personaje que hable"], "respuesta": "Hay herramientas como HeyGen u OmniHuman. Lo básico para que funcione: un audio limpio, una imagen del personaje en buena resolución, de frente, con ojos, nariz y boca bien visibles y sin manos tapando la cara. Esto lo vemos a fondo en Silver.", "silver": true, "video": {"id": "nwytwdiqdxE", "titulo": "Crea tu Canal de YouTube SIN CÁMARA, y monetiza con IA", "url": "https://www.youtube.com/watch?v=nwytwdiqdxE"}}, {"id": "g5-064", "modulo": "M6", "clase": "Edición", "pregunta": "¿Cómo hago gráficos, infografías o animaciones sin After Effects?", "variantes": ["motion graphics fácil", "hacer infografías en el video", "animaciones de texto profesionales", "gráficos animados"], "respuesta": "Una solución que usa Max es conectar Claude Code con Remotion o HyperFrames, donde solo pagás el uso de Claude. En Lite te alcanza con los textos, transiciones y filtros de CapCut para tus primeros videos. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g5-065", "modulo": "M6", "clase": "Edición", "pregunta": "¿Puedo automatizar la búsqueda de imágenes o la edición con Claude?", "variantes": ["automatizar el video con IA", "Claude Code para editar", "que la IA busque las imágenes", "automatizar todo el canal"], "respuesta": "Se puede automatizar parte de la búsqueda de imágenes con Claude Code, pero encarece el proceso y requiere conocimiento. Y ojo: si YouTube te manda a apelación, necesitás mostrar intervención humana en el guion, la edición y la subida. Esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g6-001", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Qué es el contenido reutilizado y por qué desmonetizan por eso?", "variantes": ["qué significa contenido reutilizado", "me rechazaron por contenido reutilizado, qué es", "si no copié nada, por qué dicen reutilizado", "qué es contenido repetitivo para youtube"], "respuesta": "Ojo con esto, porque confunde a muchos: no hace falta que hayas copiado material ajeno. YouTube también mete en esa bolsa el contenido de bajo esfuerzo o hecho en masa: plantillas idénticas, poca o nula intervención humana, guiones reciclados, voz robótica, miniaturas copiadas. Lo que quiere ver es que el video sea una creación tuya, que aporte algo y que no exista solo para juntar vistas. Igual, las políticas cambian: leé la versión oficial de YouTube seguido. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g6-002", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo usar clips e imágenes de bancos gratuitos en mis videos sin que me desmoneticen?", "variantes": ["puedo usar videos de pexels o pixabay", "se pueden usar clips de stock", "uso imágenes de bancos y me desmonetizan?", "está permitido usar material ajeno"], "respuesta": "Sí, podés sacar clips e imágenes de bancos, siempre que les sumes valor humano. La política que comparte Max dice que si usás contenido ajeno tenés que modificarlo de forma significativa para que se considere tuyo. En la práctica: tu guion y tu voz en off le dan un sentido nuevo al material, y la edición es tuya. Se puede tomar la estructura de otros, nunca el contenido tal cual. Revisá siempre la licencia de cada banco. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g6-003", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Cómo uso los videos cortos de Canva sin que me tomen el video como reutilizado?", "variantes": ["puedo usar videos de canva", "los clips de canva dan problema", "cómo modifico un clip de stock", "qué cambios le hago a los videos de canva"], "respuesta": "Se puede, pero con cuidado, porque ese clip seguramente ya lo usó otro creador. Lo que recomienda Max: reencuadralo desde el inicio (zoom, recorte, otro encuadre), espejalo, sumale algún texto en algunos, y no armes todo solo con Canva: mezclalo con fotos, imágenes o videos de IA. Si usás voz de IA, cambiale algún parámetro como velocidad o expresividad, o usá tu propia voz. Con eso te alejás bastante de un rechazo. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-005", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿La IA está prohibida en YouTube para monetizar?", "variantes": ["youtube desmonetiza todo lo hecho con ia?", "puedo usar ia y monetizar", "se puede monetizar contenido con ia", "youtube prohibió la ia"], "respuesta": "No, la IA no está prohibida. Max y Lau lo explican así: es una herramienta más de producción; lo que se castiga es el contenido perezoso, repetitivo, de producción masiva y sin intervención humana, o el que vive del clickbait. Max cuenta que hay casos de canales hechos con IA que monetizaron. La clave es que se note la cabeza humana en el guion, la edición y la subida. Para el detalle fino, leé siempre la política oficial de YouTube. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g6-006", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Qué parte del video tiene que ser humana para que YouTube no lo tome como automatizado?", "variantes": ["qué tengo que hacer yo y qué la ia", "cómo demuestro que hay un humano detrás", "qué es intervención humana", "youtube detecta los videos hechos solo con ia?"], "respuesta": "Sí, YouTube busca presencia humana en el proceso. Lo que marca Max: tené guiones (aunque te ayudes con IA, retocalos y sumá tu opinión), editá vos y no todos los videos iguales, que las miniaturas tengan un estilo pero no sean casi idénticas, y no uses voces robóticas. Si no, lo toma como contenido de bajo valor y no lo monetiza, o lo desmonetiza después. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "hxTpugOFcyw", "titulo": "El fin de los canales automatizados? Cómo sobrevivir a la nueva política de YOUTUBE", "url": "https://www.youtube.com/watch?v=hxTpugOFcyw"}}, {"id": "g6-007", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo pegar el guion tal cual me lo da la IA?", "variantes": ["uso el guion de chatgpt directo", "el guion lo hace la ia, está mal?", "tengo que reescribir el guion de la ia", "guion con ia desmonetiza?"], "respuesta": "Mejor que no. Max recomienda no pegar el guion directo de la IA: retocalo, agregá tu opinión, tu perspectiva. Lau suma que la IA está buenísima para analizar estructura y patrones narrativos, pero el tono, la voz, los modismos y la forma de hablar tienen que ser tuyos y únicos de tu canal. Eso es lo que separa un canal con valor de uno automatizado de relleno. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-008", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿La voz de IA me puede traer problemas para monetizar?", "variantes": ["puedo usar voz de elevenlabs", "voz robótica desmonetiza?", "uso voz artificial, está bien?", "qué voz uso para no tener problemas"], "respuesta": "Se puede usar voz de IA, pero que no suene robótica. Max recomienda una voz de buena calidad y modificarle algún parámetro, como velocidad o expresividad, o directamente clonar o usar tu propia voz. La voz robótica aparece seguido en el perfil de los canales que vienen desmonetizando. Y acordate de marcar la casilla de contenido sintético al subir. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "QDI67WVg1OY", "titulo": "Esto es lo que está pasando en YouTube ahora I DESMONETIZADOS", "url": "https://www.youtube.com/watch?v=QDI67WVg1OY"}}, {"id": "g6-010", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo hacer videos con una sola imagen con un leve movimiento?", "variantes": ["un video con una imagen fija sirve", "imagen estática con zoom desmonetiza?", "pocas imágenes en todo el video", "efecto ken burns en todo el video"], "respuesta": "No te lo recomendamos. Lau describe el perfil de los canales desmonetizados: imagen estática en loop con efecto de zoom, voz robótica, sin transiciones, sin edición, misma música todo el tiempo, guiones reciclados. Max aclara que algunos canales que muestra en sus reels son para enseñar lo rentable que es YouTube, no siguen la metodología, y que el que había usado una sola imagen corrigió eso para seguir monetizado. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "QDI67WVg1OY", "titulo": "Esto es lo que está pasando en YouTube ahora I DESMONETIZADOS", "url": "https://www.youtube.com/watch?v=QDI67WVg1OY"}}, {"id": "g6-011", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Conviene ponerle subtítulos quemados a mis videos?", "variantes": ["pongo subtítulos en la edición?", "subtítulos en pantalla está bien", "cómo pongo subtítulos gratis", "los subtítulos ayudan a monetizar?"], "respuesta": "Lau no lo recomienda para nada: hoy los subtítulos en la edición son uno de los elementos repetitivos más típicos de los canales faceless de baja calidad, y pueden leerse como contenido producido en masa. Lo que sí es obligatorio es subir los subtítulos nativos de YouTube (CC) en todos los videos, porque el algoritmo los usa para entender y categorizar tu contenido. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-012", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "Si uso IA solo para la voz o para algunas imágenes, ¿tengo que declararlo?", "variantes": ["tengo que marcar contenido sintético", "solo la voz es ia, lo declaro?", "declarar ia baja las vistas?", "marco que es contenido alterado"], "respuesta": "Sí. Max y Lau coinciden: siempre que uses IA, en cualquier parte del proceso, marcá la casilla de contenido alterado o sintético al subir el video. Y tranquilo: según Max, eso no afecta en nada la distribución de tu canal. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "uIF68kQmaMg", "titulo": "SynthID: YouTube Automatizado te está marcando (y no lo sabes)", "url": "https://www.youtube.com/watch?v=uIF68kQmaMg"}}, {"id": "g6-013", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Dónde se declara que usé IA: en la descripción, en el video o en el canal?", "variantes": ["lo pongo en la descripción que es ia", "dónde aviso que usé inteligencia artificial", "basta con aclararlo en el video?", "dónde está la casilla de ia"], "respuesta": "Lo único que vale ante YouTube es la casilla de contenido sintético que aparece al subir el video, en el recuadro debajo de la descripción y la miniatura. Lau lo aclara: podés mencionarlo también en el video o en la descripción, pero eso solo no cuenta como declaración. Ahí mismo marcá también si es o no contenido para niños. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "uIF68kQmaMg", "titulo": "SynthID: YouTube Automatizado te está marcando (y no lo sabes)", "url": "https://www.youtube.com/watch?v=uIF68kQmaMg"}}, {"id": "g6-014", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Por qué me dicen que guarde los proyectos y el material de cada video?", "variantes": ["para qué guardo los archivos", "tengo que guardar los proyectos de edición", "qué guardo por si me rechazan", "puedo editar en la nube"], "respuesta": "Porque si te rechazan la monetización y apelás, tenés que poder mostrar que hay un proceso humano: guiones, proyectos de edición, cómo hacés las miniaturas. Max recomienda guardar todo el material en una carpeta y tener los proyectos originales en tu computadora; por eso desaconseja editores dentro de plataformas donde después no podés descargar el proyecto. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-015", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo usar una app de IA que arma el video entero por mí?", "variantes": ["hay una ia que hace todo el video?", "uso un editor automático con ia", "opus clip o apps que editan solas", "herramientas que editan por prompt"], "respuesta": "Podés, pero bajo tu riesgo. Max advierte que si YouTube te manda a apelación y el video lo armó una IA, no tenés guiones ni proyectos para demostrar que no automatizaste, y eso es justo lo que YouTube no quiere. Si la usás, que sea parcialmente y que la herramienta te deje intervenir, guardar y descargar el proyecto. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "hxTpugOFcyw", "titulo": "El fin de los canales automatizados? Cómo sobrevivir a la nueva política de YOUTUBE", "url": "https://www.youtube.com/watch?v=hxTpugOFcyw"}}, {"id": "g6-017", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo automatizar el contenido desde mi primer canal?", "variantes": ["arranco directo con automatización", "automatizar todo el canal se puede", "uso automatizaciones en lote", "automatización en el primer canal"], "respuesta": "Max no lo recomienda para un primer canal, por dos motivos: no desarrollás habilidades de edición y proceso manual, y YouTube puede reconocer patrones de automatización y rechazar la monetización. Él aclara que lo hace corriendo riesgos y con cuentas viejas que ya tienen confianza ganada. Si en algún momento automatizás, que haya intervención tuya en guion, edición y subida. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "hxTpugOFcyw", "titulo": "El fin de los canales automatizados? Cómo sobrevivir a la nueva política de YOUTUBE", "url": "https://www.youtube.com/watch?v=hxTpugOFcyw"}}, {"id": "g6-018", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "Si uso canales de referencia, ¿YouTube me lo toma como copia?", "variantes": ["usar un canal de referencia es copiar?", "me van a desmonetizar por copiar otro canal", "clonar un canal funciona", "tomar la estructura de otro canal está bien"], "respuesta": "Si copiás, sí te va a ir mal; pero el método no es copiar. Max lo explica: validás que haya audiencia, tomás la estructura ganadora y después cambiás todo el contenido, y sobre todo el ángulo. Eso es lo que te hace un canal único y no uno igual a los demás. Clonar canales nunca funcionó. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "LbuKQhm7DfY", "titulo": "La Fórmula Para Hacer VIDEOS VIRALES EN YOUTUBE Antes De Que Sea Tarde (YouTube 2027)", "url": "https://www.youtube.com/watch?v=LbuKQhm7DfY"}}, {"id": "g6-020", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿La música de CapCut es segura para videos de YouTube?", "variantes": ["puedo usar la música de capcut", "efectos de capcut tienen copyright", "me reclamaron por música de capcut", "sonidos de capcut en youtube"], "respuesta": "No te la recomendamos. Lau explica que las licencias de la biblioteca de CapCut están pensadas para TikTok y uso personal; en YouTube pueden saltar reclamos de Content ID. Y Max suma que, como muchos creadores usan esa misma música, podés tener problemas de contenido reutilizado cuando quieras monetizar. Mejor usá bibliotecas pensadas para YouTube. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-021", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo sacar sonidos o música de otros videos de YouTube?", "variantes": ["bajo un sonido ambiente de otro video", "uso el audio de otro youtuber", "descargar sonidos de youtube", "sonido de fondo sacado de otro canal"], "respuesta": "No te conviene. Lau lo dice directo: no lo descargues de otros videos de YouTube, porque te lo puede marcar como contenido duplicado. Usá bibliotecas gratuitas de efectos de sonido como Pixabay, FreeSound o SoundBible (leyendo si piden atribución), o la Biblioteca de audio de YouTube. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-022", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Dónde consigo música de fondo sin problemas para monetizar?", "variantes": ["qué música uso en mis videos", "música sin copyright dónde", "biblioteca de audio de youtube cómo", "qué música es segura"], "respuesta": "La más segura, según Max, es la Biblioteca de audio de YouTube, dentro de YouTube Studio: las pistas con licencia CC requieren que copies los créditos en la descripción. Lau, cuando el canal ya está monetizado, usa casi solo Epidemic Sound, que es pago. Ojo: gratis no siempre significa sin atribución, leé las condiciones de cada sitio. Max tampoco recomienda loopear la misma pista todo el video. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-023", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo usar música hecha con IA, como Suno, en videos que quiero monetizar?", "variantes": ["música de suno se puede monetizar", "creo la música con ia", "música ia tiene copyright?", "canal de música con ia monetiza"], "respuesta": "Se puede, pero suma riesgo. Max dice que la música con IA agrega bastante riesgo de desmonetización, aunque no siempre pase, y él prefiere la Biblioteca de YouTube o Epidemic Sound. Lau aclara que el derecho a usarla comercialmente depende del plan: con el gratuito no podés monetizarla. Y un canal que sea solo música de IA, sin guion, Max lo ve casi imposible de monetizar. Esto lo ves en la clase «Contenido reutilizado».", "silver": false, "video": {"id": "R38vZH6BCsA", "titulo": "NO crees estos canales en YOUTUBE FACELESS", "url": "https://www.youtube.com/watch?v=R38vZH6BCsA"}}, {"id": "g6-024", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "Me salió un reclamo de Content ID por música, ¿es un strike? ¿Qué pasa con la monetización?", "variantes": ["me llegó un aviso de copyright por la música", "content id qué significa", "reclamo de derechos de autor en un video", "el video tiene copyright y no gana plata"], "respuesta": "Tranquilo: un reclamo de Content ID no es un strike. Lau explica que significa que el dueño de la música identificó su pista: el video sigue público, pero los ingresos de ese video irían al titular, no a vos; no afecta al resto. Se puede resolver reemplazando, silenciando o recortando el tramo desde YouTube Studio. Max suma que un canal puede estar monetizado y aun así no ganar con los videos que tienen reclamos. Esto lo ves en la clase «Contenido reutilizado».", "silver": false}, {"id": "g6-025", "modulo": "M9", "clase": "Cómo configurarlo", "pregunta": "¿Cómo protejo mi canal y mi cuenta de AdSense de hackeos?", "variantes": ["seguridad de la cuenta de adsense", "cómo evito que me roben el canal", "verificación en dos pasos hace falta", "medidas de seguridad para el canal"], "respuesta": "Lau marca un mínimo obligatorio: verificación en dos pasos en todas tus cuentas (YouTube ya la exige para entrar al Programa de Socios), mejor con app de autenticación, passkey o llave física que por SMS; un email único por canal; y un gestor de contraseñas con claves distintas. Nunca pongas como contacto público el email con el que creaste el canal: usá un correo aparte. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-027", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Cuáles son los requisitos para monetizar un canal de videos largos?", "variantes": ["cuántos suscriptores necesito para monetizar", "cuántas horas de reproducción pide youtube", "requisitos del programa de socios", "qué necesito para ganar plata en youtube"], "respuesta": "Hoy, para formato largo, necesitás 1.000 suscriptores y 4.000 horas de visualización pública en los últimos 12 meses, o 10 millones de vistas de Shorts en 90 días. Desde el 1 de febrero de 2027 los canales nuevos van a necesitar 8.000 horas o 20 millones de vistas de Shorts. Si entrás antes, quedás con las condiciones actuales. Cumplir los números no alcanza solo: después viene una revisión de políticas. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "zUfp4Z6xoZ4", "titulo": "Cómo monetizar en Youtube Automatizado con las NUEVAS REGLAS", "url": "https://www.youtube.com/watch?v=zUfp4Z6xoZ4"}}, {"id": "g6-028", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Es verdad que el requisito sube de 4.000 a 8.000 horas?", "variantes": ["suben las horas para monetizar", "8000 horas de reproducción", "cambian los requisitos de monetización", "duplican las horas necesarias"], "respuesta": "Sí. YouTube anunció que desde el 1 de febrero de 2027 los canales nuevos van a necesitar 8.000 horas en 12 meses (o 20 millones de vistas de Shorts en 90 días), el doble que hoy. Si entrás al programa antes de esa fecha, quedás con las reglas actuales: por eso conviene apurar el sprint. Y tranquilo: el crecimiento en YouTube casi nunca es lineal. Muchas veces un solo video que pega te acerca a la meta más rápido que muchos videos regulares.", "silver": false, "video": {"id": "Sd61yrZolAg", "titulo": "YouTube CAMBIÓ las reglas de monetización (2027) — El cambio más grande de la historia", "url": "https://www.youtube.com/watch?v=Sd61yrZolAg"}}, {"id": "g6-029", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Cómo hago para llegar a las horas de reproducción si mis videos tienen pocas vistas?", "variantes": ["cómo junto 4000 horas", "me faltan muchas horas", "cómo llego más rápido a monetizar", "se puede monetizar con pocos videos"], "respuesta": "Lau insiste en que el juego es encontrar un outlier: un video que acierte en el tema, tenga buen empaque y retenga, puede darte más horas que decenas de videos regulares. Max suma lo que lleva a eso: una idea con alta demanda y poca oferta, una miniatura con alto CTR y una retención altísima en la muestra inicial. Y no saques conclusiones antes de tener una buena cantidad de videos: en SEN6 decimos esperar al video 30. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "wVo2-1folnA", "titulo": "Te quedan 4 meses para MONETIZAR en YouTube con las reglas viejas (plan de 120 días)", "url": "https://www.youtube.com/watch?v=wVo2-1folnA"}}, {"id": "g6-030", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Las horas de videos ocultos o privados cuentan para monetizar?", "variantes": ["cuentan los videos privados", "si oculto un video pierdo horas", "horas de videos no listados", "qué horas cuentan para el requisito"], "respuesta": "No. Según la clase, para el requisito solo cuentan las horas de visualización pública: los videos ocultos o privados no suman. Tenelo en cuenta antes de ocultar videos que te están trayendo horas. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g6-031", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Se puede monetizar un canal solo de Shorts?", "variantes": ["requisitos para shorts", "cuántas vistas necesito en shorts", "monetizar con shorts conviene", "canal de shorts monetiza"], "respuesta": "Se puede. Según la clase, en Shorts el requisito son 10 millones de vistas públicas en los últimos 90 días, no en el año. Pero Max no lo recomienda: son negocios más efímeros, cuando dejás de tener virales se cae, y tenés que subir muchos videos por día. Tanto su experiencia como la de sus mentores coinciden en que conviene el formato largo. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "SAW-PZamvf0", "titulo": "Los Shorts destruyen tu monetización: esto es lo que no te dicen en Youtube", "url": "https://www.youtube.com/watch?v=SAW-PZamvf0"}}, {"id": "g6-032", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Qué es la meta intermedia de 500 suscriptores?", "variantes": ["qué pasa con 500 suscriptores", "super chat y membresías cuándo", "beneficios antes de monetizar", "qué se habilita antes de los 1000"], "respuesta": "Según la clase, con 500 suscriptores y 3.000 horas se habilitan funciones como Super Chat, Super Stickers, Super Thanks y membresías. Es un buen escalón intermedio mientras vas hacia los requisitos completos del Programa de Socios. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g6-033", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Qué revisa YouTube cuando cumplo los requisitos y postulo?", "variantes": ["qué pasa cuando llego a los requisitos", "cómo es la revisión de monetización", "qué miran los revisores", "me revisan el canal antes de aprobar"], "respuesta": "Al llegar a los requisitos, YouTube revisa con IA y con personas que el canal cumpla las políticas de monetización y las normas de la comunidad. Según la política que compartió Max, como no pueden ver todo, suelen mirar el tema principal, los videos más vistos y más recientes, los de mayor tiempo de reproducción, los títulos, miniaturas y descripciones, y la sección de información del canal. Las políticas cambian: leelas seguido. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g6-034", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Dónde leo las políticas oficiales de monetización de YouTube?", "variantes": ["dónde están las políticas de youtube", "link de las normas de monetización", "políticas del programa de socios", "dónde leo las reglas oficiales", "¿Dónde leo las políticas de YouTube?", "¿dónde están las reglas de youtube?", "¿qué normas tengo que leer?", "políticas de monetización", "normas de la comunidad"], "respuesta": "Lau insiste en que hay que leerlas y conocerlas, porque son las reglas del negocio que querés armar. Están en las páginas oficiales de YouTube: la sección de políticas y lineamientos para creadores, el centro de ayuda de YouTube y la comunidad de ayuda. Buscá siempre la fuente oficial de cualquier novedad, no la versión de terceros. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "Z_Ebze3KG6Y", "titulo": "YouTube te quita el dinero por estos 4 errores (y nadie te lo dice)", "url": "https://www.youtube.com/watch?v=Z_Ebze3KG6Y"}}, {"id": "g6-035", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "Con el cambio que cuenta vistas desde el primer segundo, ¿cambian los requisitos?", "variantes": ["ahora las vistas cuentan desde el inicio", "vista con interacción qué es", "el cambio de vistas afecta la monetización", "cuentan más vistas, gano más?"], "respuesta": "No. Lau explica que desde el cambio una vista cuenta desde el primer fotograma, y lo que antes era vista ahora se llama vista con interacción. Según YouTube, los ingresos se siguen calculando con vistas y horas con interacción, los requisitos para monetizar no cambiaron, y el CTR y la retención se calculan igual. Un contador más grande no te hace ganar más. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g6-036", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Por qué las horas del panel general no coinciden con las de la pestaña de monetización?", "variantes": ["las horas de monetización son menos", "no coinciden las horas en youtube studio", "horas de reproducción distintas", "por qué tarda en actualizar las horas"], "respuesta": "Es normal. Lau lo explica: hay un retraso que YouTube llama data lag; en el panel de monetización puede ser de 3 a 5 días, porque congela esas horas mientras verifica que no haya tráfico falso. Las horas oficiales son las que te cuenta como válidas el panel de monetización, y ahí solo entran horas públicas válidas. No te asustes si ves diferencia. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g6-037", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "Mi canal todavía no está monetizado pero muestra anuncios, ¿por qué?", "variantes": ["salen anuncios en mi canal sin monetizar", "youtube pone publicidad en mis videos", "anuncios sin estar en el programa de socios", "me pagan por esos anuncios?", "Mi canal no está monetizado pero aparecen anuncios, ¿por qué?", "hay publicidad en mis videos y no cobro", "¿youtube gana con mi canal?", "¿por qué hay anuncios si no monetizo?", "¿es malo que haya anuncios?"], "respuesta": "Es normal desde un cambio de 2021. Max explica que al aceptar las condiciones de YouTube aceptás que puede mostrar anuncios en tu canal sin obligación de pagarte, y que depende también del país. No te beneficia directamente, pero Lau lo ve como una buena señal: YouTube considera tu canal lo suficientemente seguro para las marcas. Esto lo ves en la clase «Requisitos de monetización».", "silver": false}, {"id": "g6-038", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "Me rechazaron la monetización, ¿se terminó el canal?", "variantes": ["rechazaron mi solicitud de monetización", "no me aprobaron el programa de socios", "qué hago si me rechazan", "puedo volver a postular"], "respuesta": "No se terminó. Max dice que podés apelar, salvo que ya sepas que no cumplís las normas, y que si te rechazan podés volver a intentarlo a los 90 días; ese tiempo lo podés usar para corregir. Hay alumnos que monetizaron después de un rechazo, corrigiendo con feedback. No te adelantes a problemas: decidí en el momento. Esto lo ves en la clase «Requisitos de monetización».", "silver": false, "video": {"id": "wVo2-1folnA", "titulo": "Te quedan 4 meses para MONETIZAR en YouTube con las reglas viejas (plan de 120 días)", "url": "https://www.youtube.com/watch?v=wVo2-1folnA"}}, {"id": "g6-039", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "¿Cómo armo la apelación si me rechazan por contenido reutilizado?", "variantes": ["qué muestro en la apelación", "cómo apelo el rechazo", "video de apelación cómo se hace", "qué le digo a youtube para apelar"], "respuesta": "Lo básico: en la apelación tenés que poder mostrar que hay un proceso humano, con tus guiones, proyectos de edición y cómo hacés las miniaturas; por eso es clave guardar todo desde el día uno. Cómo armar la apelación paso a paso y revisar tu caso lo vemos a fondo en Silver.", "silver": true, "video": {"id": "zC2hfYjWdXI", "titulo": "Miles de CANALES AUTOMATIZADOS de Youtube están siendo eliminados", "url": "https://www.youtube.com/watch?v=zC2hfYjWdXI"}}, {"id": "g6-040", "modulo": "M10", "clase": "Requisitos de monetización", "pregunta": "Mi canal fue desmonetizado hace tiempo, ¿lo vuelvo a postular o hago uno nuevo?", "variantes": ["canal viejo desmonetizado qué hago", "me desmonetizaron, abro otro canal?", "puedo reaplicar un canal suspendido", "arranco de cero con otro canal"], "respuesta": "Depende mucho del motivo. Max explica que no es lo mismo estar desmonetizado por inactividad o por un cambio de políticas que por contenido agresivo o strikes, y que con una sola cuenta de AdSense no podés limpiar el historial. Como cada caso requiere revisar el canal, esto lo vemos a fondo en Silver.", "silver": true}, {"id": "g6-041", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "Un canal está copiando mis videos, ¿qué hago?", "variantes": ["me copiaron el canal", "denunciar un canal que me copia", "otro canal usa mis videos y mi voz", "canal clon de mi canal"], "respuesta": "Lau recomienda moverse rápido: dejar vivo un canal clon es un error, porque compite por tus impresiones y puede confundir a los sistemas automáticos con contenido reutilizado. Si estás seguro de la copia, YouTube tiene herramientas de copyright para reclamar. El paso a paso de derechos de autor lo vemos a fondo en Silver.", "silver": true}, {"id": "g6-042", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "¿Puedo usar fotos de internet o con derechos de autor si las modifico con IA?", "variantes": ["mejoro una foto con ia y la uso", "imágenes de google con copyright", "fair use cómo funciona", "si edito una foto ya es mía?"], "respuesta": "Lau responde que no: si tomás una foto protegida y la mejorás o la expandís con IA, sigue siendo una obra derivada con los derechos del original. Max agrega que las fotos que dicen con licencia están prohibidas. Derechos de autor, Fair Use y dominio público son temas que vemos a fondo en Silver.", "silver": true}, {"id": "g6-043", "modulo": "M9", "clase": "Contenido reutilizado", "pregunta": "YouTube me limitó un video por copyright, ¿lo borro?", "variantes": ["borro el video con copyright", "video limitado qué hago", "elimino o oculto el video", "resubí el video, borro el viejo?"], "respuesta": "Max recomienda no borrarlo sino ponerlo como no listado desde YouTube Studio: Contenido, buscás el video, el lápiz y en visibilidad elegís no listado. Así no aparece en el buscador ni en tu feed. Cuándo conviene borrar, ocultar o dejar un video lo vemos a fondo en Silver.", "silver": true}, {"id": "g6-044", "modulo": "M9", "clase": "Cómo configurarlo", "pregunta": "¿Necesito Multilogin o proxies para mis canales?", "variantes": ["tengo que instalar multilogin", "uso proxies para varios canales", "qué es multilogin", "multilogin antes del primer canal"], "respuesta": "Para arrancar, no. Max aclara que no es necesario si no tenés canales desmonetizados, que va contra las normas de YouTube y es riesgoso a futuro; se usa como último recurso en casos extremos. Cuándo y cómo se usa lo vemos a fondo en Silver.", "silver": true}, {"id": "g6-045", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Qué es AdSense y para qué lo necesito?", "variantes": ["qué es adsense", "cómo me paga youtube", "para qué sirve adsense", "cuándo paga youtube"], "respuesta": "AdSense es la plataforma de Google que te paga. Max lo resume así: YouTube es como Recursos Humanos, el que decide si entrás, y AdSense es el contador, el que te paga. Según la clase, para cobrar tenés que crear y validar tu cuenta, y YouTube paga entre el 21 y el 26 de cada mes lo generado el mes anterior. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-046", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Cuándo tengo que crear la cuenta de AdSense?", "variantes": ["creo adsense antes de monetizar", "necesito adsense para empezar el canal", "en qué momento se crea adsense", "adsense ahora o después"], "respuesta": "No te apures: si todavía no tenés AdSense no pasa nada. Cuando YouTube te acepte en el programa, te va a preguntar si ya tenés una cuenta de AdSense o si querés crearla, y ahí la vinculás. Lo importante desde ya es que el país del canal coincida con el que vas a usar en AdSense. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-047", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "Tengo una cuenta de AdSense vieja, ¿la uso o creo una nueva?", "variantes": ["ya tenía adsense de antes", "puedo usar mi adsense viejo", "creo otra cuenta de adsense", "adsense inactivo sirve", "Ya tengo una cuenta de AdSense vieja, ¿me sirve o creo otra?", "tengo adsense de antes", "¿puedo tener dos adsense?", "¿necesito una adsense nueva?", "tengo una cuenta inactiva de adsense"], "respuesta": "Usá la que tenés. Max lo aclara: solo se puede tener una cuenta de AdSense por persona, así que no crees otra. Cuando llegues a la monetización y YouTube te pregunte si tenés cuenta, decile que sí y poné el ID de esa cuenta para vincularla. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-048", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "Si monetizo un segundo canal, ¿va a la misma cuenta de AdSense?", "variantes": ["dos canales un adsense", "segundo canal qué adsense uso", "varios canales misma cuenta de pago", "si cae un canal cae el otro?", "Si monetizo un segundo canal, ¿va a la misma AdSense?", "¿varios canales en una adsense?", "¿cada canal necesita su adsense?", "tengo dos canales, ¿cómo cobro?", "¿qué pasa si desmonetizan un canal?"], "respuesta": "Sí. Como AdSense permite una sola cuenta por persona, cuando aprueben tu segundo canal le decís que ya tenés una y se enlaza a la misma. Max advierte el riesgo: si un canal cae por infracciones graves, te pueden tumbar los dos, porque quedan relacionados por esa cuenta. Por eso conviene cuidar mucho las normas en todos. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-049", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿El país del canal tiene que coincidir con el de AdSense?", "variantes": ["qué país pongo en el canal", "país de residencia del canal", "el país del canal importa", "pongo el país donde vivo o otro"], "respuesta": "Sí, conviene que coincidan. Max explica que la elegibilidad al Programa de Socios se define por el país que elegís en ese ajuste, y que hay países suspendidos; además define qué leyes locales aplican a tu canal. Lau agrega que tiene que ser el país de tu situación fiscal, el de tu cuenta de AdSense: si no coinciden, puede haber un choque de datos que frene todo al monetizar. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-050", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Puedo poner Estados Unidos como país para ganar más?", "variantes": ["pongo usa para cobrar más", "abro la cuenta con ip de estados unidos", "gano menos por vivir en latinoamérica", "conviene poner otro país"], "respuesta": "Max lo desaconseja: falsear el país puede traerte problemas administrativos en AdSense e incluso desmonetización. Lau explica que lo que define cuánto ganás no es dónde vive tu cuenta sino dónde está tu audiencia. Si querés audiencia que paga más, la vía es hacer el canal en inglés, sin mentir tu ubicación. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-051", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "Todavía no decidí el país, ¿pasa algo si lo cambio después?", "variantes": ["cambio el país del canal más adelante", "puse otro país, lo corrijo?", "país del canal se puede modificar", "no sé qué país poner todavía"], "respuesta": "Si todavía no tenés AdSense, no es urgente: Max dice que da igual por ahora. Lo importante es que, cuando llegues a monetizar, el país del canal coincida con el de AdSense, porque define la elegibilidad al programa. Su consejo es poner tu país real, el de la persona que va a recibir el dinero. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-052", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "Mi país no está habilitado para monetizar, ¿qué país pongo?", "variantes": ["mi país está suspendido en youtube", "no puedo monetizar desde mi país", "pongo el país de un familiar", "quién tiene que recibir el dinero"], "respuesta": "Max explica que hay países suspendidos para el Programa de Socios y que en el canal tenés que poner el país de la persona que va a recibir el dinero, el mismo que figure en AdSense. Como depende de tu situación puntual, revisá la lista oficial de países habilitados de YouTube antes de decidir. Esto lo ves en la clase «Cómo configurarlo».", "silver": false, "video": {"id": "J2c7ha2Tyk8", "titulo": "Cómo GANAR DINERO en YouTube desde países PROHIBIDOS (nadie te lo dice)", "url": "https://www.youtube.com/watch?v=J2c7ha2Tyk8"}}, {"id": "g6-053", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Qué es el PIN de AdSense y cómo llega?", "variantes": ["cómo llega el pin de adsense", "carta de google adsense", "para qué es el pin", "cuánto tarda el pin"], "respuesta": "Es un código que llega en una carta física a tu dirección. Lau explica que sirve para confirmar que la dirección del que cobra es real antes de liberar pagos. Tarda de 2 a 4 semanas; si no llega, podés pedir hasta 3 reenvíos, dejando pasar 3 a 4 semanas entre cada uno. Max cuenta que en algunos países ya se valida con datos biométricos. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-054", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "Pedí el PIN de AdSense varias veces y nunca llegó, ¿qué hago?", "variantes": ["no me llega el pin", "el pin nunca llegó", "ya pedí tres pines", "cómo verifico adsense sin el pin"], "respuesta": "Si ya pasaste el tercer pedido, Max recomienda usar el solucionador de problemas de PIN de AdSense, entrando logueado con tu cuenta. Si no hay respuesta, probá el chat de creadores de YouTube Studio (no todas las cuentas lo tienen) o el soporte por email. Agotados los intentos, se puede verificar de otra forma online. Es frustrante, pero es lo que legitima los pagos. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-055", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Qué pasa si no verifico el PIN a tiempo?", "variantes": ["hay plazo para el pin", "se vence el pin de adsense", "si no pongo el pin qué pasa", "tiempo límite para verificar"], "respuesta": "Ojo con esto. Lau explica que hay una ventana estricta de 4 meses desde que se genera el primer PIN: si la dirección no queda verificada en ese plazo, AdSense suspende los anuncios y los ingresos se detienen. Estate atento a la carta y no lo dejes para último momento. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-056", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Cuándo puedo tocar la plata de AdSense? ¿Hay un mínimo?", "variantes": ["umbral de pago de adsense", "cuánto tengo que juntar para cobrar", "desde cuánto paga adsense", "mínimo para retirar"], "respuesta": "Max cuenta, por su experiencia, que te validan la cuenta pero no te dejan tocar nada hasta llegar a un umbral de 100 USD. Por eso, si es por el dinero, a veces conviene esperar a ese umbral antes de pelearte con la verificación. Revisá las condiciones de pago oficiales de AdSense para tu país. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-057", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Cómo manejo los impuestos de lo que cobro por AdSense?", "variantes": ["tengo que declarar lo de youtube", "impuestos de adsense", "cómo facturo lo de youtube", "retención de impuestos de estados unidos", "¿Cómo manejo los impuestos de lo que cobro de YouTube?", "¿tengo que pagar impuestos?", "¿cómo declaro lo de adsense?", "¿necesito un contador?", "¿qué régimen fiscal elijo?"], "respuesta": "Esto tenés que verlo con un contador o asesor fiscal de tu país. Lau es claro: en SEN6 no podemos dar asesoramiento contable ni legal, porque depende de tu jurisdicción y tu situación. Lo que sí comentó Max, por experiencia, es que YouTube aplica la retención de EE. UU. según las vistas que tengas de ese país. Esto lo ves en la clase «Cómo configurarlo».", "silver": false}, {"id": "g6-058", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "¿Puedo cobrar AdSense con PayPal u otra plataforma?", "variantes": ["cobro con paypal", "qué medios de pago acepta adsense", "cómo recibo la plata", "cuenta bancaria para adsense"], "respuesta": "Hay una lista oficial de medios de pago aceptados por país, así que depende de dónde vivas: revisala en la ayuda de AdSense. Las opciones de cobro y cómo elegir la mejor para tu caso lo vemos a fondo en Silver.", "silver": true}, {"id": "g6-059", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "Vivo en Argentina, ¿cómo cobro AdSense sin pesificar?", "variantes": ["cobrar en dólares desde argentina", "no quiero pesificar adsense", "apps para cobrar youtube", "venezuela cómo cobro adsense"], "respuesta": "Max cuenta que hay alternativas para Argentina y Venezuela con algunas apps que permiten no pesificar los ingresos. Cuáles son, cómo funcionan y cómo configurarlas para tu caso lo vemos a fondo en Silver. Para la parte impositiva, consultalo siempre con un contador de tu país.", "silver": true}, {"id": "g6-060", "modulo": "M10", "clase": "Cómo configurarlo", "pregunta": "AdSense me pide verificar mi identidad, ¿cómo lo hago?", "variantes": ["verificación de identidad adsense", "me piden documento en adsense", "validar identidad manual", "verificación biométrica de adsense"], "respuesta": "Es un paso normal: Max explica que si el PIN no llega tenés que validar tu identidad de forma manual desde tu cuenta de AdSense, y que en algunos países ya se hace con datos biométricos. Es lo que legitima los pagos. El paso a paso de verificación de identidad lo vemos a fondo en Silver.", "silver": true}];
